INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00242','math','初中',0,'jkp-0010','short_answer',0.38,'根据结论完成下列问题： 结论：数轴上两点之间的距离等于相应两数差的绝对值. 问题：（1）数轴上表示3 和8 的两点之间的距离是______ ；数轴上表示-3 和-9 的两点之间的距离是_____ ；数轴上表示2 和-8 的两点之间的距离是_______ ； （2）数轴上表示x 和-2 的两点A 和B 之间的距离是______ ；如果AB=4 ，那 么x 为____ ； （3）当代数式x+1+x-2+x-3取最小值时，相应的x 的值是 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00243','math','初中',0,'jkp-0010','short_answer',0.38,'结合数轴与绝对值的知识回答下列问题： （1 ）探究：①数轴上表示5 和2 的两点之间的距离是 ； ②数轴上表示-2 和-6 的两点之间的距离是 ； ③数轴上表示-4 和3 的两点之间的距离是 ； （2 ）归纳：一般地，数轴上表示数m 和数n 的两点之间的距离等于m-n . （3 ）应用：①如果表示数a 和3 的两点之间的距离是7 ，则可记为：a-3=7 ， 那么a= ； ②若数轴上表示数a 的点位于-4 与3 之间，求a+4+a-3的值； ③当a 取何值时，a+4+a-1+a-3的值最小，最小值是多少？请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
