INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00248','math','初中',0,'jkp-0010','short_answer',0.38,'数轴上两点间的距离等于这两点所对应的数的差的绝对值．例：如图所示， 点A、B 在数轴上分别对应的数为a、b ，则A、B 两点间的距离表示为AB=a-b . 根据以上知识解题： （1）若数轴上两点A、B 表示的数为x、-1 ， ①A、B 之间的距离可用含x 的式子表示为 ； ②若该两点之间的距离为2 ，那么x 值为 . （2 ）x+1+x-2的最小值为 ，此时x 的取值是 ； （3 ）已知（x+1+x-2 ）（y-3+y+2 ）=15 ，求x-2y 的最大值 和最小 值 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00249','math','初中',0,'jkp-0010','short_answer',0.38,'三台生产同一种产品的机器M1、M2、M3 在x 轴上的位置如图所示．M1、 M2、M3生产该产品的效率之比为2 ：1 ：3 ，它们生产的产品都需要沿着x 轴运 送到检验台检验，而移动所需费用与移动的距离成正比．问检验台应该设在x 轴上的何处，才能使移动产品所花费的费用最省？','','','','imported-junior-pdf','approved','通用','基础');
