INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00256','math','初中',0,'jkp-0010','short_answer',0.38,'不相等的有理数a ，b ，c 在数轴上的对应点分别为A ，B ，C ，如果 a-b+b-c=a-c ，那么B 点应为( ) （1）在A ，C 点的右边； （2 ）在A ，C 点的左边； （3 ）在A ，C 点之间； （4）以上三种情况都有可能.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00257','math','初中',0,'jkp-0010','short_answer',0.38,'（1）数轴上两点表示的有理数是a、b ，求这两点之间的距离； （2）是否存在有理数x，使x+1+x-3=x ？ （3）是否存在整数x，使x-4+x-3+x+3+x+4=14？如果存在，求出所有 的整数x ；如果不存在，说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00258','math','初中',0,'jkp-0010','short_answer',0.38,'若x≤1 ，y≤1 且u=x+y+y+1+2y-x-4 ，则umin+umax= .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00259','math','初中',0,'jkp-0010','short_answer',0.38,'认真阅读下面的材料，完成有关问题. 材料：在学习绝对值时，老师教过我们绝对值的几何含义，如5-3表示5、3 在 数轴上对应的两点之间的距离；5+3=5-（-3 ） ，所以5+3表示5、-3 在数 轴上对应的两点之间的距离；5=5-0 ，所以5表示5 在数轴上对应的点到原 点的距离．一般地，点A、B 在数轴上分别表示有理数a、b ，那么A、B 之间的 距离可表示为a-b . 问题（1）：点A、B、C 在数轴上分别表示有理数x、-2、1 ，那么A 到B 的距 离与A 到C 的距离之和可表示为 （用含绝对值的式子表示）. 问题（2 ）：利用数轴探究：①找出满足x-3+x+1=6 的x 的所有值是 ， ②设x-3+x+1=p ，当x 的值取在不小于-1 且不大于3 的范围时，p 的值是不 变的，而且是p 的最小值，这个最小值是 ；当x 的值取在 的范围 时，x+x-2的最小值是 . 问题（3）：求x-3+x-2+x+1的最小值以及此时x 的值. 问题（4）：若x-3+x-2+x+x+1≥a 对任意的实数x 都成立，求a 的取值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00260','math','初中',0,'jkp-0010','short_answer',0.38,'如果实数a 满足：-2014＜a＜0 ，则x-a+x+2014+x-a+2014的最小值 是 .','','','','imported-junior-pdf','approved','通用','基础');
