INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00267','math','初中',0,'jkp-0010','short_answer',0.38,'当a、b 满足什么条件时，下列关系成立： （1）a+b=a+b （2）a+b=a-b（3 ）a-b=a+b（4）a-b=a-b （5 ）a-b=a-b （6）a+b=a-b （7）a+b＞a-b （8 ）a+b＜a-b','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00268','math','初中',0,'jkp-0010','short_answer',0.38,'证明A=x-y+x+y-2z+x-y+x+y+2z=4max{x ，y ，z} ，其中max {x ， y ，z}表示x ，y ，z 这三个数中的最大者．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00269','math','初中',0,'jkp-0010','short_answer',0.38,'将1 ，2 ，… ，100 这100 个正整数任意分成50 组，每组两个数．现将每 组两个数中的一个记为a ，另一个记为b ，代入 中进行计算， 并求出结果．50 组都代入后，可求得50 个值，求这50 个值的和的最大值．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00270','math','初中',0,'jkp-0010','short_answer',0.38,'有一台单功能计算器，对任意两个整数只能完成求差后再取绝对值的运算， 其运算过程是：输入第一个整数x1 ，只显示不运算，接着再输入整数x2 后则显 示x1-x2的结果．比如依次输入1 ，2 ，则输出的结果是1-2=1 ；此后每输入一 个整数都是与前次显示的结果进行求差后再取绝对值的运算． （1）若小明依次输入1 ，2 ，3 ，4 ，则最后输出的结果是 ；若将1 ，2 ， 3 ，4 这4 个整数任意的一个一个的输入，全部输入完毕后显示的结果的最大值 是 ，最小值是 ； （2 ）若随意地一个一个的输入三个互不相等的正整数2 ，a ，b ，全部输入完毕 后显示的最后结果设为k ，k 的最大值为10 ，求k 的最小值．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00271','math','初中',0,'jkp-0010','short_answer',0.38,'从数码1 ，2 ，3 ，4 ，5 ，6 ，7 ，8 ，9 中任选4 个数码，用这四个数码组 成数字最接近的两个两位数，并用d 表示这两个两位数的差的绝对值（例如， 选取数码1 ，2 ，7 ，9 ），则d=27-19=8），这样，任意四个数码就对应一个正 整数d ，求d的最大值．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00272','math','初中',0,'jkp-0010','short_answer',0.38,'有一正整数列1 ，2 ，3 ，… ，2n-1、2n ，现从中挑出n 个数，从大到小 排列依次为a1，a2，… ，an ，另n 个数从小到大排列依次为b1 ，b2，… ，bn ．求 a1-b1+a2-b2+…+an-bn 之所有可能的值．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00273','math','初中',0,'jkp-0010','short_answer',0.38,'证明：①当a＜0 ，b＜0 时，a+b=-a-b ，a-b=a-b 或-a+b ， ∵-a-b＞a-b ，-a-b＞-a+b ，∴a+b＞a-b ； ②当a＜0 ，b≥0 时，a+b=-a+b ，a-b=-a+b ， ∵-a+b=-a+b ，∴a+b=a-b ； ③当a≥0 ，b＜0 时，a+b=a-b ，a-b=a-b ， ∵a-b=a-b ，∴a+b=a-b ； ④当a≥0 ，b≥0 时，a+b=a+b ，a-b=a-b 或-a+b ， ∵a+b≥a-b ，a+b≥-a+b ，∴a+b≥a-b . 综上所述，a+b≥a-b .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00274','math','初中',0,'jkp-0010','short_answer',0.38,'证明：①当a＜0 ，b＜0 时，a-b=-a+b ，a-b=a-b 或-a+b ， ∵-a+b＜a-b ，-a+b=-a+b ，∴a-b≤a-b ； ②当a＜0 ，b≥0 时，a-b=-a-b ，a-b=-a+b ， ∵-a-b≤-a+b ，∴a-b≤a-b ； ③当a≥0 ，b＜0 时，a-b=a+b ，a-b=a-b ， ∵a+b＜a-b ，∴a-b＜a-b ； ④当a≥0 ，b≥0 时，a-b=a-b ，a-b=a-b 或-a+b ， ∵a-b=a-b ，a-b≤-a+b ，∴a-b≤a-b . 综上所述，a-b≤a-b .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00275','math','初中',0,'jkp-0010','short_answer',0.38,'证明：∵a+b+a-b≥a+b+a-b=2a=2a ，∴a+b+a-b≥2a .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00276','math','初中',0,'jkp-0010','short_answer',0.38,'证明：（1）当x≥y ，x≥z 时， A=x-y+x+y-2z+x-y+x+y+2z=2x-2z+2x+2z=4x ； （2 ）当y≥z ，y≥x 时， A=y-x+x+y-2z+y-x+x+y+2z=2y-2z+2y+2z=4y ； （3 ）当z≥x ，z≥y 时，因为x-y+x+y=max{x ，y}≤2z ， 所以A=2z-x-y-x-y+x-y+x+y+2z=4z . 从而A=4max{x ，y ，z} .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00277','math','初中',0,'jkp-0034','short_answer',0.38,'给出下列判断，其中判断正确的是( ) （1 ）在数轴上，原点两旁的两个点所表示的数都是互为相反数； （2 ）仸何正数必定大于它的倒数； （3 ）5ab ， ，都是整式； （4）平方得81 的数是±9 . A . （1 ）（2 ） B . （2 ）（3 ） C . （3 ）（4 ） D . （1 ）（4 ）','','','','imported-junior-pdf','approved','通用','基础');
