INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00457','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（房山区七年级上期末）为防控流感，某校积极进行校园环境消毒，购买了甲、 乙两种消毒液共100 瓶，其中甲种消毒液每瓶6 元，乙种消毒液比甲种消毒液每瓶贵 50%．购买这两种消毒液共用780 元，求甲、乙两种消毒液各购买多少瓶？ 六、 利润问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00458','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（武昌区上学期期末七年级数学）某商品因换季准备打折出售，如果按定价的 七五折出售，将亏25 元；而按定价的九折出售，将赚20 元，则该商品的定价为 （ ） A．230 元 B．275 元 C．300 元 D．325 元','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00459','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（深圳中学初一上期中）天虹商店打折销售中，某件商品打出“1 元换2.5 元电 子券”的促销活动，此活动相当于打几折？（ ） A．2.5 B．4 C．6 D．7.5','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00460','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（河南郑州市初一上期末）商场推出全场打八折的优惠活动，持贵宾卡可在八 折基础上继续打折．小明妈妈持贵宾卡买了标价为10000 元的商品，共节省2800 元， 则她用贵宾卡在八折基础上继续享受________优惠．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00461','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（太原市七年级第二次测评）元旦时，某服装店将一件衣服按成本价提高40% 后标价，又打8 折卖出，结果这件衣服获利24元，这件衣服的成本价是________元','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00462','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（2009 年西安高新一中初一分班数学真卷）小明以8 折优惠买了一双鞋，省了 20 元，那么他买鞋实际付了________元．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00463','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（山东淄博市）家电下乡是我国应对当前国际金融危机，惠农强农，带动工业 生产，促进消费，拉动内需的一项重要举措．国家规定，农民购买家电下乡产品将得 到销售价格13%的补贴资金．今年5 月1 日，甲商场向农民销售某种家电下乡手机20 部．已知从甲商场售出的这20 部手机，国家共发放了2340 元的补贴，若设该手机的 销售价格为x 元，以下方程正确的是 A．20 13% 2340 x  B．20 2340 13% x   C．20 (1 13%) 2340 x   D．13% 2340 x  ','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00464','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（河南郑州市初一上期末、武昌区水果湖第二中学初一上期末） 一家商店将某种服装按成本价提高40%后标价，又以8 折（即按标价的80%）优惠卖 出，结果每件仍获利15 元，这种服装的成本价是多少元？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00465','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（2011-2012 西安西铁一中—七年级数学—期末试卷）某种商品的进价是每件 1000 元，标价是每件1500 元。 ⑴商店要求以利润不低于5%的售价打折出售，售货员最低可以打几折售出此商品？ ⑵为了在十一黄金周获取更多利润，老板决定写上“大酬宾，8 折优惠”进行广告促销， 为了使利润仍不低于5%，最低需多少元标价？ 七、 方案选择问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00466','math','初中',0,'jkp-0041','short_answer',0.38,'【中】（南山外国语初一期末）小明在A．B．C 三家商场发现他看中的电子词典单 价相同，看中的书包单价也相同．电子词典和书包单价之和是452 元，电子词典的单 价是书包单价的4 倍少8 元． ⑴小明看中的电子词典和书包的单价各是多少元？ ⑵周末商家促销，A 商场所有商品打八折销售，B 商场全场购物满100元返购物券30 元销售（不足100元不返券，购物券全场通用）．小明有400 元钱，如果他只能在同 一家商场购买这两样物品，请帮他计算一下，在A、B 两家商场各需要花费多少元钱？ 在哪一家商场购买更省钱？ ⑶若C 商场同个周末的促销方法是全场购物满100元减25 元销售（不足100元不 减）．小明身上也带有400 元钱，那么他在C 商场购买这两样物品需花费多少钱？ （4）请分别计算B、C 两家商场实际相当于所有整百元商品打几折销售？（结果保留 两个有效数字） 八、 行程问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00467','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（房山区2012 七年级上期末）某校操场的环形跑道一圈长400 米.小明练习骑 自行车，平均每分钟骑350 米；小亮练习跑步，平均每分钟跑250 米，两人从同一处 同时反向出发，当他们第二次相遇时所经过的时间是 A．2 3 分 B．2 13 分 C．3 4 分 D．4 3 分','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00468','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（深圳外国语初一上期末）小时候听过龟兔赛跑的故事，都知道乌龟最后占胜 了小白兔．如果在第二次赛跑中，小白兔知耻而后勇，在落后乌龟1km 时，以 10m/min 的速度奋起直追，而乌龟仍然以1m/min 的速度爬行，那么小白兔需要 ________ min 就能追上乌龟．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00469','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（西安陕师大附中初一数学上学期期末测试题）甲、乙、丙3 人，甲每分钟行 60 米，乙每分钟行67.5 米，丙每分钟行75 米，如果甲乙二人在东村，丙在西村，他 们3 人同时由两村相向而行，丙遇到乙后，继续行走10 分钟才遇到甲．问东西两村相 距多少米？ 九、 工程问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00470','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（天津市河西区第一学期七年级期末质量调查数学试卷）整理一批图书，如果 由一个人单独做要花60 小时．现先由一部分人用一小时整理，随后增加15 人和他们 一起又做了两小时，恰好完成整理工作．假设每个人的工作效率相同，那么先安排整 理的同学有多少人？ 十、 几何综合问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00471','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（太原市七年级第二次测评）如图，在水平桌面上有甲、乙两个容器，其内部 呈圆柱形，它们的高相等，内部底面积分别为 2 2 80cm 100cm ， ．其中甲容器装满水， 乙容器是空的．若将甲中的水全部倒入乙中，则乙中的水位高度比原先甲容器中水位 的高度低了8cm，求甲乙两容器的高 十一、 一元一次方程的其它应用','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00472','math','初中',0,'jkp-0041','short_answer',0.38,'【易】（深圳外国语初一上联合测）在一个3 3 方格的每一个方格内填写一个数字， 使各行，各列，以及每一条对角线上的三个数字的和都相等，制成一个三阶幻方，如 图1，现有一个三阶幻方，已知它的4 个方格内的数，如图2，请求出余下的各个方格 内的数，并利用图2 的三阶幻方制成一个所有9 个数之和等于18 的三阶幻方，填写在 图3．（只填图，不要求写过程） 乙 甲 -4 -3 -2 -1 0 4 3 1 2 图1 n-3 n-2 n+2 n 图2 图3','','','','imported-junior-pdf','approved','通用','基础');
