INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00678','math','初中',0,'jkp-0235','short_answer',0.38,'由m（a+b+c ）=ma+mb+mc ，可得：（a+b ）（a2-ab+b2 ） =a3-a2b+ab2+a2b-ab2+b3=a3+b3 ，即（a+b ）（a2-ab+b2 ）=a3+b3…① 我们把等式①叫做多项式乘法的立方和公式. 下列应用这个立方和公式迚行的变形丌正确的是( ) A . （x+4y）（x2-4xy+16y2 ）=x3+64y3B . （2x+y）（4x2-2xy+y2 ）=8x3+y3 C . （a+1 ）（a2+a+1 ）=a3+1 D . x3+27=（x+3 ）（x2-3x+9 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00679','math','初中',0,'jkp-0235','short_answer',0.38,'为了美化城市，经统一规划，将一正方形草坪的南北方向增加3m ，东西 方向缩短3m ，则改造后的长方形草坪面积不原来正方形草坪面积相比( ) A . 增加6m2 B . 增加9m2 C . 减少9m2 D . 保持丌变','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00680','math','初中',0,'jkp-0235','short_answer',0.38,'某商品原价为100 元，现有下列四种调价方案，其中0＜n＜m＜100 ， 则调价后该商品价格最低的方案是( ) A . 先涨价m% ，再降价n% B . 先涨价n% ，再降价m% C . 行涨价 % ，再降价 % D . 先涨价 % ，再降价 %','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00681','math','初中',0,'jkp-0235','short_answer',0.38,'图①是一个边长为（m+n ）的正方形，小颖将图①中的阴影部分拼成图② 的形状，由图①和图②能验证的式子是( ) A . （m+n ）2-（m-n ）2=4mn B . （m+n ）2-（m2+n2 ）=2mn C . （m-n ）2+2mn=m2+n2 D . （m+n ）（m-n ）=m2-n2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00682','math','初中',0,'jkp-0235','short_answer',0.38,'如图所示，在边长为a 的正方形中，剪去一个边长为b 的小正方形（a＞ b ），将余下部分拼成一个梯形，根据两个图形阴影部分面积的关系，可以得到 一个关于a、b 的恒等式为( ) A . （a-b ）2=a2-2ab+b2 B . （a+b ）2=a2+2ab+b2 C . a2-b2=（a+b ）（a-b ） D . a2+ab=a（a+b ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00683','math','初中',0,'jkp-0235','short_answer',0.38,'利用图形中面积的等量关系可以得到某些数学公式．例如，根据图甲，我 们可以得到两数和的平方公式：（a+b ）2=a2+2ab+b2 ．你根据图乙能得到的数 学公式是( ) A . （a+b ）（a-b ）=a2-b2 B . （a-b ）2=a2-2ab+b2 C . a（a+b ）=a2+ab D . a（a-b ）=a2-ab','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00684','math','初中',0,'jkp-0235','short_answer',0.38,'在边长为a 的正方形中挖去一个边长为b 的小正方形（a＞b ）（如图甲）， 把余下的部分拼成一个矩形（如图乙），根据两个图形中阴影部分的面积相等， 可以验证( ) A . （a+b ）2=a2+2ab+b2 B . （a-b ）2=a2-2ab+b2 C . a2-b2=（a+b ）（a-b ） D . （a+2b ）（a-b ）=a2+ab-2b2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00685','math','初中',0,'jkp-0235','short_answer',0.38,'将边长分别为（a+b ）和（a-b ）的两个正方形摆放成如图所示的位置， 则阴影部分的面积化简后的结果是 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00686','math','初中',0,'jkp-0235','short_answer',0.38,'（m+n-p ）（p-m-n ）（m-p-n ）4（p+n-m ）2 等于( ) A . -（m+n-p ）2（p+n-m ）6 B . （m+n-p ）2（m-n-p ）6 C . （-m+n+p ）8 D . -（m+n+p ）8','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00687','math','初中',0,'jkp-0235','short_answer',0.38,'若A=（2+1 ）（22+1 ）（24+1 ）（28+1 ），则A-2003 的末位数字是( ) A . 0 B . 2 C . 4 D . 6','','','','imported-junior-pdf','approved','通用','基础');
