INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00691','math','初中',0,'jkp-0235','short_answer',0.38,'某校数学课外活动探究小组，在老师的引导下迚一步研究了完全平方公 式．结合实数的性质发现以下规律：对于仸意正数a、b ，都有a+b≥2 成立．某 同学在做一个面积为3 600cm2 ，对角线相互垂直的四边形风筝时，运用上述规 律，求得用来作对角线用的竹条至少需要准备xcm ．则x 的值是( ) A . 120 B . 60 C . 120 D . 60','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00692','math','初中',0,'jkp-0235','short_answer',0.38,'如图为杨辉三角表，它可以帮助我们按规律写出（a+b ）n（其中n 为正 整数）展开式的系数，请仔绅观察表中规律，填出（a+b ）4 的展开式中所缺的 系数. （a+b ）1=a+b ； （a+b ）2=a2+2ab+b2 ； （a+b ）3=a3+3a2b+3ab2+b3 ； （a+b ）4=a4+ a3b+ a2b2+ ab3+b4 .','','','','imported-junior-pdf','approved','通用','基础');
