INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00758','math','初中',0,'jkp-0235','short_answer',0.38,'下列选项在用提取公因式法分解因式时，正确的是( ) A . 3x2-9xy=x（3x-9y） B . x3 +2x2+x=x（x2+2x） C . -2x3+2x2-4x=-2x（x2+x-2 ） D . x（x-y）2-y（y-x）2=（x-y）3','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00759','math','初中',0,'jkp-0235','short_answer',0.38,'分解因式a（a-b-c ）+b（c-a+b ）+c（b-a+c ）的结果是( ) A . （b+c-a ）2 B . （a-b-c ）（a+b-c ） C . -（a-b-c）2 D . （a-b-c）2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00760','math','初中',0,'jkp-0235','short_answer',0.38,'下列因式分解正确的是( ) A . mn（m-n ）-m（n-m ）=-m（n-m ）（n+1 ） B . 6（p+q ）2-2（p+q ）=2（p+q ）（3p+q-1 ） C . 3（y-x）2+2（x-y）=（y-x）（3y-3x+2 ） D . 3x（x+y）-（x+y）2 =（x+y）（2x+y）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00761','math','初中',0,'jkp-0235','short_answer',0.38,'下面各式的因式分解中，正确的是( ) A . -7ab-14+49aby=7ab（1-2x+7y） B . -3xmyn +xm+1yn-1=-3xmyn-1（y+3x） C . 6（a-b）2-2（b-a ）=2（a-b ）（3a-3b+1 ） D . xy（x-y）-x（y-x）=x（x-y）（y-1 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00762','math','初中',0,'jkp-0235','short_answer',0.38,'把下列各式因式分解，错误的有( ) ①a2b+7ab-b=b（a2+7a ）； ②3x2y-3xy+6y=3y（x2-x+2 ）； ③8xyz-6x2y2z=2xyz（4-3xyz）； ④-2a2+4ab-6ac=-2a（a+2b-3c ）. A . 1 个 B . 2 个 C . 3 个 D . 4 个','','','','imported-junior-pdf','approved','通用','基础');
