INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00812','math','初中',0,'jkp-0235','short_answer',0.38,'一次课堂练习，小明做了如下4 道因式分解题，你认为小明做得丌够完整 的一题是（ ） A ．x2-2xy+y2=（x-y）2 B ．x2y-xy2=xy（x-y） C ．x3-x=x（x2-1 ） D ．x2-y2 =（x-y）（x+y）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00813','math','初中',0,'jkp-0235','short_answer',0.38,'下列各式的因式分解中，正确的是（ ） A ．3m2-6m=m（3m-6 ） B ．a2b+ab+a=a（ab+b ） C ．-x2+2xy-y2=-（x-y）2 D ．x2 +y2=（x+y）2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00814','math','初中',0,'jkp-0235','short_answer',0.38,'在多项式①a2-b2+2ab ；②1-a+a2 ；③-x+x2 ；④-4x2+12xy-9y2 中能 用完全平方公式分解的有（ ）个． A ．1 B ．2 C ．3 D ．4','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00815','math','初中',0,'jkp-0235','short_answer',0.38,'下列因式分解中正确的是（ ） A ．a4-8a2+16=（a-4 ）2 B ．-a2+a- =- （2a-1 ）2 C ．x（a-b ）-y（b-a ）=（a-b）（x-y）D ．a4-b4=（a2+b2 ）（a2-b2 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-00816','math','初中',0,'jkp-0235','short_answer',0.38,'小明在抄分解因式的题目时，丌小心漏抄了x 的指数，他只知道该数为丌 大于10 的正整数，并且能利用平方差公式分解因式，他抄在作业本上的式子是 x□-4y2（ “□”表示漏抄的指数），则这个指数可能的结果共有（ ） A ．2 种 B ．3 种 C ．4 种 D ．5种','','','','imported-junior-pdf','approved','通用','基础');
