INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01067','math','初中',0,'jkp-0078','short_answer',0.38,'如图，若AB∥CE，下列正确的是( ) A . ∠B = ∠ACB B . ∠B = ∠ACE C . ∠A = ∠ECD D . ∠A = ∠ACE','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01068','math','初中',0,'jkp-0078','short_answer',0.38,'如图，直线AB、CD 相交于点O，OE⊥AB于O，∠COE=55°, 则∠BOD 的度数是( ) A ．40 ° B ． 45 ° C ．30 ° D ．35 °','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01069','math','初中',0,'jkp-0078','short_answer',0.38,'下列说法中，正确的是( ) A ．没有公共点的两线段一定平行 B．如果直线a 与直线b相交，直线b 与c相交，那么，直线a 与c 也 一定相交 C．在同一平面内，两条直线不相交就一定平行 D．不相交的两条直线，就是平行线','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01070','math','初中',0,'jkp-0078','short_answer',0.38,'下列说法不正确的是( ) A ．同位角相等，两直线平行 B．过一点有且只有一条直线与已知直线平行 C．两直线平行，内错角相等 D．同旁内角互补，两直线平行','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01071','math','初中',0,'jkp-0078','short_answer',0.38,'如图，以知：∠1=∠2，那么下列结论正确的是( ) A . ∠C=∠D B ． AD∥BC C ．AB∥C D D . ∠3=∠4','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01072','math','初中',0,'jkp-0078','short_answer',0.38,'如图，AD⊥BC 于D，DE∥AC，那么∠C 与∠ADE 的关系是 ( ) A ．互余 B．互邻 C．相等 D．互补','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01073','math','初中',0,'jkp-0078','short_answer',0.38,'两条直线被第三条直线所截，有一对同旁内角互补，则这一对同 旁内角的平分线( ) A．平行 B．垂直 C．平行或垂直 D．平行或垂直或在同一平面上 A E B C D','','','','imported-junior-pdf','approved','通用','基础');
