INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01075','math','初中',0,'jkp-0078','short_answer',0.38,'如图，∠ACB=90°, CD⊥AB，垂足为D，则点C 到AB 的距离 可用线段（ ）的长度来表示。 A ．CA B．CD C．CB D．AD','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01076','math','初中',0,'jkp-0078','short_answer',0.38,'下列命题中，真命题是( ) A ．互补两角若相等，则此两角都是直角 B．直线是平角 C．不相交的两条直线叫做平行线 D．和为180°的两个角叫做邻补角 F','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01077','math','初中',0,'jkp-0078','short_answer',0.38,'公园里准备修五条甬道，并在甬道交叉路口处设一个报亭，这样 的报亭最多设( ) A ．9 个 B．10 个 C．11 个 D．12 个','','','','imported-junior-pdf','approved','通用','基础');
