INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01079','math','初中',0,'jkp-0078','short_answer',0.38,'下列句子中不是命题的是( ) A.两直线平行，同位角相等。 B.直线AB垂直于CD 吗？ C.若︱a︱=︱b︱，则a2 = b 2。 D.同角的补角相等。','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01080','math','初中',0,'jkp-0078','short_answer',0.38,'一辆汽车在笔直的公路上行驶，两次拐弯后，仍在原来的方向上 平行前进，那么两次拐弯的角度依次是( ) A.第一次右拐50o，第二次左拐130 o B.第一次左拐50o，第二次右拐50 o C.第一次左拐50o，第二次左拐130 o D.第一次右拐50o，第二次右拐50 o','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01081','math','初中',0,'jkp-0078','short_answer',0.38,'下列说法中正确的是( ) A.有且只有一条直线垂直于已知直线 B.从直线外一点到这条直线的垂线段，叫做这点到这条直线距离 C.互相垂直的两条线段一定相交 D.直线c 外一点A 与直线c 上各点连接而成的所有线段中最短线段 的长是3cm，则点A 到直线c 的距离是3cm。','','','','imported-junior-pdf','approved','通用','基础');
