INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01154','math','初中',0,'jkp-0078','short_answer',0.38,'如图所示，直线a∥b，直线c 和直线a、b分别交于C、D 两点 ，点A 、B 分别是直线a、b 上的点，点M 是直线CD 上的一点， 连接AM，BM， （1）若点M在C、D之间，且∠1=25° , ∠3=35° , 求∠2 的度数 ； （2）如果点M 在直线CD 上运动，问∠1、∠2、∠3 之间有怎样的 数量关系？请写出来，不必说明理由.','','','','imported-junior-pdf','approved','通用','基础');
