INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01157','math','初中',0,'jkp-0078','short_answer',0.38,'（1）如图，直线a，b，c 两两相交，∠3=2∠1，∠2=155 °, 求∠4 的度数. （2）如图，直线AB、CD 相交于点O，OE 平分∠BOD，OF 平分 ∠COE，∠AOD：∠BOE=4：1，求∠AOF 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01158','math','初中',0,'jkp-0080','short_answer',0.38,'（2014•铜仁地区）下列图形中，∠1 与∠2 是对顶角的是( ) A. B. C. D.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01159','math','初中',0,'jkp-0080','short_answer',0.38,'（2012 春•鼓楼区校级期中）平面内有两两相交的三条直线，若最多有m 个交点，最少有n 个交点，则m+n 等 于( ) A. 1 B. 2 C. 3 D. 4','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01160','math','初中',0,'jkp-0080','short_answer',0.38,'下列说法正确的是( ) （1）如果∠1+∠2+∠3=180。，那么∠1 与∠2 与∠3 互为补角； （2）如果∠A+∠B=90。，那么∠A 是余角； （3）互为补角的两个角的平分线互相垂直； （4）有公共顶点且又相等的角是对顶角； （5）如果两个角相等，那么它们的余角也相等. A. 1 个 B. 2 个 C. 3 个 D. 4 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01161','math','初中',0,'jkp-0080','short_answer',0.38,'（2014•河南）如图，直线AB，CD 相交于点O，射线OM 平分∠AOC，ON⊥OM，若∠AOM=35。，则∠CON 的度数为( ) A. 35。 B. 45。 C. 55。 D. 65。','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01162','math','初中',0,'jkp-0080','short_answer',0.38,'如图，直线AB、CD 相交于点O ，∠DOE=90。，则∠AOE 与∠DOB 的关系是( ) A. 对顶角 B. 互补的两个角 C. 互余的两个角 D. 一对相等的角','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01163','math','初中',0,'jkp-0080','short_answer',0.38,'如图，直线l 1，l2，l3 相交于一点，则下列答案中，全对的一组是( ) A. ∠1=90。，∠2=30。，∠3=∠4=60。 B. ∠1=∠3=90。，∠2=∠4=30。 C. ∠1=∠3=90° , ∠2=∠4=60° D. ∠1=∠3=90° , ∠2=60° , ∠4=30°','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01164','math','初中',0,'jkp-0080','short_answer',0.38,'（2014•上海）如图，已知直线a 、b 被直线c 所截，那么∠1 的同位角是( ) A. ∠2 B. ∠3 C. ∠4 D. ∠5','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01165','math','初中',0,'jkp-0080','short_answer',0.38,'如图，已知AB⊥MN 于E，下列条件中不能得到CD⊥MN 的是( ) A. CD∥AB B. ∠CFE= ∠AEM C. ∠CFE+∠AEF=180° D. ∠CFE+∠CFN=180°','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01166','math','初中',0,'jkp-0080','short_answer',0.38,'（2014•汕尾）如图，能判定EB∥AC 的条件是( ) A. ∠C=∠ABE B. ∠A=∠EBD C. ∠C=∠ABC D. ∠A=∠ABE','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01167','math','初中',0,'jkp-0080','short_answer',0.38,'（2009 秋•翠屏区期末）已知如图，∠A=135° , ∠B=45° , 在下面的说法中，一定正确的是( ) A. AD∥BC B. AB∥CD C. ∠C=135° , ∠D=45° D. ∠C=45° , ∠D=135°','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01168','math','初中',0,'jkp-0080','short_answer',0.38,'（2007 春•西城区期末）下列命题中，错误的是( ) A. 对顶角的角平分线互为反向延长线 B. 在同一平面内，垂直于同一直线的两条直线互相平行 C. 如果一个角的两边与另一个角的两边分别平行，那么这两个角相等或互补 D. 同时垂直于两条平行线，并且夹在这两条平行线间的线段叫做这两条平行线的距离','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01169','math','初中',0,'jkp-0080','short_answer',0.38,'（2011秋•岳阳楼区校级期末）下列说法中正确的有( ) ①同位角相等. ②凡直角都相等. ③一个角的余角一定比它的补角小. ④在直线、射线和线段中，直线最长. ⑤两点之间的线段的长度就是这两点间的距离. ⑥如果一个角的两边分别平行于另一个角的两边，则这两个角一定相等. A. 0 个 B. 1 个 C. 2 个 D. 3 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01170','math','初中',0,'jkp-0080','short_answer',0.38,'（2011春•灌南县校级期末）如图，下列推理正确的是( ) A. ∵MA∥NB，∴∠1=∠3 B. ∵∠2=∠4 ，∴MC∥ND C. ∵∠1=∠3 ，∴MA∥NB D. ∵MC∥ND ，∴∠1=∠3','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01171','math','初中',0,'jkp-0080','short_answer',0.38,'（2012 春•金台区期末）如图，AB⊥BC，BC⊥CD，∠EBC=∠BCF，则∠ABE 与∠FCD 的关系是( ) A. 同位角且相等 B. 不是同位角但相等 C. 是同位角但不相等 D. 不是同位角也不相等','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01172','math','初中',0,'jkp-0080','short_answer',0.38,'（2013春•下城区期末）如图，AB∥EF∥DC，EG∥DB，则图中与∠1 相等的角(∠1 除外）共有( ) A. 6 个 B. 5 个 C. 4 个 D. 3 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01173','math','初中',0,'jkp-0080','short_answer',0.38,'（2015•河北一模）如图，在五边形ABCDE 中，AB∥DE，若△ABE 的面积为5，则△ABD 的面积为( ) A. 4 B. 5 C. 10 D. 无法判断','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01174','math','初中',0,'jkp-0080','short_answer',0.38,'（2014•安顺）如图，∠AOB 的两边OA，OB 均为平面反光镜，∠AOB=40。．在射线OB 上有一点P，从P 点 射出一束光线经OA 上的Q 点反射后，反射光线QR 恰好与OB 平行，则∠QPB 的度数是( ) A. 60。 B. 80。 C. 100。 D. 120。','','','','imported-junior-pdf','approved','通用','基础');
