INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01247','math','初中',0,'jkp-0080','short_answer',0.38,'如图（1）是长方形纸条，将纸条沿EF 折叠成图（2），再沿AF 折叠成图（3），已知图（3）中的∠CFE=120。， 则图（1）中∠DEF 的度数是 . 三．解答题（共10 小题）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01248','math','初中',0,'jkp-0080','short_answer',0.38,'（2014•益阳）如图，EF∥BC，AC 平分∠BAF，∠B=80。．求∠C 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01249','math','初中',0,'jkp-0080','short_answer',0.38,'如图，请分别根据已知条件进行推理，得出结论，并在括号内注明理由. （1）∵∠2=∠3（已知）， ∴ ∥ ( ) （2）∵∠2=∠5（已知）， ∴ ∥ ( ) （3）∵∠2+∠1=180。（已知）， ∴ ∥ ( ) （4）∵∠5=∠3（已知）， ∴ ∥ ( ) （5）∵∠4+∠6=180。（已知）， ∴ ∥ ( ) （6）∵AB∥CD，AB∥EF（已知）， ∴ ∥ ( )','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01250','math','初中',0,'jkp-0080','short_answer',0.38,'如图，∠PCN=45。，直线CP 与CN 分别交AQ、EF 于点B、D，∠ABC=20。，∠CDE=25。，试说明：AQ∥EF.','','','','imported-junior-pdf','approved','通用','基础');
