INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01252','math','初中',0,'jkp-0080','short_answer',0.38,'如图所示，两平面镜OM、ON 的夹角为∠θ , 入射光线AB 沿着与镜面ON 平行的方向照射到镜面OM 上，经 过两次反射后的反射光线CD 平行于镜面OM，求∠θ的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01253','math','初中',0,'jkp-0080','short_answer',0.38,'如图，已知∠3+∠DCB=180。，∠1=∠2 ，∠CME：∠GEM=4：5，求∠CME 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01254','math','初中',0,'jkp-0080','short_answer',0.38,'如图，已知BDⅡAC，CEⅡBA，且D、A、E 在同一条直线上，设上BAC=x ，上D+上E=y . （1）试用x 的一次式表示y； （2）当x=90。，且上D=2上E 时，DB 与EC 具有怎样的位置关系？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01255','math','初中',0,'jkp-0080','short_answer',0.38,'（1）阅读填空： 如图1 ，ABⅡDE，试问上B、上E、上BCE 有什么关系. 解：上B+上E=上BCE 过点C 作CFⅡAB， 则上B=上1【 】 又“ABⅡDE，ABⅡCF， :CFⅡDE :上E=上2【 】 :上B+上E=上1+上2，即上B+上E=上BCE . （2）应用解答： 观察上面图形与结论，解决下面的问题： 如图2，上DAB+上B+上BCE=360。，作上BCF=上BCG，CF 与上BAH 的平分线交于F，若上F 的余角等于2上B 的 补角，求上BAH 的度数. （3）拓展深化： 如图3 ，在前面的条件下，若点P 是AB 上一点，Q 是GE 上任一点，QR 平分上PQR，PMⅡQR，PN 平分上APQ， 下列结论：①上APQ+上NPM 的值不变；②上NPM 的度数不变，可以证明，只有一个是正确的，请你做出正确的 选择并求值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01256','math','初中',0,'jkp-0080','short_answer',0.38,'（2014•赤峰）如图1 ，E 是直线AB，CD 内部一点，AB∥CD，连接EA，ED. （1）探究猜想： ①若∠A=30° , ∠D=40°, 则∠AED 等于多少度？ ②若∠A=20° , ∠D=60°, 则∠AED 等于多少度？ ③猜想图1 中∠AED，∠EAB，∠EDC 的关系并证明你的结论. （2）拓展应用： 如图2 ，射线FE 与矩形ABCD 的边AB 交于点E ，与边CD 交于点F ，①②③④分别是被射线FE 隔开的4 个区 域（不含边界，其中区域③、④位于直线AB 上方，P 是位于以上四个区域上的点，猜想：∠PEB，∠PFC，∠EPF 的关系（不要求证明）.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01257','math','初中',0,'jkp-0080','short_answer',0.38,'（2007•福州）如图，直线AC∥BD，连接AB，直线AC、BD 及线段AB 把平面分成①、②、③、④四个 部分，规定：线上各点不属于任何部分．当动点P 落在某个部分时，连接PA，PB，构成∠PAC，∠APB，∠PBD 三个角．（提示：有公共端点的两条重合的射线所组成的角是0°角） （1）当动点P 落在第①部分时，求证：∠APB=∠PAC+∠PBD； （2）当动点P 落在第②部分时，∠APB=∠PAC+∠PBD 是否成立？（直接回答成立或不成立） （3）当动点P 落在第③部分时，全面探究∠PAC，∠APB，∠PBD 之间的关系，并写出动点P 的具体位置和相应 的结论．选择其中一种结论加以证明. 相交线与平行线100 题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01258','math','初中',0,'jkp-0059','short_answer',0.38,'手电筒发射出来的光线，给我们的感觉是( ) A ．线段 B ．射线 C ．直线 D ．折线','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01259','math','初中',0,'jkp-0059','short_answer',0.38,'下列语句正确的是( ) A ．画直线AB=10 厘米 B ．画直线l 的垂直平分线 C ．画射线OB=3 厘米 D ．延长线段AB 到点C ，使得BC=AB','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01260','math','初中',0,'jkp-0059','short_answer',0.38,'下列说法正确的是( ) A ．直线AB 和直线BA 是两条直线 B ．射线AB 和射线BA 是两条射线 C ．线段AB 和线段BA 是两条线段 D ．直线AB 和直线a 不能是同一条直线','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01261','math','初中',0,'jkp-0059','short_answer',0.38,'下列图形中，能够相交的是( ) A． B ． C ． D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01262','math','初中',0,'jkp-0059','short_answer',0.38,'如图，小华的家在A 处，书店在B 处，星期日小明到书店去买书，他想尽快 的赶到书店，请你帮助他选择一条最近的路线( ) A ．A⇒C⇒D⇒B B ．A⇒C⇒F⇒B C ．A⇒C⇒E⇒F⇒B D ．A⇒C⇒M⇒B','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01263','math','初中',0,'jkp-0059','short_answer',0.38,'已知O 为圆锥的顶点，M 为圆锥底面上一点，点P 在OM 上．一只蜗牛从 P 点出发，绕圆锥侧面爬行，回到P 点时所爬过的最短路线的痕迹如图所示．若 沿OM 将圆锥侧面剪开并展开，所得侧面展开图是( ) A . B . C . D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01264','math','初中',0,'jkp-0059','short_answer',0.38,'下列四个生活、生产现象： ①用两个钉子就可以把木条固定在墙上； ②植树时，只要定出两棵树的位置，就能确定同一行树所在的直线； ③从A 地到B 地架设电线，总是尽可能沿着线段AB 架设； ④把弯曲的公路改直，就能缩短路程， 其中可用公理“两点之间，线段最短”来解释的现象有 .','','','','imported-junior-pdf','approved','通用','基础');
