INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01268','math','初中',0,'jkp-0059','short_answer',0.38,'往返于甲、乙两地的火车中途要停靠三个站，则有 种不同的票价（来 回票价一样），需准备 种车票.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01269','math','初中',0,'jkp-0059','short_answer',0.38,'在同一平面内，三条直线两两相交，最多有3 个交点，那么4 条直线两两 相交，最多有 个交点，8 条直线两两相交，最多有 个交点.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01270','math','初中',0,'jkp-0059','short_answer',0.38,'一条直线上有若干个点，以任意两点为端点可以确定一条线段，线段的条 数与点的个数之间的对应关系如下表所示．请你探究表内数据间的关系，根据发 现的规律，则表中n= . 点的个数 2 3 4 5 6 7 线段的条数 1 3 6 10 15 n','','','','imported-junior-pdf','approved','通用','基础');
