INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01298','math','初中',0,'jkp-0059','short_answer',0.38,'已知三条线段a、b、c 在同一条直线上，它们有共同的起点，a 的终点是b 的中心，c 的中点是b 的终点，且a+b+c=7cm ，求a、b、c 的长.','','','','imported-junior-pdf','approved','通用','基础');
