INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01302','math','初中',0,'jkp-0059','short_answer',0.38,'已知线段AB=20 ，点P 是直线AB 上一动点，M 是AP 的中点，N 是PB 的中点. （1 ）如图1 ，当点P 在线段AB 上运动时，MN 的长度是否改变？ （2 ）如图2 ，当点P 在线段AB 的延长线上时，MN 的长度是否改变？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01303','math','初中',0,'jkp-0059','short_answer',0.38,'如图所示，C、D 是线段AB 上的两点，AB=a ，CD=b ，M、N、P 分别为 AC、CD、DB 的中点， （1）求AM+CN+DP 的长 （2 ）求AM+PB 的长 （3 ）求PM 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01304','math','初中',0,'jkp-0059','short_answer',0.38,'如图甲，点O 是线段AB 上一点，C、D 两点分别从O、B 同时出发，以 2cm/s、4cm/s 的速度在直线AB 上运动，点C 在线段OA 之间，点D 在线段 OB 之间. （1 ）设C、D 两点同时沿直线AB 向左运动t 秒时，AC ：OD=1 ：2 ，求 的 值； （2）在（1）的条件下，若C、D运动秒后都停止运动，此时恰有OD﹣AC= BD， 求CD 的长； （3 ）在（2 ）的条件下，将线段CD 在线段AB 上左右滑动如图乙（点C 在OA 之间，点D 在OB 之间），若M、N 分别为AC、BD 的中点，试说明线段MN 的长度总不发生变化.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01305','math','初中',0,'jkp-0059','short_answer',0.38,'已知线段AB 和CD 的公共部分BD= AB= CD ，线段AB、CD 的中点E、 F 之间的距离是14cm ，求BD 和AC 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01306','math','初中',0,'jkp-0059','short_answer',0.38,'已知点O 在直线AB 上，且线段OA 的长度为4cm ，线段OB 的长度为6cm ， E、F 分别为线段OA、OB 的中点，则线段EF 的长度为 cm .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01307','math','初中',0,'jkp-0059','short_answer',0.38,'线段MN 上有P、Q 两点，MN=32cm ，MP=17cm ，PQ=6cm ．求NQ 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01308','math','初中',0,'jkp-0059','short_answer',0.38,'已知线段AB=9.6cm ，C 是线段AB 的中点，D 是线段CB 的中点，点E 在 线段AB 上，且CE= AC ，画图并计算DE 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01309','math','初中',0,'jkp-0059','short_answer',0.38,'如图，已知点A、B、C 是数轴上三点，O 为原点．点C对应的数为6，BC=4 ， AB=12 . （1）求点A、B 对应的数； （2 ）动点P、Q 分别同时从A、C 出发，分别以每秒6 个单位和3 个单位的速 度沿数轴正方向运动．M 为AP 的中点，N 在CQ 上，且CN= CQ ，设运动时 间为t（t＞0 ）. ①求点M、N 对应的数（用含t 的式子表示）；②t 为何值时，OM=2BN .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01310','math','初中',0,'jkp-0059','short_answer',0.38,'如图，线段AB=24 ，动点P 从A 出发，以每秒2 个单位的速度沿射线AB 运动，M 为AP 的中点. （1 ）出发多少秒后，PB=2AM ？ （2 ）当P 在线段AB 上运动时，试说明2BM﹣BP 为定值. （3 ）当P 在AB 延长线上运动时，N 为BP 的中点，下列两个结论：①MN 长 度不变；②MA+PN 的值不变．选择一个正确的结论，并求出其值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01311','math','初中',0,'jkp-0059','short_answer',0.38,'如图1 ，直线AB 上有一点P ，点M、N 分别为线段PA、PB 的中点， AB=14 . （1）若点P 在线段AB 上，且AP=8 ，求线段MN 的长度； （2 ）若点P 在直线AB 上运动，试说明线段MN 的长度与点P 在直线AB 上的 位置无关； （3 ）如图2 ，若点C 为线段AB 的中点，点P 在线段AB 的延长线上，下列结 论：① 的值不变；② 的值不变，请选择一个正确的结论并求其值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01312','math','初中',0,'jkp-0059','short_answer',0.38,'（1 ）如图，A、B、C 是三个居住人口数量相同的住宅小区的大门所在位置， 且A、B、C 三点共线，已知AB=120 米，BC=200 米，E、F 分别是AB、BC 的中点，为了方便三个小区的居民出行，公交公司计划在E 点或F 点设一公交停 靠站点，为使从三个小区大门步行到公交停靠点的路程长之和最小，你认为公交 车停靠点的位置应设在哪里，为什么？ （2 ）已知A、B、C 三点在一条直线上，如果AB=a ，BC=b ，且a＜b ，求线段 AB 和BC 的中点E、F 之间的距离. 二、角（共66 题）','','','','imported-junior-pdf','approved','通用','基础');
