INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01349','math','初中',0,'jkp-0059','short_answer',0.38,'如图，已知∠AOB=40° , ∠BOC=80° , 又OD ，OE 分别是∠AOB 和∠BOC 的平分线. （1）图中有 个角； （2 ）求∠DOE 的度数； （3 ）设∠AOB=x ，∠BOC=y ，∠DOE 的度数为 （用含x ，y 的代数式表 示）. （4 ）通过（2 ）、（3 ）的计算，猜想∠DOE= ∠AOC .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01350','math','初中',0,'jkp-0059','short_answer',0.38,'如图，已知O 为AD 上一点，∠AOC 与∠AOB 互补，OM ，ON 分别为∠AOC ， ∠AOB 的平分线，若∠MON=40° ,试求∠AOC 与∠AOB 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01351','math','初中',0,'jkp-0059','short_answer',0.38,'如图，已知直线AB 和CD 相交于点O ，∠COE 是直角，OF 平分∠AOE . （1）写出∠AOC 与∠BOD 的大小关系： ，判断的依据是 ； （2 ）若∠COF=35° ,求∠BOD 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01352','math','初中',0,'jkp-0059','short_answer',0.38,'如图，∠AOB=35°40′ ，∠BOC=50°30′ ，∠DOC=21°18′ ，OE 平分∠AOD ， 求∠BOE 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01353','math','初中',0,'jkp-0059','short_answer',0.38,'如图，如果∠BOC ：∠AOD=2 ：3 ，∠AOB ：∠COD=5 ：2 ，又∠AOB 比其 他三个角的和小10° ,求这四个角的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01354','math','初中',0,'jkp-0059','short_answer',0.38,'如图所示，OE 平分∠AOC ，OF 平分∠BOC ，若∠AOB+∠EOF=156° ,求 ∠EOF 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01355','math','初中',0,'jkp-0059','short_answer',0.38,'如图所示，直线AB ，CD ，EF 都经过点O ，且AB⊥CD ，OG 平分∠BOE ， 如果∠EOG= ∠AOE ，求∠EOG ，∠DOF 和∠AOE 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01356','math','初中',0,'jkp-0059','short_answer',0.38,'如图，已知∠AOE 是平角，∠DOE=20° ,OB 平分∠AOC ，且∠COD ：∠BOC=2 ： 3 ，求∠BOC 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01357','math','初中',0,'jkp-0059','short_answer',0.38,'如图，OM 平分∠AOB、ON 平分∠COD ，若∠AOD=84° , ∠MON=68° , 求∠BOC .','','','','imported-junior-pdf','approved','通用','基础');
