INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01359','math','初中',0,'jkp-0059','short_answer',0.38,'如图，∠BOC﹣∠AOB=20° , ∠BOC ：∠COD ：∠DOA=2 ：3 ：5 ，求∠COD 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01360','math','初中',0,'jkp-0059','short_answer',0.38,'如图，∠AOB、∠COB、∠COD的度数之比是2：1：3，且∠AOC+∠DOB=140° , 求∠AOD 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01361','math','初中',0,'jkp-0059','short_answer',0.38,'如图，∠ACB 是一个平角，∠DCE﹣∠ACD=∠ECF﹣∠DCE=∠FCG﹣ ∠ECF=∠GCB﹣∠FCG=10° ,求∠GCB 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01362','math','初中',0,'jkp-0059','short_answer',0.38,'如图，已知∠COB=n∠AOC（n＞1 ），OD 平分∠AOB . （1）求∠COD 与∠AOB 的比值（用关于n 的式子表示）； （2 ）若∠COD ：∠AOB=1 ：6 ，求n 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01363','math','初中',0,'jkp-0059','short_answer',0.38,'如图，∠AOE=80° , OB 平分∠AOC ，OD 平分∠COE . ∠AOB=15° . （1）求∠COD 度数； （2 ）若OA 表示时钟时针，OD 表示分针，且OA 指在3 点过一点，求此时的 时刻是多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01364','math','初中',0,'jkp-0059','short_answer',0.38,'已知：如图，ON 是∠AOC 的平分线，OM 是∠AOB 的平分线. （1）若∠AOB=90° , ∠AOC=30° ,求∠MON 的大小. （2 ）若∠AOB=α , ∠AOC=β , 试用含α , β的代数式表示∠MON ，并直接写出 ∠MON 与∠BOC 的倍数关系.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01365','math','初中',0,'jkp-0059','short_answer',0.38,'如图1 ，∠AOB=80° , ∠COD=40° , OM 平分∠BOD、ON 平分∠AOC . （1）求∠MON 的度数. （2 ）将图1 中的∠COD 绕点O 旋转至如图2 的位置，求此时∠MON 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01366','math','初中',0,'jkp-0059','short_answer',0.38,'如图，D 为直线AB 上一点，∠BOC=α . （1 ）如图①,若α=40° , OD 平分∠AOC ，∠DOE=90° ,则∠AOE= ； （2 ）如图②,若∠AOD= ∠AOC ，∠DOE=60° ,请用α表示∠AOE 的度数； （3 ）如图③, ∠AOD= ∠AOC ，∠DOE= （n≥2 ，且n 为正整数），请用 α和n 表示∠AOE 的度数．（直接写出结果）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01367','math','初中',0,'jkp-0059','short_answer',0.38,'已知∠AOB=160° , OC 是∠AOB 的一条射线. （1 ）如图①, 如果射线OC 从射线OA 位置开始绕点O 以每秒10°的速度顺时 针旋转，到与OB 重合时停止旋转．那么当射线OC 旋转 秒时，图中出现 直角. （2 ）如图②, 如果OD 是∠COB 内的另一条射线，并且∠COD=30° , OM 平分 ∠AOC ，ON 平分∠BOD ．那么当∠COD 绕顶点O 在∠AOB 内部旋转时，判断 ∠MON 的大小是否发生改变，若不变，求出这个角的度数，若改变，请说明理 由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01368','math','初中',0,'jkp-0059','short_answer',0.38,'如图，0N 是∠BOC 的平分线，OM 是∠AOC 的平分线. （1 ）如果∠AOC=28° , ∠BOC=42° ,那么∠MON 是多少度？ （2 ）如果∠AOB 的大小保持与上图中相同，而射线OC 在∠AOB 的内部绕点O 转动，那么射线OM ，ON 的位置是否发生变化？为什么？ （3 ）∠MON 的大小是否发生变化？如果不变，请说出其度数；如果变化，请 说出变化范围.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01369','math','初中',0,'jkp-0059','short_answer',0.38,'以∠AOB 的顶点O 为端点引射线OC ，使∠AOC ：∠BOC=5 ：4 . （1）若∠AOB=18° . 求∠AOC 与∠BOC 的度数； （2 ）若∠AOB=m° . 求∠AOC 与∠BOC 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01370','math','初中',0,'jkp-0059','short_answer',0.38,'（1 ）已知∠BOC=120° , ∠AOB=70° ,求∠AOC 的大小； （2 ）已知∠AOB=80° ,过O 作射线OC（不同于OA、OB ），满足∠AOC= ∠BOC ， 求∠AOC 的大小. （注：本题中所说的角都是指小于平角的角）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01371','math','初中',0,'jkp-0059','short_answer',0.38,'如图，将一副三角尺的直角顶点重合在一起. （1）若∠DOB 与∠DOA 的比是2 ：11 ，求∠BOC 的度数. （2 ）若叠合所成的∠BOC=n°（0＜n＜90 ），则∠AOD 的补角的度数与∠BOC 的度数之比是多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01372','math','初中',0,'jkp-0059','short_answer',0.38,'将一副三角板如图1 摆放，∠DCE=30 ゜,现将∠DCE 绕C 点以15 ゜/s 的速度逆时针旋转，旋转时间为t（s ）. （1 ）t 为多少时，CD 恰好平分∠BCE ？请在图2 中自己画图，并说明理由. （2 ）当6＜t＜8 时，CM 平分∠ACE ，CN 平分∠BCD ，求∠MCN ，在图3 中完 成. （3 ）当8＜t＜12 时，（2 ）中结论是否发生变化？请在图4 中完成.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01373','math','初中',0,'jkp-0059','short_answer',0.38,'如图，∠AOB=90° , ∠BOC=20° . （1 ）如图1 所示，分别作∠AOC ，∠BOC 的平分线OM ，ON ，求∠MON 的度 数； （2 ）如图2 所示，若将（1 ）中的OC 绕O 点向下旋转，使∠BOC=2x° , 仍然 分别作∠AOC ，∠BOC 的平分线OM ，ON ，能否求出∠MON 的度数？若能， 求出其值；若不能，试说明理由； （3 ）如图3 所示，∠AOB=90° , 若将（1 ）中的0C 绕0 点向上旋转，使0C 在 ∠AOB 的内部，且∠BOC=2y° , 仍然分别作∠AOC ，∠BOC 的平分线OM ，ON ， 还能否求出∠MON 的度数吗？若能，求出其值；若不能，说明理由. 线与角121 题解析 一、线（共55 题）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01374','math','初中',0,'jkp-0160','short_answer',0.38,'（铜仁）如图，△ABC≌△DEF ，BE=4 ，AE=1 ，则DE 的长是( ) A . 5 B . 4 C . 3 D .2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01375','math','初中',0,'jkp-0160','short_answer',0.38,'（凉山州）如图所示，∠E=∠F=90° , ∠B=∠C ，AE=AF ，结论：①EM=FN ； ②CD=DN ；③∠FAN=∠EAM ；④△ACN≌△ABM ．其中正确的有( ) A . 1 个 B . 2 个 C . 3 个 D . 4 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01376','math','初中',0,'jkp-0160','short_answer',0.38,'（西宁）用直尺和圆规作一个角等于已知角的示意图如下，则说明 ∠A′O′B′=∠AOB 的依据是( ) A . （S ．S ．S .) B . （S．A ．S .) C . （A．S ．A .) D . （A．A ．S .)','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01377','math','初中',0,'jkp-0160','short_answer',0.38,'（江西）如图，已知AB=AD ，那么添加下列一个条件后，仍无法判定 △ABC≌△ADC 的是( ) A . ∠BCA=∠DCA B . ∠BAC=∠DAC C . ∠B=∠D=90° D . CB=CD','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01378','math','初中',0,'jkp-0160','short_answer',0.38,'（沈阳）如图所示，正方形ABCD 中，点E 是CD 边上一点，连接AE ，交对 角线BD 于点F ，连接CF ，则图中全等三角形共有( ) A . 1 对 B . 2 对 C . 3 对 D . 4 对 6 ．（成都）如图，在△ABC 与△DEF 中，已有条件AB=DE ，还需添加两个条件 才能使△ABC≌△DEF ，不能添加的一组条件是( ) A . ∠B=∠E ，BC=EF B . BC=EF ，AC=DF C . ∠A=∠D ，∠B=∠E D . ∠A=∠D ，BC=EF','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01379','math','初中',0,'jkp-0160','short_answer',0.38,'（十堰）如图，已知∠1=∠2 ，AC=AD ，增加下列条件：①AB=AE ；②BC=ED ； ③∠C=∠D ；④∠B=∠E ．其中能使△ABC≌△AED 的条件有( ) A . 4 个 B . 3个 C . 2 个 D . 1 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01380','math','初中',0,'jkp-0160','short_answer',0.38,'（临沂）如图：在平行四边形ABCD 中，AB≠BC ，AE、CF 分别为∠BAD、 ∠BCD 的平分线，连接BD ，分别交AE、CF 于点G、H ，则图中的全等三角形 共有( ) A . 3 对 B . 4 对 C . 5对 D . 6 对 9 ．（乌鲁木齐）如图，在△ABC 与△DEF 中，给出以下六个条件： （1 ）AB=DE ；（2 ）BC=EF ；（3 ）AC=DF ；（4 ）∠A=∠D ； （5 ）∠B=∠E ；（6 ）∠C=∠F . 以其中三个作为已知条件，不能判断△ABC 与△DEF 全等的是( ) A . （1 ）（5 ）（2 ）B . （1 ）（2 ）（3 ）C . （4 ）（6 ）（1 ）D . （2 ）（3 ）（4 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01381','math','初中',0,'jkp-0160','short_answer',0.38,'（四川）下列说法中，正确的是( ) A . 两腰对应相等的两个等腰三角形全等 B . 两锐角对应相等的两个直角三角形全等 C . 两角及其夹边对应相等的两个三角形全等 D . 面积相等的两个三角形全等','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01382','math','初中',0,'jkp-0160','short_answer',0.38,'（温州）如图，AC、BD 是长方形ABCD 的对角线，过点D 作DE∥AC 交 BC 的延长线于E ，则图中与△ABC 全等的三角形共有( )','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01383','math','初中',0,'jkp-0160','short_answer',0.38,'（贵港）如图，△ABC 是等腰直角三角形，∠ACB=90° ,AC=BC ，若CD⊥AB ， DE⊥BC 垂足分别是D、E ．则图中全等的三角形共有( ) A . 2 对 B . 3对 C . 4 对 D . 5对','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01384','math','初中',0,'jkp-0160','short_answer',0.38,'（遵义）如图，OA=OB ，OC=OD ，∠O=50° , ∠D=35° , 则∠AEC= ( ) A ．1 个 B ．2 个 C ．3 个 D ．4 个 A . 60° B . 50° C . 45° D . 30°','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01385','math','初中',0,'jkp-0160','short_answer',0.38,'（厦门）如图，在△ABC 和△BDE 中，点C 在边BD 上，边AC 交边BE 于点 F ．若AC=BD ，AB=ED ，BC=BE ，则∠ACB 等于( ) A . ∠EDB B . ∠BED C . ∠AFB D . 2∠ABF','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01386','math','初中',0,'jkp-0160','short_answer',0.38,'（双鸭山）如图所示，已知△ABC 和△DCE 均是等边三角形，点B ，C ，E 在 同一条直线上，AE 与BD 与BD 交于点O ，AE 与CD 交于点G ，AC 与BD 交 于点F ，连接OC ，FG ，其中正确结论的个数是( ) ①AE=BD ；②AG=BF ；③FG ∥BE ；④∠BOC=∠EOC . A . 1 个 B . 2 个 C . 3 个 D . 4 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01387','math','初中',0,'jkp-0160','short_answer',0.38,'（鄂州）如图，已知△ABC 中，∠ABC=45° , AC=4 ，H 是高AD 和BE 的交 点，则线段BH 的长度为( ) A . B . 4 C . D . 5','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01388','math','初中',0,'jkp-0160','short_answer',0.38,'（乌兰察布）如图，已知等边△ABC 中，BD=CE ，AD 与BE 相交于点P ， 则∠APE 的度数为( ) A . 45° B . 60° C . 55° D . 75°','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01389','math','初中',0,'jkp-0160','short_answer',0.38,'（滨州）如图，△ABD 与△ACE 均为正三角形，且AB＜AC ，则BE 与CD 之 间的大小关系是( ) A . BE=CD B . BE＞CD C . BE＜CD D . 大小关系不确定','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01390','math','初中',0,'jkp-0160','short_answer',0.38,'（临沂）如图，将两根钢条AA′、BB′的中点O 连在一起，使AA′、BB′可以 绕着点O 自由转动，就做成了一个测量工件，由三角形全等得出A′B′的长等于 内槽宽AB ；那么判定△OAB≌△OA′B′的理由是( ) A . 边角边 B . 角边角 C . 边边边 D . 角角边','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01391','math','初中',0,'jkp-0160','short_answer',0.38,'（随州）如图，过边长为1 的等边△ABC 的边AB 上一点P ，作PE⊥AC 于E ， Q 为BC 延长线上一点，当PA=CQ 时，连PQ 交AC 边于D ，则DE 的长为 ( ) A . B . C . D . 不能确定','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01392','math','初中',0,'jkp-0160','short_answer',0.38,'（龙岩）如图，在边长为4 的等边三角形ABC 中，AD 是BC 边上的高，点 E ，F 是AD 上的两点，则图中阴影部分的面积是( ) A . 4 B . 3 C . 2 D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01393','math','初中',0,'jkp-0160','short_answer',0.38,'（聊城）如图，在Rt△ABC 中，AB=AC ，AD⊥BC ，垂足为D ．E、F 分别 是CD、AD 上的点，且CE=AF ．如果∠AED=62° , 那么∠DBF= ( ) A . 62° B . 38° C . 28° D . 26°','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01394','math','初中',0,'jkp-0160','short_answer',0.38,'（丽水）如图，已知△ABC 中，∠ABC=90° , AB=BC ，三角形的顶点在相互 平行的三条直线l1 ，l2 ，l3上，且l1 ，l2之间的距离为2 ，l2 ，l3之间的距离为3 ， 则AC 的长是( ) A . B . C . D . 7','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01395','math','初中',0,'jkp-0160','short_answer',0.38,'（綦江县）如图，在▱ABCD 中，分别以AB、AD 为边向外作等边△ABE、△ADF ， 延长CB 交AE 于点G ，点G 在点A、E 之间，连接CE、CF ，EF ，则以下四个 结论一定正确的是( ) ①△CDF≌△EBC；②∠CDF=∠EAF ；③△ECF 是等边三角形；④CG⊥AE . A . 只有①② B . 只有①②③ C . 只有③④ D . ①②③④','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01396','math','初中',0,'jkp-0160','short_answer',0.38,'（重庆）已知：如图，在正方形ABCD 外取一点E ，连接AE、BE、DE ．过 点A 作AE 的垂线交DE 于点P ．若AE=AP=1 ，PB= ．下列结论： ①△APD≌△AEB ；②点B 到直线AE 的距离为√E； ③EB⊥ED ；④S△APD+S△APB=1+ ；⑤S 正方形ABCD=4+ . 其中正确结论的序号是( ) A . ①③④ B . ①②⑤ C . ③④⑤ D . ①③⑤','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01397','math','初中',0,'jkp-0160','short_answer',0.38,'（黄冈）如图，在正方形ABCD 中，点E、F 分别在CD、BC 上，且BF=CE ， 连接BE、AF 相交于点G ，则下列结论不正确的是( ) A . BE=AF B . ∠DAF=∠BEC C . ∠AFB+∠BEC=90° D . AG⊥BE','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01398','math','初中',0,'jkp-0160','short_answer',0.38,'（安顺）如图，在等腰梯形ABCD 中，AD ∥BC ，对角线AC ，BD 相交于点 O ，有如下四个结论： ①AC=BD ；②AC⊥BD ；③等腰梯形ABCD 是中心对称图形；④△AOB≌△DOC . 则正确的结论是( ) A . ①④ B . ②③ C . ①②③ D . ①②③④','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01399','math','初中',0,'jkp-0160','short_answer',0.38,'（包头）如图，已知两个全等直角三角形的直角顶点及一条直角边重合，将 △ABC 绕点C 按顺时针方向旋转到△A′CB′的位置，其中A′C 交直线AD 于点E ， A′B′分别交直线AD ，AC 于点F ，G ．则旋转后的图中，全等三角形共有( ) A . 2 对 B . 3对 C . 4 对 D . 5对','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01400','math','初中',0,'jkp-0160','short_answer',0.38,'（眉山）如图，△ACD 和△AEB 都是等腰直角三角形，∠CAD=∠EAB=90° , 四边形ABCD 是平行四边形，下列结论中错误的是( ) A . △ACE 以点A 为旋转中心，逆时针方向旋转90°后与△ADB 重合 B . △ACB 以点A 为旋转中心，顺时针方向旋转270°后与△DAC 重合 C . 沿AE 所在直线折叠后，△ACE 与△ADE 重合 D . 沿AD 所在直线折叠后，△ADB 与△ADE 重合','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01401','math','初中',0,'jkp-0160','short_answer',0.38,'（临安市）如图直角梯形ABCD 中，AD ∥BC ，AB⊥BC ，∠BCD=45° ,AD=2 ， BC=3 ，将腰CD 以D 为中心逆时针旋转90°至ED ，连AE、CE ，则△ADE 的面 积是( ) A . 1 B . 2 C . 3 D . 不能确定 二、填空题','','','','imported-junior-pdf','approved','通用','基础');
