INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01413','math','初中',0,'jkp-0160','short_answer',0.38,'（保山）如图，▱ABCD 的两条对角线AC、BD 相交于点O . （1 ）图中有哪些三角形是全等的？（2 ）选出其中一对全等三角形进行证明.','','','','imported-junior-pdf','approved','通用','基础');
