INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01416','math','初中',0,'jkp-0160','short_answer',0.38,'（吉林）如图，在△ABC 中，∠ACB=90° , AC=BC ，CE⊥BE ，CE 与AB 相交 于点F ，AD⊥CF 于点D ，且AD 平分∠FAC ，请写出图中两对全等三角形，并 选择其中一对加以证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01417','math','初中',0,'jkp-0160','short_answer',0.38,'（达州）如图所示，将一长方形纸片ABCD 折叠，使点C 与点A 重合，点D 落在点E 处，折痕为MN ，图中有全等三角形吗？若有，请找出并证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01418','math','初中',0,'jkp-0160','short_answer',0.38,'（长春）如图，△ABC 中，AB=AC ，延长BC 至D ，使CD=BC ，点E 在边 AC 上，以CE ，CD 为邻边做▱CDFE ，过点C 作CG∥AB 交EF 于点G ，连接BG ， DE . （1 ）∠ACB 与∠GCD 有怎样的数量关系？请说明理由； （2）求证：△BCG≌△DCE . 9（．丽水）已知命题：如图，点A，D，B，E在同一条直线上，且AD=BE，∠A=∠FDE， 则△ABC≌△DEF ．判断这个命题是真命题还是假命题，如果是真命题，请给出证 明；如果是假命题，请添加一个适当条件使它成为真命题，并加以证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01419','math','初中',0,'jkp-0160','short_answer',0.38,'（吉林）如图，AB=AC ，AD⊥BC 于点D ，AD=AE ，AB 平分∠DAE 交DE 于点F ，请你写出图中三对全等三角形，并选取其中一对加以证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01420','math','初中',0,'jkp-0160','short_answer',0.38,'（宜昌）如图，在△ABC 与△ABD 中，BC=BD ．设点E 是BC 的中点，点F 是BD 的中点. （1 ）请你在图中作出点E 和点F ；（要求用尺规作图，保留作图痕迹，不写作法 与证明） （2 ）连接AE ，AF ．若∠ABC=∠ABD ，请你证明△ABE≌△ABF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01421','math','初中',0,'jkp-0160','short_answer',0.38,'（衢州）如图，AB∥CD . （1 ）用直尺和圆规作∠C 的平分线CP ，CP 交AB 于点E（保留作图痕迹，不写 作法）. （2 ）在（1 ）中作出的线段CE 上取一点F ，连接AF ．要使△ACF≌△AEF ，还需 要添加一个什么条件？请你写出这个条件（只要给出一种情况即可；图中不再增 加字母和线段；不要求证明）.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01422','math','初中',0,'jkp-0160','short_answer',0.38,'（盐城）如图，点C、E、B、F 在同一直线上，AC ∥DF ，AC=DF ，BC=EF ， △ABC 与△DEF 全等吗？证明你的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01423','math','初中',0,'jkp-0160','short_answer',0.38,'（河池）如图所示，在平行四边形ABCD 中，AE⊥BD ，FC⊥BD ，垂足分 别为E ，F . （1 ）写出图中所有的全等三角形； （2 ）选择（1 ）中的任意一对全等三角形进行证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01424','math','初中',0,'jkp-0160','short_answer',0.38,'（大连）如图，在△ABC 中，AB=AC ，点D、E 分别是AB、AC 的中点，点 F 是BE、CD 的交点．请写出图中两组全等的三角形，并选出其中一组加以证 明．（要求：写出证明过程中的重要依据）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01425','math','初中',0,'jkp-0160','short_answer',0.38,'（常州）已知，如图，延长△ABC 的各边，使得BF=AC ，AE=CD=AB ，顺 次连接D ，E ，F ，得到△DEF 为等边三角形．求证： （1 ）△AEF≌△CDE ；（2 ）△ABC 为等边三角形．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01426','math','初中',0,'jkp-0160','short_answer',0.38,'（河南）复习“全等三角形”的知识时，老师布置了一道作业题： “如图①，已知，在△ABC 中，AB=AC ，P 是△ABC 中内任意一点，将AP 绕点 A 顺时针旋转至AQ ，使∠QAP=∠BAC ，连结BQ、CP 则BQ=CP ．” 小亮是个爱动脑筋的同学，他通过对图①的分析，证明了△ABQ≌△ACP ，从而证 得BQ=CP ．之后，他将点P 移到等腰三角形ABC 外，原题中其它条件不变， 发现“BQ=CP”仍然成立，请你就图②给出证明．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01427','math','初中',0,'jkp-0160','short_answer',0.38,'（宁波）如图，△ABC 中，AB=AC ，过点A 作GE ∥BC ，角平分线BD、CF 相交于点H ，它们的延长线分别交GE 于点E、G ．试在图中找出3 对全等三角 形，并对其中一对全等三角形给出证明．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01428','math','初中',0,'jkp-0160','short_answer',0.38,'（金华）如图，在△ABC 中，点D 在AB 上，点E 在BC 上，BD=BE ． （1 ）请你再添加一个条件，使得△BEA≌△BDC ，并给出证明．你添加的条件是 ． ______ （2 ）根据你添加的条件，再写出图中的一对全等三角形 ．（只要求写出 一对全等三角形，不再添加其他线段，不再标注或使用其他字母，不必写出证明 过程）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01429','math','初中',0,'jkp-0160','short_answer',0.38,'（顺义区）已知：如图，AB=AC ，点D 是BC 的中点，AB 平分∠DAE ，AE⊥BE ， 垂足为E ．求证：AD=AE ．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01430','math','初中',0,'jkp-0160','short_answer',0.38,'（绍兴）课外兴趣小组活动时，许老师出示了如下问题：如图1 ，己知四边 形ABCD 中，AC 平分∠DAB ，∠DAB=60° ，∠B 与∠D 互补，求证： AB+AD= AC ．小敏反复探索，不得其解．她想，若将四边形ABCD 特殊化， 看如何解决该问题． （1 ）特殊情况入手添加条件：“∠B=∠D” ，如图2 ，可证AB+AD= AC ；（请 你完成此证明） （2 ）解决原来问题受到（1 ）的启发，在原问题中，添加辅助线：如图3 ，过C 点分别作AB、AD 的垂线，垂足分别为E、F ．（请你补全证明）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01431','math','初中',0,'jkp-0160','short_answer',0.38,'（南充）如图，已知BE⊥AD ，CF⊥AD ，且BE=CF ．请你判断AD 是△ABC 的中线还是角平分线？请说明你判断的理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01432','math','初中',0,'jkp-0160','short_answer',0.38,'（内江）如图，将等腰直角三角形ABC 的直角顶点置于直线l 上，且过A ， B 两点分别作直线l 的垂线，垂足分别为D ，E ，请你在图中找出一对全等三角 形，并写出证明它们全等的过程.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01433','math','初中',0,'jkp-0160','short_answer',0.38,'（漳州）如图，AD ∥BC ，∠A=90° , 以点B 为圆心，BC 长为半径画弧，交 射线AD 于点E ，连接BE ，过点C 作CF⊥BE ，垂足为F ，求证：AB=FC .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01434','math','初中',0,'jkp-0160','short_answer',0.38,'（梧州）如图，AB 是∠DAC 的平分线，且AD=AC ．求证：BD=BC .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01435','math','初中',0,'jkp-0160','short_answer',0.38,'（乐山）如图，AC ∥DE ，BC ∥EF ，AC=DE ．求证：AF=BD . 27 ．（深圳）如图所示、△AOB 和△COD 均为等腰直角三角形， ∠AOB=∠COD=90° , D 在AB 上. （1）求证：△AOC≌△BOD； （2 ）若AD=1 ，BD=2 ，求CD 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01436','math','初中',0,'jkp-0160','short_answer',0.38,'（内江）如图，△ACD 和△BCE 都是等腰直角三角形，∠ACD=∠BCE=90° , AE 交CD 于点F ，BD 分别交CE、AE 于点G、H ．试猜测线段AE 和BD 的数 量和位置关系，并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01437','math','初中',0,'jkp-0160','short_answer',0.38,'（淮安）已知：如图，点C 是线段AB 的中点，CE=CD ，∠ACD=∠BCE ， 求证：AE=BD .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01438','math','初中',0,'jkp-0160','short_answer',0.38,'（德州）如图，点E ，F 在BC 上，BE=CF ，∠A=∠D ，∠B=∠C ，AF 与DE 交于点O . （1 ）求证：AB=DC ； （2 ）试判断△OEF 的形状，并说明理由','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01439','math','初中',0,'jkp-0160','short_answer',0.38,'（楚雄州）如图，点A，E，B，D 在同一直线上，AE=DB，AC=DF，AC∥DF．请 探索BC 与EF 有怎样的位置关系？并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01440','math','初中',0,'jkp-0160','short_answer',0.38,'（黄石）如图，C、F 在BE 上，∠A=∠D ，AC ∥DF ，BF=EC . 求证：AB=DE .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01441','math','初中',0,'jkp-0160','short_answer',0.38,'（赤峰）如图，在四边形ABCD 中，AB=BC ，BF 是∠ABC 的平分线，AF ∥DC ， 连接AC ，CF ．求证：CA 是∠DCF 的平分线.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01442','math','初中',0,'jkp-0160','short_answer',0.38,'（北京）已知：如图，在△ABC 中，∠ACB=90° , CD⊥AB 于点D ，点E 在 AC 上，CE=BC ，过E 点作AC 的垂线，交CD 的延长线于点F . 求证：AB=FC .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01443','math','初中',0,'jkp-0160','short_answer',0.38,'（重庆）已知：如图，在梯形ABCD 中，AD ∥BC ，BC=DC ，CF 平分∠BCD ， DF∥AB ，BF 的延长线交DC 于点E ．求证： （1）△BFC≌△DFC； （2 ）AD=DE .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01444','math','初中',0,'jkp-0160','short_answer',0.38,'（云南）如图，在梯形ABCD 中，AD ∥BC ，AB=DC ，若点M 为线段AD 上任意一点（M 与A、D 不重合）．问：当点M 在什么位置时，MB=MC ，请 说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01445','math','初中',0,'jkp-0160','short_answer',0.38,'（泰安）两个大小不同的等腰直角三角形三角板如图1 所示放置，图2 是由 它抽象出的几何图形，AB=AC ，AE=AD ，∠BAC=∠EAD=90° , B ，C ，E 在同 一条直线上，连接DC . （1 ）请找出图2 中与△ABE 全等的三角形，并给予证明（说明：结论中不得含 有未标识的字母）； （2 ）证明：DC⊥BE . 38（．安徽）已知：点O到△ABC 的两边AB ，AC所在直线的距离相等，且OB=OC . （1 ）如图1 ，若点O 在边BC 上，求证：AB=AC ； （2 ）如图2 ，若点O 在△ABC 的内部，求证：AB=AC ； （3 ）若点O 在△ABC 的外部，AB=AC 成立吗？请画出图表示.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01446','math','初中',0,'jkp-0160','short_answer',0.38,'（张家界）如图，在四边形ABCD 中，AB=AD ，BC=DC ，E 为AC 上的一 动点（不与A 重合），在E 移动过程中BE 和DE 是否相等？若相等，请写出证 明过程；若不相等，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01447','math','初中',0,'jkp-0160','short_answer',0.38,'（南昌）如图，在△ABC 中，D 是AB 上一点，DF 交AC 于点E ，DE=FE ， AE=CE ，AB 与CF 有什么位置关系？证明你的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01448','math','初中',0,'jkp-0160','short_answer',0.38,'（黄冈）如图，分别以Rt△ABC 的直角边AC ，BC 为边，在Rt△ABC 外作两 个等边三角形△ACE 和△BCF ，连接BE ，AF . 求证：BE=AF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01449','math','初中',0,'jkp-0160','short_answer',0.38,'（北京）已知：如图，OP 是∠AOC 和∠BOD 的平分线，OA=OC ，OB=OD ．求 证：AB=CD .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01450','math','初中',0,'jkp-0160','short_answer',0.38,'（岳阳）如图△ADF 和△BCE 中，∠A=∠B ，点D、E、F、C 在同-直线上， 有如下三个关系式：①AD=BC ；②DE=CF ；③BE∥AF . （1 ）请用其中两个关系式作为条件，另一个作为结论，写出所有你认为正确的 命题．（用序号写出命题书写形式，如：如果①、②, 那么③) （2 ）选择（1 ）中你写出的一个命题，说明它正确的理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01451','math','初中',0,'jkp-0160','short_answer',0.38,'（陕西）如图，O 为平行四边形ABCD 的对角线AC 的中点，过点O 作一 条直线分别与AB ，CD 交于点M ，N ，点E ，F 在直线MN 上，且OE=OF . （1 ）图中共有几对全等三角形，请把它们都写出来； （2 ）求证：∠MAE=∠NCF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01452','math','初中',0,'jkp-0160','short_answer',0.38,'（日照）如图，已知，等腰Rt△OAB 中，∠AOB=90° , 等腰Rt△EOF 中， ∠EOF=90° , 连接AE、BF ．求证： （1 ）AE=BF ； （2 ）AE⊥BF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01453','math','初中',0,'jkp-0160','short_answer',0.38,'（内江）如图，在△ABD 和△ACE 中，有下列四个等式： （1 ）AB=AC ；（2 ）AD=AE ；（3 ）∠1=∠2 ；（4 ）BD=CE . 请你以其中三个等式作为题设，余下的作为结论， 写出一个真命题．（要求写出已知，求证及证明过程）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01454','math','初中',0,'jkp-0160','short_answer',0.38,'（海南）如图，四边形ABCD 是正方形，G 是BC 上任意一点（点G 与B、 C 不重合），AE⊥DG 于E ，CF∥AE 交DG 于F . （1 ）在图中找出一对全等三角形，并加以证明； （2 ）求证：AE=FC+EF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01455','math','初中',0,'jkp-0160','short_answer',0.38,'（防城港）如图，在△ABC 和△ABD 中，现给出如下三个论断：①AD=BC ； ②∠C=∠D ；③∠1=∠2 ．请选择其中两个论断为条件，另一个论断为结论，构造 一个命题. （1 ）写出所有的真命题（写成“ ⇒ ”形式，用序号表示）： （2 ）请选择一个真命题加以证明．你选择的真命题是 ⇒ .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01456','math','初中',0,'jkp-0160','short_answer',0.38,'（长春）如图，在正方形ABCD 中，△PBC、△QCD 是两个等边三角形，PB 与DQ 交于M ，BP 与CQ 交于E ，CP 与DQ 交于F ．求证：PM=QM .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01457','math','初中',0,'jkp-0160','short_answer',0.38,'（安徽）如图，已知长方形ABCD ，过点C 引∠A 的平分线AM 的垂线，垂 足为M ，AM 交BC 于E ，连接MB ，MD . （1 ）求证：BE=DC ； （2 ）求证：∠MBE=∠MDC .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01458','math','初中',0,'jkp-0160','short_answer',0.38,'（武汉）如图，在四边形ABCD 中，对角线AC、BD 相交于点O ，已知 ∠ADC=∠BCD ，AD=BC ，求证：AO=BO .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01459','math','初中',0,'jkp-0160','short_answer',0.38,'（广安）某学校花台上有一块形如图所示的三角形ABC 地砖，现已破损．管 理员要对此地砖测量后再去市场加工一块形状和大小与此完全相同的地砖来换， 今只有尺子和量角器，请你帮他设计一个测量方案，使其加工的地砖能符合要求， 并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01460','math','初中',0,'jkp-0160','short_answer',0.38,'（武汉）你一定玩过跷跷板吧！如图是小明和小刚玩跷跷板的示意图，横板 绕它的中点O 上下转动，立柱OC 与地面垂直．当一方着地时，另一方上升到 最高点．问：在上下转动横板的过程中，两人上升的最大高度AA′、BB′有何数 量关系，为什么？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01461','math','初中',0,'jkp-0160','short_answer',0.38,'（韶关）如图，在△ABC 中，AB≠AC ，∠BAC 的外角平分线交直线BC 于D ， 过D 作DE⊥AB ，DF⊥AC 分别交直线AB ，AC 于E ，F ，连接EF . （1 ）求证：EF⊥AD ； （2 ）若DE∥AC ，且DE=1 ，求AD 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01462','math','初中',0,'jkp-0160','short_answer',0.38,'（娄底）如图，在四边形ABCD 中，AD ∥BC ，E 为CD 的中点，连接AE、 BE ，BE⊥AE ，延长AE 交BC 的延长线于点F ．求证： （1 ）FC=AD ；（2 ）AB=BC+AD .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01463','math','初中',0,'jkp-0160','short_answer',0.38,'（宜宾）已知；如图，在△ABC 中，AB=BC ，∠ABC=90 度．F 为AB 延长 线上一点，点E 在BC 上，BE=BF ，连接AE、EF 和CF . （1 ）求证：AE=CF ； （2 ）若∠CAE=30° , 求∠EFC 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01464','math','初中',0,'jkp-0160','short_answer',0.38,'（中原区）已知：如图，在Rt△ABC 中，∠C=90° , 沿过B 点的一条直线BE 折叠这个三角形，使C 点与AB 边上的一点D 重合．当∠A 为多少时，点D 恰 为AB 的中点？写出一个你认为适当的角度，并利用此角的大小证明D 为AB 的 中点.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01465','math','初中',0,'jkp-0160','short_answer',0.38,'（河南）如图，四边形ABCD 是平行四边形，△AB′C 和△ABC 关于AC 所在 的直线对称，AD 和B′C 相交于点O ，连接BB′ . （1 ）请直接写出图中所有的等腰三角形（不添加字母）； （2）求证：△AB′O≌△CDO .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01466','math','初中',0,'jkp-0160','short_answer',0.38,'（南充）已知：如图，OA 平分∠BAC ，∠1=∠2 ．求证：△ABC 是等腰三角 形.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01467','math','初中',0,'jkp-0160','short_answer',0.38,'（莱芜）两个全等的含30° , 60°角的三角板ADE 和三角板ABC 如图所示放 置，E，A ，C 三点在一条直线上，连接BD，取BD的中点M，连接ME，MC．试 判断△EMC 的形状，并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01468','math','初中',0,'jkp-0160','short_answer',0.38,'（常德）如图，P 是等边三角形ABC 内的一点，连接PA ，PB ，PC ，以BP 为边作∠PBQ=60° , 且BQ=BP ，连接CQ . （1 ）观察并猜想AP 与CQ 之间的大小关系，并证明你的结论； （2 ）若PA ：PB ：PC=3 ：4 ：5 ，连接PQ ，试判断△PQC 的形状，并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01469','math','初中',0,'jkp-0160','short_answer',0.38,'（江西）如图，△ABC 是等边三角形，点D、E、F 分别是线段AB、BC、CA 上的点， （1 ）若AD=BE=CF ，问△DEF 是等边三角形吗？试证明你的结论； （2 ）若△DEF 是等边三角形，问AD=BE=CF 成立吗？试证明你的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01470','math','初中',0,'jkp-0160','short_answer',0.38,'（上海模拟）如图，在△ABC 中，点D 在边AC 上，DB=BC ，点E 是CD 的 中点，点F 是AB 的中点. （1 ）求证：EF= AB ； （2 ）过点A 作AG∥EF ，交BE 的延长线于点G ，求证：△ABE≌△AGE .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01471','math','初中',0,'jkp-0160','short_answer',0.38,'（自贡）已知：三角形ABC 中，∠A=90° , AB=AC ，D 为BC 的中点， （1 ）如图，E ，F 分别是AB ，AC 上的点，且BE=AF ，求证：△DEF 为等腰直 角三角形； （2 ）若E ，F 分别为AB ，CA 延长线上的点，仍有BE=AF ，其他条件不变，那 么，△DEF 是否仍为等腰直角三角形？证明你的结论. 65（．大田县）如图所示，△ACB和△ECD都是等腰直角三角形，∠ACB=∠ECD=90° , D 为AB 边上一点. （1）求证：△ACE≌△BCD； （2 ）若AD=5 ，BD=12 ，求DE 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01472','math','初中',0,'jkp-0160','short_answer',0.38,'（内江）如图，△ACB 和△ECD 都是等腰直角三角形，A ，C ，D 三点在同一 直线上，连接BD ，AE ，并延长AE 交BD 于F . （1）求证：△ACE≌△BCD； （2 ）直线AE 与BD 互相垂直吗？请证明你的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01473','math','初中',0,'jkp-0160','short_answer',0.38,'（宿迁）已知如图，在▱ABCD 中，E、F 是对角线AC 上的两点，且AE=CF . 求证：∠ADF=∠CBE .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01474','math','初中',0,'jkp-0160','short_answer',0.38,'（潍坊）如图，四边形ABCD 为平行四边形，AD=2 ，BE∥AC ，DE 交AC 的延长线于F 点，交BE 于E 点. （1 ）求证：EF=DF ； （2 ）若AC=2CF ，∠ADC=60° , AC⊥DC ，求DE 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01475','math','初中',0,'jkp-0160','short_answer',0.38,'（昆明）己知：如图，点P 为平行四边形ABCD 中CD 边的延长线上一点， 连接BP，交AD，于点E，探究：当PD与CD有什么数量关系时，△ABE≌△DPE．画 出图形并证明△ABE≌△DPE .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01476','math','初中',0,'jkp-0160','short_answer',0.38,'（梅州）如图，AC 是平行四边形ABCD 的对角线. （1 ）请按如下步骤在图中完成作图（保留作图痕迹）： ①分别以A ，C 为圆心，以大于AC 长为半径画弧，弧在AC 两侧的交点分别为 P ，Q . ②连接PQ ，PQ 分别与AB ，AC ，CD 交于点E ，O ，F ； （2 ）求证：AE=CF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01477','math','初中',0,'jkp-0160','short_answer',0.38,'（德阳）如图，已知平行四边形ABCD 中，点E 为BC 边的中点，延长DE ， AB 相交于点F . 求证：CD=BF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01478','math','初中',0,'jkp-0160','short_answer',0.38,'（厦门）如图，在平行四边形ABCD 中，E、F 分别是AB、CD 上的点，且 ∠DAF=∠BCE . （1）求证：△DAF≌△BCE； （2 ）若∠ABC=60° , ∠ECB=20° , ∠ABC 的平分线BN 交AF 与M ，交AD 于 N ，求∠AMN 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01479','math','初中',0,'jkp-0160','short_answer',0.38,'（莆田）已知：如图在平行四边形ABCD 中，过对角线BD 的中点O 作直 线EF 分别交DA 的延长线、AB、DC、BC 的延长线于点E、M、N、F . （1 ）观察图形并找出一对全等三角形：△ ≌△ , 请加以证明； （2 ）在（1 ）中你所找出的一对全等三角形，其中一个三角形可由另一个三角 形经过怎样的变换得到？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01480','math','初中',0,'jkp-0160','short_answer',0.38,'（衢州）已知：如图，E、F 是平行四边形ABCD 的对角线AC 上的两点， AE=CF . 求证：（1 ）△ADF≌△CBE；（2 ）EB∥DF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01481','math','初中',0,'jkp-0160','short_answer',0.38,'（黔东南州）如图，在平行四边形ABCD 中，过A、C 分别作对角线的垂线， 垂足分别为E、F . （1 ）图中有哪几对三角形全等请指出来； （2 ）求证：AE=CF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01482','math','初中',0,'jkp-0160','short_answer',0.38,'（长春）如图，在平行四边形ABCD 中，E 为BC 边上一点，且AB=AE . （1）求证：△ABC≌△EAD； （2 ）若AE 平分∠DAB ，∠EAC=25° , 求∠AED 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01483','math','初中',0,'jkp-0160','short_answer',0.38,'（泸州）如图，在矩形ABCD 中，点E 是BC 上一点，AE=AD ，DF⊥AE ， 垂足为F ．线段DF 与图中的哪一条线段相等？先将你猜想出的结论填写在下面 的横线上，然后再加以证明．即DF= ．（写出一条线段即可）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01484','math','初中',0,'jkp-0160','short_answer',0.38,'（嘉兴）如图，矩形ABCD 中，M 是CD 的中点．求证： （1 ）△ADM≌△BCM ；（2 ）∠MAB=∠MBA .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01485','math','初中',0,'jkp-0160','short_answer',0.38,'（潼南县）如图，四边形ABCD 是边长为2 的正方形，点G 是BC 延长线上 一点，连接AG ，点E、F 分别在AG 上，连接BE、DF ，∠1=∠2 ，∠3=∠4 . （1）证明：△ABE≌△DAF； （2 ）若∠AGB=30° , 求EF 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01486','math','初中',0,'jkp-0160','short_answer',0.38,'（陕西）如图，A、B、C 三点在同一条直线上，AB=2BC ，分别以AB ，BC 为边做正方形ABEF 和正方形BCMN 连接FN ，EC . 求证：FN=EC .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01487','math','初中',0,'jkp-0160','short_answer',0.38,'（青海）如图，正方形ABCD 的对角线AC 和BD 相交于点O ，O 又是正方 形A1B1C1O 的一个顶点，O A1 交AB 于点E ，OC1 交BC 于点F . （1）求证：△AOE≌△BOF； （2 ）如果两个正方形的边长都为a ，那么正方形A1B1C1O 绕O 点转动，两个 正方形重叠部分的面积等于多少？为什么？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01488','math','初中',0,'jkp-0160','short_answer',0.38,'（随州）如图，一个含45°的三角板HBE 的两条直角边与正方形ABCD 的 两邻边重合，过E 点作EF⊥AE 交∠DCE 的角平分线于F 点，试探究线段AE 与 EF 的数量关系，并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01489','math','初中',0,'jkp-0160','short_answer',0.38,'（长沙）在正方形ABCD 中，AC 为对角线，E 为AC 上一点，连接EB、ED . （1）求证：△BEC≌△DEC； （2 ）延长BE 交AD 于F ，当∠BED=120°时，求∠EFD 的度数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01490','math','初中',0,'jkp-0160','short_answer',0.38,'（崇左）如图，在正方形ABCD 中，点E、F 分别在BC、CD 上移动，但A 到EF 的距离AH 始终保持与AB 长相等，问在E、F 移动过程中： （1 ）∠EAF 的大小是否有变化？请说明理由. （2 ）△ECF 的周长是否有变化？请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01491','math','初中',0,'jkp-0160','short_answer',0.38,'（资阳）如图，已知四边形ABCD、AEFG 均为正方形，∠BAG=α（0° < α ＜180° ) . （1 ）求证：BE=DG ，且BE⊥DG ； （2 ）设正方形ABCD、AEFG 的边长分别是3 和2 ，线段BD、DE、EG、GB 所围成封闭图形的面积为S ．当α变化时，指出S 的最大值及相应的α值．（直接 写出结果，不必说明理由）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01492','math','初中',0,'jkp-0160','short_answer',0.38,'（湘潭）如图，B ，C ，E 是同一直线上的三个点，四边形ABCD 与四边形 CEFG 都是正方形，连接BG ，DE . （1 ）观察图形，猜想BG 与DE 之间的大小关系，并证明你的结论； （2 ）若延长BG 交DE 于点H ，求证：BH⊥DE .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01493','math','初中',0,'jkp-0160','short_answer',0.38,'（南充）如图，ABCD 是正方形，点G 是BC 上的任意一点，DE⊥AG 于E ， BF ∥DE ，交AG 于F . 求证：AF=BF+EF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01494','math','初中',0,'jkp-0160','short_answer',0.38,'（佛山）如图，在正方形ABCD 中，CE⊥DF ．若CE=10cm ，求DF 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01495','math','初中',0,'jkp-0160','short_answer',0.38,'（肇庆）如图，在等腰Rt△ABC 中，∠C=90° , 正方形DEFG 的顶点D 在边 AC 上，点E、F 在边AB 上，点G 在边BC 上. （1 ）求证：AE=BF ； （2 ）若BC= cm ，求正方形DEFG 的边长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01496','math','初中',0,'jkp-0160','short_answer',0.38,'（丽水）如图，正方形ABCD 中，E 与F 分别是AD ，BC 上一点．在①AE=CF ， ②BE ∥DF ，③∠1=∠2 中，请选择其中一个条件，证明BE=DF . （1 ）你选择的条件是 （只需填写序号）. （2 ）证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01497','math','初中',0,'jkp-0160','short_answer',0.38,'（肇庆）如图，已知点E 为正方形ABCD 的边BC 上一点，连接AE ，过点 D 作DG⊥AE ，垂足为G ，延长DG 交AB 于点F ．求证：BF=CE .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01498','math','初中',0,'jkp-0160','short_answer',0.38,'（茂名）如图，已知正方形ABCD 的边长是2 ，E 是AB 的中点，延长BC 到点F 使CF=AE . （1 ）若把△ADE 绕点D 旋转一定的角度时，能否与△CDF 重合？请说明理由. （2 ）现把△DCF 向左平移，使DC 与AB 重合，得△ABH ，AH 交ED 于点G ．求 证：AH⊥ED ，并求AG 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01499','math','初中',0,'jkp-0160','short_answer',0.38,'（淮安）如图，在矩形ABCD 中，AE 平分∠DAB 交DC 于点E ，连接BE ， 过E 作EF⊥BE 交AD 于E . （1 ）求证：∠DEF=∠CBE ； （2 ）请找出图中与EB 相等的线段（不另添加辅助线和字母），并说明理由. 94（长春）在等腰梯形ABCD 中，AD ∥BC ，∠C=60° , AD=CD ，E、F 分别在 AD、CD 上，DE=CF ，AF、BE 交于点P ．请你量一量∠BPF 的度数，并证明你 的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01500','math','初中',0,'jkp-0160','short_answer',0.38,'（梅州）用两个全等的正方形ABCD 和CDFE 拼成一个矩形ABEF ，把一个 足够大的直角三角尺的直角顶点与这个矩形的边AF 的中点D 重合，且将直角三 角尺绕点D 按逆时针方向旋转. （1 ）当直角三角尺的两直角边分别与矩形ABEF 的两边BE ，EF 相交于点G ，H 时，如图甲，通过观察或测量BG 与EH 的长度，你能得到什么结论并证明你的 结论； （2 ）当直角三角尺的两直角边分别与BE 的延长线，EF 的延长线相交于点G ， H 时（如图乙），你在图甲中得到的结论还成立吗？简要说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01501','math','初中',0,'jkp-0160','short_answer',0.38,'（临沂）如图1 ，已知正方形ABCD 的对角线AC、BD 相交于点O ，E 是 AC 上一点，连接EB ，过点A 作AM⊥BE ，垂足为M ，AM 交BD 于点F . （1 ）求证：OE=OF ； （2 ）如图2 ，若点E 在AC 的延长线上，AM⊥BE 于点M ，交DB 的延长线于 点F ，其它条件不变，则结论“OE=OF”还成立吗？如果成立，请给出证明； 如果不成立，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01502','math','初中',0,'jkp-0160','short_answer',0.38,'（锦州）如图，△ABC 是等腰直角三角形，其中CA=CB ，四边形CDEF 是 正方形，连接AF、BD . （1 ）观察图形，猜想AF 与BD 之间有怎样的关系，并证明你的猜想； （2 ）若将正方形CDEF 绕点C 按顺时针方向旋转，使正方形CDEF 的一边落在 △ABC 的内部，请你画出一个变换后的图形，并对照已知图形标记字母，题（1 ） 中猜想的结论是否仍然成立？若成立，直接写出结论，不必证明；若不成立，请 说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01503','math','初中',0,'jkp-0160','short_answer',0.38,'（岳阳）如图，已知正方形ABCD ，把一个直角与正方形叠合，使直角顶点 与A 重合，两边分别与AB、AD 重合．将直角绕点A 按逆时针方向旋转，当直 角的一边与BC 相交于E 点，另一边与CD 的延长线相交于F 点时，作∠EAF 的 平分线交CD 于G ，连接EG . 求证：（1 ）BE=DF ；（2 ）BE+DG=EG .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01504','math','初中',0,'jkp-0160','short_answer',0.38,'（宜昌）在梯形ABCD 中，AD ∥BC ，AB=CD ，E 为AD 中点. （1）求证：△ABE≌△DCE； （2 ）若BE 平分∠ABC ，且AD=10 ，求AB 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01505','math','初中',0,'jkp-0160','short_answer',0.38,'（深圳）如图，在梯形ABCD 中，AD ∥BC ，EA⊥AD ，M 是AE 上一点， ∠BAE=∠MCE ，∠MBE=45° . （1 ）求证：BE=ME ； （2 ）若AB=7 ，求MC 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01506','math','初中',0,'jkp-0160','short_answer',0.38,'（湘潭）如图，梯形ABCD ，AB ∥DC ，AD=DC=CB ，AD、BC 的延长线 相交于G ，CE⊥AG 于E ，CF⊥AB 于F . （1 ）请写出图中4 组相等的线段（已知的相等线段除外）； （2 ）从你写出的4 组相等的线段中选一组加以证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01507','math','初中',0,'jkp-0160','short_answer',0.38,'（北京）已知：如图，在梯形ABCD 中，AD ∥BC ，AB=DC ，点E、F 分别 在AB、DC 上，且BE=2EA ，CF=2FD ．求证：∠BEC=∠CFB .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01508','math','初中',0,'jkp-0160','short_answer',0.38,'（重庆）已知：如图，在直角梯形ABCD 中，AD ∥BC ，∠ABC=90° . 点E 是DC 的中点，过点E 作DC 的垂线交AB 于点P ，交CB 的延长线于点M ．点 F 在线段ME 上，且满足CF=AD ，MF=MA . （1 ）若∠MFC=120° , 求证：AM=2MB ； （2 ）求证：∠MPB=90°- ∠FCM .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01509','math','初中',0,'jkp-0160','short_answer',0.38,'（盐城）如图1 所示，在直角梯形ABCD 中，AD ∥BC ，AB⊥BC ，∠DCB=75° , 以CD 为一边的等边△DCE 的另一顶点E 在腰AB 上. （1 ）求∠AED 的度数； （2 ）求证：AB=BC ； （3 ）如图2 所示，若F 为线段CD 上一点，∠FBC=30° , 求 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01510','math','初中',0,'jkp-0160','short_answer',0.38,'（泰安）如图所示，在直角梯形ABCD 中，∠ABC=90° , AD ∥BC ，AB=BC ， E 是AB 的中点，CE⊥BD . （1 ）求证：BE=AD ； （2 ）求证：AC 是线段ED 的垂直平分线； （3 ）△DBC 是等腰三角形吗？并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01511','math','初中',0,'jkp-0160','short_answer',0.38,'（北京）问题：已知△ABC 中，∠BAC=2∠ACB ，点D 是△ABC 内的一点， 且AD=CD ，BD=BA ．探究∠DBC 与∠ABC 度数的比值. 请你完成下列探究过程： 先将图形特殊化，得出猜想，再对一般情况进行分析并加以证明. （1 ）当∠BAC=90°时，依问题中的条件补全右图； 观察图形，AB 与AC 的数量关系为 ；当推出∠DAC=15°时，可进一步推 出∠DBC 的度数为 ；可得到∠DBC 与∠ABC 度数的比值为 ； （2 ）当∠BAC＜90°时，请你画出图形，研究∠DBC 与∠ABC 度数的比值是否与 （1 ）中的结论相同，写出你的猜想并加以证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01512','math','初中',0,'jkp-0160','short_answer',0.38,'（乐山）如图，在等腰梯形ABCD 中，AD ∥BC ，G 是边AB 上的一点，过 点G 作GE∥DC 交BC 边于点E ，F 是EC 的中点，连接GF 并延长交DC 的延长 线于点H ．求证：BG=CH .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01513','math','初中',0,'jkp-0160','short_answer',0.38,'（桂林）如图，在等腰梯形ABCD 中，AD ∥BC ，对角线AC、BD 相交于 点O . （1 ）图中共有 对全等三角形； （2 ）写出你认为全等的一对三角形，并证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01514','math','初中',0,'jkp-0160','short_answer',0.38,'（湛江）如图所示，已知等腰梯形ABCD 中，AD ∥BC ，AB=DC ，AC 与 BD 相交于点O ．请在图中找出一对全等的三角形，并加以证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01515','math','初中',0,'jkp-0160','short_answer',0.38,'（遵义）如图所示，在等腰梯形ABCD 中，AD ∥BC ，DE⊥BC 于点E ，BF⊥AE 于点F ，请你添加一个条件，使△ABF≌△CDE . （1 ）你添加的一个条件是 ； （2 ）请写出证明过程.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01516','math','初中',0,'jkp-0160','short_answer',0.38,'（郴州）如图，在等腰梯形ABCD 中，AD ∥BC ，AB=DC ，点E 是BC 边 的中点，EM⊥AB ，EN⊥CD ，垂足分别为M、N . 求证：EM=EN .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01517','math','初中',0,'jkp-0160','short_answer',0.38,'（钦州）已知：如图，在等腰梯形ABCD 中，AB∥CD ，点E、F 分别在AD、 BC 上，且DE=CF . 求证：AF=BE .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01518','math','初中',0,'jkp-0160','short_answer',0.38,'（沈阳）如图，已知在梯形ABCD 中，AD ∥BC ，AB=DC ，对角线AC 和 BD 相交于点O ，E 是BC 边上一个动点（E 点不与B、C 两点重合），EF∥BD 交 AC 于点F ，EG∥AC 交BD 于点G . （1 ）求证：四边形EFOG 的周长等于2 OB ； （2 ）请你将上述题目的条件“梯形ABCD 中，AD ∥BC ，AB=DC”改为另一种 四边形，其他条件不变，使得结论“四边形EFOG 的周长等于2 OB”仍成立， 并将改编后的题目画出图形，写出已知、求证、不必证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01519','math','初中',0,'jkp-0160','short_answer',0.38,'（伊春）如图，将矩形纸片ABCD 沿对角线AC 折叠，使点B 落到点B′的 位置，AB′与CD 交于点E . （1 ）试找出一个与△AED 全等的三角形，并加以证明； （2 ）若AB=8 ，DE=3 ，P 为线段AC 上的任意一点，PG⊥AE 于G ，PH⊥EC 于H ，试求PG+PH 的值，并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01520','math','初中',0,'jkp-0160','short_answer',0.38,'（镇江）如图，在△ABC 和△ADE 中，点E 在BC 边上，∠BAC=∠DAE ， ∠B=∠D ，AB=AD . （1）求证：△ABC≌△ADE； （2 ）如果∠AEC=75° , 将△ADE 绕着点A 旋转一个锐角后与△ABC 重合，求这 个旋转角的大小.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01521','math','初中',0,'jkp-0160','short_answer',0.38,'（崇左）如图所示，正方形ABCD 中，E 是CD 上一点，F 在CB 的延长线 上，且DE=BF . （1）求证：△ADE≌△ABF； （2 ）问：将△ADE 顺时针旋转多少度后与△ABF 重合，旋转中心是什么？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01522','math','初中',0,'jkp-0160','short_answer',0.38,'（牡丹江）平面内有一等腰直角三角板( ∠ACB=90° ) 和一直线MN ．过 点C 作CE⊥MN 于点E ，过点B 作BF⊥MN 于点F ．当点E 与点A 重合时（如 图1 ），易证：AF+BF=2CE ．当三角板绕点A 顺时针旋转至图2、图3 的位置 时，上述结论是否仍然成立？若成立，请给予证明；若不成立，线段AF、BF、 CE 之间又有怎样的数量关系，请直接写出你的猜想，不需证明. 118（．鸡西）已知Rt△ABC 中，AC=BC ，∠C=90° ,D 为AB 边的中点，∠EDF=90° , ∠EDF 绕D 点旋转，它的两边分别交AC、CB（或它们的延长线）于E、F . （1 ）当∠EDF 绕D 点旋转到DE⊥AC 于E 时（如图1 ），易证S△DEF+S△CEF= S△ABC； （2 ）当∠EDF 绕D 点旋转到DE 和AC 不垂直时，在图2 和图3 这两种情况下， 上述结论是否成立？若成立，请给予证明；若不成立，S△DEF、S△CEF、S△ABC又有 怎样的数量关系？请写出你的猜想，不需证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01523','math','初中',0,'jkp-0160','short_answer',0.38,'（张家界）聪聪用两块含45°角的直角三角尺△ABC、△MNK 进行一次探究 活动：他将△MNK 的直角顶点M 放在△ABC 的斜边AB 的中点处，让MK 经过 C 点（如图甲），若BC=MK=4 . （1 ）此时两三角尺的重叠部分( △ACM ）面积为 ； （2 ）再将图甲中的△MNK 绕顶点M 逆时针旋转45°得到图乙，此时两三角尺 的重叠部分（四边形MDCG ）面积为 ； （3 ）据此猜想：在MK 与BC 相交的前提下，将△MNK 绕点M 旋转到任一位 置（如图丙）时两三角尺的重叠部分面积为 ，请说出理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01524','math','初中',0,'jkp-0160','short_answer',0.38,'（荆门）将两块全等的含30°角的三角尺如图（1 ）摆放在一起，它们的较 短直角边长为3 . （1 ）将△ECD 沿直线l 向左平移到图（2 ）的位置，使E 点落在AB 上，则 CC′= ； （2 ）将△ECD 绕点C 逆时针旋转到图（3 ）的位置，使点E落在AB 上，则△ECD 绕点C 旋转的度数= ； （3 ）将△ECD 沿直线AC 翻折到图（4 ）的位置，ED′与AB 相交于点F ，求证： AF=FD′ .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01525','math','初中',0,'jkp-0160','short_answer',0.38,'（义乌市）如图1 ，小明将一张矩形纸片沿对角线剪开，得到两张三角形纸 片（如图2 ），量得他们的斜边长为10cm ，较小锐角为30° , 再将这两张三角纸 片摆成如图3 的形状，但点B、C、F、D 在同一条直线上，且点C 与点F 重合．（在 图3 至图6 中统一用F 表示） 小明在对这两张三角形纸片进行如下操作时遇到了三个问题，请你帮助解决. （1 ）将图3 中的△ABF 沿BD 向右平移到图4 的位置，使点B 与点F 重合，请 你求出平移的距离； （2 ）将图3 中的△ABF 绕点F 顺时针方向旋转30°到图5 的位置，A1F 交DE 于 点G ，请你求出线段FG 的长度； （3 ）将图3 中的△ABF 沿直线AF 翻折到图6 的位置，AB1 交DE 于点H ，请证 明：AH﹦DH .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01526','math','初中',0,'jkp-0160','short_answer',0.38,'（南平）如图，等腰直角△ABC 中，∠ABC=90° , 点P 在AC 上，将△ABP 绕顶点B 沿顺时针方向旋转90°后得到△CBQ . （1 ）求∠PCQ 的度数； （2 ）当AB=4 ，AP ：PC=1 ：3 时，求PQ 的大小； （3 ）当点P 在线段AC 上运动时（P 不与A 重合），请写出一个反映PA2 ，PC2 ， PB2之间关系的等式，并加以证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01527','math','初中',0,'jkp-0160','short_answer',0.38,'（呼伦贝尔）图1 是边长分别为4F和3 的两个等边三角形纸片ABC 和 C′D′E′叠放在一起（C 与C′重合）. （1 ）操作：固定△ABC ，将△C′D′E′绕点C 顺时针旋转30°得到△CDE ，连接AD ， BE ，CE 的延长线交AB 于F（图2 ）. 探究：在图2 中，线段BE 与AD 之间有怎样的大小关系？试证明你的结论； （2 ）操作：将图2 中的△CDE ，在线段CF 上沿着CF 方向以每秒1 个单位的速 度平移，平移后的△CDE 设为△PQR（图3 ）. 探究：设△PQR 移动的时间为x 秒，△PQR 与△AFC 重叠部分的面积为y ，求y 与x 之间的函数解析式，并写出函数自变量x 的取值范围.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01528','math','初中',0,'jkp-0160','short_answer',0.38,'（大兴安岭）已知∠AOB=90° , 在∠AOB 的平分线OM 上有一点C ，将一 个三角板的直角顶点与C 重合，它的两条直角边分别与OA、 OB（或它们的反向延长线）相交于点D、E . （1 ）当三角板绕点C 旋转到CD 与OA 垂直时（如图1 ），易证：OD+OE=√EOC ； （2 ）当三角板绕点C 旋转到CD 与OA 不垂直时，在图2、图3 这两种情况下， 上述结论是否还成立？若成立，请给予证明；若不成立，线段OD、OE、OC 之 间又有怎样的数量关系？请写出你的猜想，不需证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01529','math','初中',0,'jkp-0160','short_answer',0.38,'（聊城）如图，在等腰Rt△ABC 中，P 是斜边BC 的中点，以P 为顶点的 直角的两边分别与边AB ，AC 交于点E ，F ，连接EF ．当∠EPF 绕顶点P 旋转时 （点E 不与A ，B 重合），△PEF 也始终是等腰直角三角形，请你说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01530','math','初中',0,'jkp-0160','short_answer',0.38,'（鄂州）正方形ABCD 和正方形AEFG 有一公共点A ，点G ．E 分别在线 段AD、AB 上（如图（1 ）所示），连接DF、BF . （1 ）求证：DF=BF ， （2 ）若将正方形AEFG 绕点A 按顺时针方向旋转，连接DG、BE（如图（2 ） 所示），在旋转过程中，请猜想线段DG、BE 始终有什么数量关系和位置关系并 证明你的猜想.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01531','math','初中',0,'jkp-0160','short_answer',0.38,'（锦州）如图a ，△ABC 和△CEF 是两个大小不等的等边三角形，且有一个 公共顶点C ，连接AF 和BE . （1 ）线段AF 和BE 有怎样的大小关系？请证明你的结论； （2 ）将图a 中的△CEF 绕点C 旋转一定的角度，得到图b ，这时（1 ）中的结论 还成立吗？作出判断并说明理由； （3 ）若将图a 中的△ABC 绕点C 旋转一定的角度，请你画出一个变换后的图形 （草图即可），（1 ）中的结论还成立吗？作出判断不必说明理由； （4 ）根据以上证明、说理、画图，归纳你的发现.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01532','math','初中',0,'jkp-0160','short_answer',0.38,'（福州）（1 ）如图1 ，点B、E、C、F 在一条直线上，BC=EF ，AB ∥DE ， ∠A=∠D ．求证：△ABC≌△DEF . （2 ）如图2 ，在矩形OABC 中，点B 的坐标为（-2 ，3 ）．画出矩形OABC 绕 点O 顺时针旋转90°后的矩形OA1B1C1 ，并直接写出的坐标A1、B1、C1 的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01533','math','初中',0,'jkp-0160','short_answer',0.38,'（西宁）（1 ）班同学上数学活动课，利用角尺平分一个角（如图所示）．设 计了如下方案： ( Ⅰ) ∠AOB 是一个任意角，将角尺的直角顶点P 介于射线OA、OB 之间，移 动角尺使角尺两边相同的刻度与M、N 重合，即PM=PN ，过角尺顶点P 的射 线OP 就是∠AOB 的平分线. ( Ⅱ) ∠AOB 是一个任意角，在边OA、OB 上分别取OM=ON ，将角尺的直角 顶点P 介于射线OA、OB 之间，移动角尺使角尺两边相同的刻度与M、N 重合， 即PM=PN ，过角尺顶点P 的射线OP 就是∠AOB 的平分线. （1 ）方案( Ⅰ)、方案( Ⅱ)是否可行？若可行，请证明；若不可行，请说明理 由； （2 ）在方案( Ⅰ) PM=PN 的情况下，继续移动角尺，同时使PM⊥OA ， PN⊥OB ．此方案是否可行？请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01534','math','初中',0,'jkp-0160','short_answer',0.38,'（山西）如图，在正方形ABCD 中，E 是CD 边的中点，AC 与BE 相交于 点F ，连接DF . （1 ）在不增加点和线的前提下，直接写出图中所有的全等三角形； （2 ）连接AE ，试判断AE 与DF 的位置关系，并证明你的结论； （3 ）延长DF 交BC 于点M ，试判断BM 与MC 的数量关系．（直接写出结论）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01535','math','初中',0,'jkp-0160','short_answer',0.38,'（泰安）（1 ）已知：如图①, 在△AOB 和△COD 中，OA=OB ，OC=OD ， ∠AOB=∠COD=60° , 求证：①AC=BD ；②∠APB=60 度； （2 ）如图②,在△AOB 和△COD 中，若OA=OB ，OC=OD ，∠AOB=∠COD=α , 则AC 与BD 间的等量关系式为 ；∠APB 的大小为 ； （3 ）如图③, 在△AOB 和△COD 中，若OA=k•OB ，OC=k•OD（k＞1 ）， ∠AOB=∠COD=α , 则AC 与BD 间的等量关系式为 ；∠APB 的大小为 . ______','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01536','math','初中',0,'jkp-0160','short_answer',0.38,'（青海）请阅读，完成证明和填空. 九年级数学兴趣小组在学校的“数学长廊”中兴奋地展示了他们小组探究发现 的结果，内容如下： （1 ）如图1 ，正三角形ABC 中，在AB、AC 边上分别取点M、N ，使BM=AN ， 连接BN、CM ，发现BN=CM ，且∠NOC=60 度．请证明：∠NOC=60 度. （2 ）如图2 ，正方形ABCD 中，在AB、BC 边上分别取点M、N ，使AM=BN ， 连接AN、DM ，那么AN= ，且∠DON= 度. （3 ）如图3 ，正五边形ABCDE 中，在AB、BC 边上分别取点M、N ，使AM=BN ， 连接AN、EM ，那么AN= ，且∠EON= 度. （4 ）在正n边形中，对相邻的三边实施同样的操作过程，也会有类似的结论. 请大胆猜测，用一句话概括你的发现： .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01537','math','初中',0,'jkp-0160','short_answer',0.38,'（日照）如图，四边形ABCD 是边长为a 的正方形，点G ，E 分别是边AB ， BC 的中点，∠AEF=90° , 且EF 交正方形外角的平分线CF 于点F . （1 ）证明：∠BAE=∠FEC ；（2 ）证明：△AGE≌△ECF；（3 ）求△AEF 的面积.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01538','math','初中',0,'jkp-0160','short_answer',0.38,'（本溪）在△ABC 中，AB=AC ，点D 是直线BC 上一点（不与B、C 重合）， 以AD 为一边在AD 的右侧作△ADE ，使AD=AE ，∠DAE=∠BAC ，连接CE . （1 ）如图1 ，当点D 在线段BC 上，如果∠BAC=90° , 则∠BCE= 度； （2 ）设∠BAC=α , ∠BCE=β . ①如图2 ，当点D 在线段BC 上移动，则α , β之间有怎样的数量关系？请说明 理由； ②当点D 在直线BC 上移动，则α , β之间有怎样的数量关系？请直接写出你的 结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01539','math','初中',0,'jkp-0160','short_answer',0.38,'（杭州）如图，在等腰△ABC 中，CH 是底边上的高线，点P 是线段CH 上 不与端点重合的任意一点，连接AP 交BC 于点E ，连接BP 交AC 于点F . （1 ）证明：∠CAE=∠CBF ； （2 ）证明：AE=BF ； （3 ）以线段AE ，BF 和AB 为边构成一个新的三角形ABG（点E 与点F 重合于 点G ），记△ABC 和△ABG 的面积分别为S△ABC和S△ABG ，如果存在点P ，能使得 S△ABC=S△ABG ，求∠ACB 的取值范围．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01540','math','初中',0,'jkp-0160','short_answer',0.38,'（平凉）如图，M 为正方形ABCD 边AB 的中点，E 是AB 延长线上的一 点，MN⊥DM ，且交∠CBE 的平分线于N ． （1 ）求证：MD=MN ； （2 ）若将上述条件中的“M 为AB 边的中点”改为“M 为AB 边上任意一点” ， 其余条件不变，则结论“MD=MN”成立吗？如果成立，请证明；如果不成立， 说明理由．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01541','math','初中',0,'jkp-0160','short_answer',0.38,'（台州）CD 经过∠BCA 顶点C 的一条直线，CA=CB ．E ，F 分别是直线 CD 上两点，且∠BEC=∠CFA=∠α ． （1 ）若直线CD 经过∠BCA 的内部，且E ，F 在射线CD 上，请解决下面两个问 题： ①如图1 ，若∠BCA=90° ，∠α =90° ， 则BE CF ；EF BE-AF（填“＞” ，“＜”或“=” ）； ②如图2 ，若0° < ∠BCA＜180° ,请添加一个关于∠α与∠BCA关系的条件 ， 使①中的两个结论仍然成立，并证明两个结论成立. （2 ）如图3 ，若直线CD 经过∠BCA 的外部，∠α=∠BCA ，请提出EF ，BE ，AF 三条线段数量关系的合理猜想（不要求证明）.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01542','math','初中',0,'jkp-0160','short_answer',0.38,'（无锡）（1 ）如图1 ，在正方形ABCD 中，M 是BC 边（不含端点B、C ） 上任意一点，P 是BC 延长线上一点，N 是∠DCP 的平分线上一点．若∠AMN=90° , 求证：AM=MN . 下面给出一种证明的思路，你可以按这一思路证明，也可以选择另外的方法证明. 证明：在边AB 上截取AE=MC ，连接ME ．正方形ABCD 中，∠B=∠BCD=90° , AB=BC . ∴∠NMC=180°-∠AMN-∠AMB=180°-∠B-∠AMB=∠MAB=∠MAE . （下面请你完成余下的证明过程） （2 ）若将（1 ）中的“正方形ABCD”改为“正三角形ABC”（如图2 ），N 是 ∠ACP 的平分线上一点，则∠AMN=60°时，结论AM=MN 是否还成立？请说 明理由. （3 ）若将（1 ）中的“正方形ABCD”改为“正n 边形ABCD…X ，请你作出猜 想：当∠AMN= 时，结论AM=MN 仍然成立．（直接写出答案，不需要 证明）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01543','math','初中',0,'jkp-0160','short_answer',0.38,'（烟台）（1 ）如图1 ，以△ABC 的边AB、AC 为边分别向外作正方形ABDE 和正方形ACFG ，连接EG ，试判断△ABC 与△AEG 面积之间的关系，并说明理 由. （2 ）园林小路，曲径通幽，如图2 所示，小路由白色的正方形理石和黑色的三 角形理石铺成．已知中间的所有正方形的面积之和是a 平方米，内圈的所有三角 形的面积之和是b 平方米，这条小路一共占地多少平方米.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01544','math','初中',0,'jkp-0160','short_answer',0.38,'（台州）如图1 ，Rt△ABC≌Rt△EDF ，∠ACB=∠F=90° ，∠A=∠E=30° ．△EDF 绕着边AB 的中点D 旋转，DE ，DF 分别交线段AC 于点M ，K ． （1 ）观察：①如图2、图3 ，当∠CDF=0°或60°时，AM+CK MK（填“＞” ， “ ＜”或“ =” ）； ②如图4 ，当∠CDF=30°时，AM+CK MK（只填“＞”或“＜” ）； （2 ）猜想：如图4 ，当0°＜∠CDF＜60°时，AM+CK MK ，证明你所得 到的结论； （3 ）如果MK2+CK2=AM2 ，请直接写出∠CDF 的度数和 的值．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01545','math','初中',0,'jkp-0160','short_answer',0.38,'（牡丹江）已知四边形ABCD 中，AB=BC ，∠ABC=120° ，∠MBN=60° ， ∠MBN 绕B 点旋转，它的两边分别交AD ，DC（或它们的延长线）于E ，F ． 当∠MBN 绕B 点旋转到AE=CF 时（如图1 ），易证AE+CF=EF ； 当∠MBN 绕B 点旋转到AE≠CF 时，在图2 和图3 这两种情况下，上述结论是 否成立？若成立，请给予证明；若不成立，线段AE ，CF ，EF 又有怎样的数量关 系？请写出你的猜想，不需证明．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01546','math','初中',0,'jkp-0160','short_answer',0.38,'（包头）如图，已知△ABC 中，AB=AC=10cm ，BC=8cm ，点D 为AB 的中点. （1 ）如果点P 在线段BC 上以3cm/s 的速度由B 点向C 点运动，同时，点Q 在线段CA 上由C 点向A 点运动. ①若点Q 的运动速度与点P 的运动速度相等，经过1s后，△BPD 与△CQP 是否 全等，请说明理由； ②若点Q 的运动速度与点P 的运动速度不相等，当点Q 的运动速度为多少时， 能够使△BPD 与△CQP 全等？ （2 ）若点Q 以②中的运动速度从点C 出发，点P 以原来的运动速度从点B 同 时出发，都逆时针沿△ABC 三边运动，求经过多长时间点P与点Q第一次在△ABC 的哪条边上相遇？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01547','math','初中',0,'jkp-0160','short_answer',0.38,'（德城区）一位同学拿了两块45°的三角尺△MNK、△ACB 做了一个探究活 动：将△MNK 的直角顶点M 放在△ABC 的斜边AB 的中点处，设AC=BC=a . （1 ）如图1 ，两个三角尺的重叠部分为△ACM ，则重叠部分的面积为 ， 周长为 ； （2 ）将图1 中的△MNK 绕顶点M 逆时针旋转45° , 得到图2 ，此时重叠部分的 面积为 ，周长为 ； （3 ）如果将△MNK 绕M 旋转到不同于图1 ，图2 的位置，如图3 所示，猜想 此时重叠部分的面积为多少？并试着加以验证.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01548','math','初中',0,'jkp-0160','short_answer',0.38,'（鄂尔多斯）我们给出如下定义：若一个四边形中存在相邻两边的平方和 等于一条对角线的平方，则称这个四边形为勾股四边形，这两条相邻的边称为这 个四边形的勾股边. （1 ）写出你所学过的特殊四边形中是勾股四边形的两种图形的名称； （2 ）如图1 ，已知格点（小正方形的顶点）O（0 ，0 ），A（3 ，0 ），B（0 ，4 ）， 请你画出以格点为顶点，OA ，OB 为勾股边且对角线相等的勾股四边形OAMB ； （3 ）如图2 ，将△ABC 绕顶点B 按顺时针方向旋转60° , 得到△DBE ，连接AD ， DC ，∠DCB=30° . 求证：DC2+BC2=AC2 ，即四边形ABCD 是勾股四边形.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01549','math','初中',0,'jkp-0160','short_answer',0.38,'（重庆）已知：如图（1 ），在平面直角坐标xOy 中，边长为2 的等边△OAB 的顶点B 在第一象限，顶点A 在x 轴的正半轴上．另一等腰△OCA 的顶点C 在 第四象限，OC=AC ，∠C=120° . 现有两动点P、Q 分别从A、O 两点同时出发， 点Q 以每秒1 个单位的速度沿OC 向点C 运动，点P 以每秒3 个单位的速度沿 A→O→B 运动，当其中一个点到达终点时，另一个点也随即停止. （1 ）求在运动过程中形成的△OPQ 的面积S 与运动的时间t 之间的函数关系， 并写出自变量t 的取值范围； （2 ）在等边△OAB 的边上（点A 除外）存在点D ，使得△OCD 为等腰三角形， 请直接写出所有符合条件的点D 的坐标； （3 ）如图（2 ），现有∠MCN=60° , 其两边分别与OB、AB 交于点M、N ，连 接MN ．将∠MCN 绕着C 点旋转（0°＜旋转角＜60° ) , 使得M、N 始终在边 OB 和边AB 上．试判断在这一过程中，△BMN 的周长是否发生变化？若没有变 化，请求出其周长；若发生变化，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01550','math','初中',0,'jkp-0160','short_answer',0.38,'（本溪）如图a ，∠EBF=90° , 请按下列要求准确画图： 1 ：在射线BE、BF 上分别取点A、C ，使BC＜AB＜2BC ，连接AC 得直角△ABC； 2 ：在AB 边上取一点M ，使AM=BC ，在射线CB 边上取一点N ，使CN=BM ， 直线AN、CM 相交于点P . （1 ）请用量角器度量∠APM 的度数为 ；（精确到1° ) （2 ）请用说理的方法求出∠APM 的度数； （3 ）若将①中的条件“BC＜AB＜2BC”改为“AB＞2BC” ，其他条件不变， 你能自己在图b 中画出图形，求出∠APM 的度数吗？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01551','math','初中',0,'jkp-0160','short_answer',0.38,'（河北）在△ABC 中，AB=AC ，CG⊥BA 交BA 的延长线于点G ．一等腰 直角三角尺按如图1 所示的位置摆放，该三角尺的直角顶点为F ，一条直角边与 AC 边在一条直线上，另一条直角边恰好经过点B . （1 ）在图1 中请你通过观察、测量BF 与CG 的长度，猜想并写出BF 与CG 满 足的数量关系，然后证明你的猜想； （2 ）当三角尺沿AC 方向平移到图2 所示的位置时，一条直角边仍与AC 边在 同一直线上，另一条直角边交BC 边于点D ，过点D 作DE⊥BA 于点E ．此时请 你通过观察、测量DE、DF 与CG 的长度，猜想并写出DE+DF 与CG 之间满足 的数量关系，然后证明你的猜想； （3 ）当三角尺在（2 ）的基础上沿AC 方向继续平移到图3 所示的位置（点F 在线段AC 上，且点F 与点C 不重合）时，（2 ）中的猜想是否仍然成立（不用 说明理由）.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01552','math','初中',0,'jkp-0160','short_answer',0.38,'（绍兴）学完“几何的回顾”一章后，老师布置了一道思考题： 如图，点M ，N 分别在正三角形ABC 的BC ，CA 边上，且BM=CN ，AM ，BN 交于点Q ．求证：∠BQM=60 度． （1 ）请你完成这道思考题； （2 ）做完（1 ）后，同学们在老师的启发下进行了反思，提出了许多问题，如： ①若将题中“BM=CN”与“∠BQM=60°”的位置交换，得到的是否仍是真命 题？ ②若将题中的点M ，N 分别移动到BC ，CA 的延长线上，是否仍能得到 ∠BQM=60° ？ ③若将题中的条件“点M ，N 分别在正三角形ABC 的BC ，CA 边上”改为“点 M ，N 分别在正方形ABCD 的BC ，CD 边上” ，是否仍能得到∠BQM=60° ？… 请你作出判断，在下列横线上填写“是”或“否” ：① ；② ； ③ ．并对②，③的判断，选择一个给出证明．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01553','math','初中',0,'jkp-0160','short_answer',0.38,'（大连）如图1 ，Rt△ABC 中AB=AC ，点D、E 是线段AC 上两动点，且 AD=EC ，AM 垂直BD ，垂足为M ，AM 的延长线交BC 于点N ，直线BD 与直 线NE 相交于点F ．试判断△DEF 的形状，并加以证明． 说明：（1 ）如果你经历反复探索，没有找到解决问题的方法，请你把探索过程中 的某种思路写出来（要求至少写3 步）； （2 ）在你经历说明（1 ）的过程之后，可以从下列①、②中选取一个补充或者 更换已知条件，完成你的证明．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01554','math','初中',0,'jkp-0160','short_answer',0.38,'画出将△BAD 沿BA 方向平移BA 长，然后顺时针旋转90°后图形；','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01555','math','初中',0,'jkp-0160','short_answer',0.38,'点K 在线段BD 上，且四边形AKNC 为等腰梯形（AC ∥KN ，如图2 ）． 附加题：如图3 ，若点D、E 是直线AC 上两动点，其他条件不变，试判断△DEF 的形状，并说明理由．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01556','math','初中',0,'jkp-0160','short_answer',0.38,'（临沂）如图1 ，已知矩形ABED ，点C 是边DE 的中点，且AB=2AD . （1 ）判断△ABC 的形状，并说明理由； （2 ）保持图1 中△ABC 固定不变，绕点C 旋转DE 所在的直线MN 到图2 中（当 垂线段AD、BE 在直线MN 的同侧），试探究线段AD、BE、DE 长度之间有什 么关系？并给予证明； （3 ）保持图2 中△ABC 固定不变，继续绕点C 旋转DE 所在的直线MN 到图3 中的位置（当垂线段AD、BE 在直线MN 的异侧）．试探究线段AD、BE、DE 长度之间有什么关系？并给予证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01557','math','初中',0,'jkp-0160','short_answer',0.38,'（天门）如图所示，在▱ABCD 中，AB＞BC ，∠A 与∠D 的平分线交于点E ， ∠B 与∠C 的平分线交于F 点，连接EF . （1 ）延长DE 交AB 于M 点，则图中与线段EM 一定相等的线段有哪几条？说 明理由；（不再另外添加字母和辅助线） （2 ）EF、BC 与AB 之间有怎样的数量关系？为什么？ （3 ）如果将条件“AB＞BC”改为“AB＜BC” ，其它条件不变，EF、BC 与AB 的关系又如何？请画出图形并证明你的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01558','math','初中',0,'jkp-0160','short_answer',0.38,'（仙桃）正方形ABCD 中，点O 是对角线DB 的中点，点P 是DB 所在直 线上的一个动点，PE⊥BC 于E ，PF⊥DC 于F . （1 ）当点P 与点O 重合时（如图①) , 猜测AP 与EF 的数量及位置关系，并证 明你的结论； （2 ）当点P 在线段DB 上（不与点D、O、B 重合）时（如图②) , 探究（1 ） 中的结论是否成立？若成立，写出证明过程；若不成立，请说明理由； （3 ）当点P 在DB 的长延长线上时，请将图③补充完整，并判断（1 ）中的结 论是否成立？若成立，直接写出结论；若不成立，请写出相应的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01559','math','初中',0,'jkp-0160','short_answer',0.38,'（海南）如图，在正方形ABCD 中，点F 在CD 边上，射线AF 交BD 于点 E ，交BC 的延长线于点G . （1）求证：△ADE≌△CDE ； （2 ）过点C 作CH⊥CE ，交FG 于点H ，求证：FH=GH ； （3 ）设AD=1 ，DF=x ，试问是否存在x 的值，使△ECG 为等腰三角形？若存在， 请求出x 的值；若不存在，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01560','math','初中',0,'jkp-0160','short_answer',0.38,'（莆田）在正方形ABCD 中，点E 是AD 上一动点，MN⊥AB 分别交AB ， CD 于M ，N ，连接BE 交MN 于点O ，过O 作OP⊥BE 分别交AB ，CD 于P ， Q . 探究：（1 ）如图①, 当点E 在边AD 上时，请你动手测量三条线段AE ，MP ， NQ 的长度，猜测AE 与MP+NQ 之间的数量关系，并证明你所猜测的结论； 探究：（2 ）如图②, 若点E 在DA 的延长线上时，AE ，MP ，NQ 之间的数量关 系又是怎样请直接写出结论； 再探究：（3 ）如图③, 连接并延长BN 交AD 的延长线DG 于H ，若点E 分别在 线段DH 和射线HG 上时，请在图③中完成符合题意的图形，并判断AE ，MP ， NQ 之间的数量关系又分别怎样？请直接写出结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01561','math','初中',0,'jkp-0160','short_answer',0.38,'（天水）在正方形ABCD 中，点P 是CD 边上一动点，连接PA ，分别过点 B、D 作BE⊥PA、DF⊥PA ，垂足分别为E、F ，如图①. （1 ）请探究BE、DF、EF 这三条线段的长度具有怎样的数量关系？若点P 在 DC 的延长线上，如图②, 那么这三条线段的长度之间又具有怎样的数量关系？ 若点P 在CD 的延长线上呢，如图③, 请分别直接写出结论； （2 ）就（1 ）中的三个结论选择一个加以证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01562','math','初中',0,'jkp-0160','short_answer',0.38,'（广州）如图，边长为1 的正方形ABCD 被两条与边平行的线段EF、GH 分割为四个小矩形，EF 与GH 交于点P . （1 ）若AG=AE ，证明：AF=AH ； （2 ）若∠FAH=45° , 证明：AG+AE=FH ； （3 ）若Rt△GBF 的周长为1 ，求矩形EPHD 的面积.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01563','math','初中',0,'jkp-0160','short_answer',0.38,'（眉山）如图：∠MON=90° , 在∠MON 的内部有一个正方形AOCD ，点 A、C 分别在射线OM、ON 上，点B1是ON 上的任意一点，在∠MON 的内部 作正方形AB1C1D1 . （1 ）连续D1D ，求证：∠D1 DA=90° ; （2 ）连接CC1 ，猜一猜，∠C1CN 的度数是多少？并证明你的结论； （3 ）在ON 上再任取一点B2 ，以AB2 为边，在∠MON 的内部作正方形AB2C2D2 ， 观察图形，并结合（1 ）、（2 ）的结论，请你再做出一个合理的判断.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01564','math','初中',0,'jkp-0160','short_answer',0.38,'（河北）如图所示，四边形ABCD 是正方形，M 是AB 延长线上一点，直 角三角尺的一条直角边经过点D ，且直角顶点E 在AB 边上滑动（点E 不与点A ， B 重合），另一直角边与∠CBM 的平分线BF 相交于点F . （1 ）如图1 所示，当点E 在AB 边的中点位置时： ①通过测量DE ，EF 的长度，猜想DE 与EF 满足的数量关系是 ； ②连接点E 与AD 边的中点N ，猜想NE 与BF 满足的数量关系是 ； ③请证明你的上述两个猜想； （2 ）如图2 所示，当点E 在AB 边上的任意位置时，请你在AD 边上找到一点 N ，使得NE=BF ，进而猜想此时DE 与EF 有怎样的数量关系.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01565','math','初中',0,'jkp-0160','short_answer',0.38,'（河南）（1 ）操作发现： 如图，矩形ABCD 中，E 是AD 的中点，将△ABE 沿BE 折叠后得到△GBE ，且点 G 在矩形ABCD 内部．小明将BG 延长交DC 于点F ，认为GF=DF ，你同意吗？ 说明理由. （2 ）问题解决： 保持（1 ）中的条件不变，若DC=2DF ，求 的值； （3 ）类比探求： 保持（1 ）中条件不变，若DC=nDF ，求 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01566','math','初中',0,'jkp-0268','short_answer',0.38,'如图，D 为等腰Rt△ABC 的斜边AB 的中点，E 为BC 边上一点，连接ED 并 延长交CA 的延长线于点F ，过D 作DH⊥EF 交AC 于G ，交BC 的延长线于H ， 则以下结论：①DE=DG ；②BE=CG；③DF=DH ；④BH=CF ．其中正确的是( ) A . ②③ B . ③④ C . ①④ D . ①②③④','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01567','math','初中',0,'jkp-0268','short_answer',0.38,'等边三角形的一边长为6cm ，则以这边上高线为边长的正方形的面积为 ( ) A ．36cm2 B ．27cm2 C ．18cm2 D ．12cm2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01568','math','初中',0,'jkp-0268','short_answer',0.38,'如图所示，在边长为2 的正三角形ABC 中，已知点P 是三角形内任意一点， 则点P 到三角形的三边距离之和PD+PE+PF 等于( ) A． B． C． D ．无法确定','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01569','math','初中',0,'jkp-0268','short_answer',0.38,'已知点A 和点B（如图），以点A 和点B 为其中两个顶点作位置不同的等腰 直角三角形，一共可作出( A ．2 个 B ．4 个C ．6 个 ) D ．8 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01570','math','初中',0,'jkp-0268','short_answer',0.38,'小明将一张正方形包装纸，剪成图1 所示形状，用它包在一个棱长为10 的 正方体的表面（不考虑接缝），如图2 所示．小明所用正方形包装纸的边长至少 为（ ） A ．40 B ．30+2 C ．20 D ．10+10','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01571','math','初中',0,'jkp-0268','short_answer',0.38,'平面上有A、B 两点，在平面内找点C ，使得△ABC 为等腰直角三角形的点C 有（ ） A ．2 个 B ．4 个C ．6 个 D ．8 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01572','math','初中',0,'jkp-0268','short_answer',0.38,'以线段AB 为一边的等腰直角三角形有（ ） A ．1 个 B ．2 个C ．4 个 D ．6 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01573','math','初中',0,'jkp-0268','short_answer',0.38,'已知△ABC 是腰长为1 的等腰直角三角形，以Rt△ABC 的斜边AC 为直角边， 画第二个等腰Rt△ACD ，再以Rt△ACD 的斜边AD 为直角边，画第三个等腰 Rt△ADE ，… ，依此类推，第n 个等腰直角三角形的面积是（ ） A ．2n﹣2 B ．2n﹣1 C ．2n D ．2n+1','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01574','math','初中',0,'jkp-0268','short_answer',0.38,'下列命题中不正确的是（ ） A ．有两个角相等的三角形是等腰三角形 B ．等腰三角形一腰上的高与底边的夹角等于顶角的一半 C ．等腰三角形两底角相等 D ．有一个角的平分线平分对边的三角形一定是等腰直角三角形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01575','math','初中',0,'jkp-0268','short_answer',0.38,'如图，以直角三角形三边为边长作正方形，其中两个以直角边为边长的正 方形面积分别为225 和400 ，则正方形A 的面积是( ) A ．175B ．575C ．625D ．700','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01576','math','初中',0,'jkp-0268','short_answer',0.38,'如图是我国古代数学家赵爽的《勾股圆方图》，它是由四个全等的直角三角 形与中间的小正方形拼成的一个大正方形、如果大正方形的面积13 ，小正方形 的面积是1 ，直角三角形的短直角边为a ，较长的直角边为b ，那么（a+b ）2 的值为( ) A ．169B ．25 C ．19 D ．13','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01577','math','初中',0,'jkp-0268','short_answer',0.38,'直角三角形有一条直角边长为13 ，另外两条边长为连续自然数，则周长为 ( ) A ．182B ．183 C ．184D ．185','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01578','math','初中',0,'jkp-0268','short_answer',0.38,'男孩戴维是城里的飞盘冠军，戈里是城里最可恶的踩高跷的人，两人约定 一比高低．戴维直立肩高1m ，他投飞盘很有力，但需在13m 内才有威力；戈 里踩高跷时鼻子离地13m ，他的鼻子是他唯一的弱点．戴维需离戈里多远时才 能击中对方的鼻子而获胜？( ) A ．7m B ．8m C ．6m D ．5m','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01579','math','初中',0,'jkp-0268','short_answer',0.38,'如图，在4×4 方格中作以AB 为一边的Rt△ABC ，要求点C 也在格点上， 这样的Rt△ABC 能作出( ) A ．2 个 B ．3 个C ．4 个 D ．6 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01580','math','初中',0,'jkp-0268','short_answer',0.38,'如图，直角三角形三边上的半圆面积从小到大依次记为S1、S2、S3 ，则S1、 S2、S3 之间的关系是( ) A ．Sl+S2＞S3 B ．Sl+S2＜S3 C ．S1+S2=S3 D ．S1 2+S2 2=S3 2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01581','math','初中',0,'jkp-0268','short_answer',0.38,'直角三角形有一条直角边的长是11 ，另外两边的长都是自然数，那么它的 周长是( ) A ．132B ．121 C ．120D ．以上答案都不对','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01582','math','初中',0,'jkp-0268','short_answer',0.38,'已知△ABC 中，AB=AC=10 ，BD 是AC 边上的高线，DC=2 ，那么BD 等 于( ) A ．4 B ．6 C ．8 D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01583','math','初中',0,'jkp-0268','short_answer',0.38,'一个直角三角形有两边长分别是6 和8 ，下列说法正确的是( ) A ．第三边长是10 B ．三角形的周长是24 C ．三角形的面积是24 D ．第三边是10 或2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01584','math','初中',0,'jkp-0268','short_answer',0.38,'一架2.5 米长的梯子斜靠在一竖直的墙上，这时梯子的顶端距墙脚2.4 米．那 么梯足离墙脚的距离是（ ）米. A ．0.7 B ．0.9 C ．1.5 D ．2.4','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01585','math','初中',0,'jkp-0268','short_answer',0.38,'在Rt△ABC 中，∠C=90° , AC=2 ，BC=2 ，则AB 为( ) A ．整数 B ．分数 C ．有理数D ．以上都不对','','','','imported-junior-pdf','approved','通用','基础');
