INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01587','math','初中',0,'jkp-0268','short_answer',0.38,'已知∠AOB=90° ,点P 在∠AOB 的平分线上，OP=6 ，则点P 到OA ，OB 的距离为( ) A．6，6 B ．3 ，3 C．3，3 D．3 ，3','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01588','math','初中',0,'jkp-0268','short_answer',0.38,'已知直角三角形的斜边为2 ，周长为 ．则其面积是( ) A． B．1 C． D ．2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01589','math','初中',0,'jkp-0268','short_answer',0.38,'设直角三角形的三边长分别为a、b、c ，若c﹣b=b﹣a＞0 ，则 =( ) A ．2 B ．3 C ．4 D ．5','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01590','math','初中',0,'jkp-0268','short_answer',0.38,'如图Rt△ABC 中，AB=BC=4 ，D 为BC 的中点，在AC 边上存在一点E ， 连接ED ，EB ，则△BDE 周长的最小值为( ) A ．2 B ．2 C ．2 +2 D ．2 +2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01591','math','初中',0,'jkp-0268','short_answer',0.38,'如图是某几何体的三视图及相关数据，则判断正确的是( ) A ．a＞c B ．b＞c C ．4a2+b2=c2 D ．a2+b2=c2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01592','math','初中',0,'jkp-0268','short_answer',0.38,'如图，一圆锥的底面半径为2 ，母线PB 的长为6 ，D 为PB 的中点．一只 蚂蚁从点A 出发，沿着圆锥的侧面爬行到点D ，则蚂蚁爬行的最短路程为( ) A． B．2 C ．3 D ．3','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01593','math','初中',0,'jkp-0268','short_answer',0.38,'如图，长方体的长为15 ，宽为10 ，高为20 ，点B 离点C 的距离为5 ，一 只蚂蚁如果要沿着长方体的表面从点A 爬到点B ，需要爬行的最短距离是( ) A ．5 B ．25 C ．10 +5 D ．35','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01594','math','初中',0,'jkp-0268','short_answer',0.38,'如图，一只蚂蚁从长宽都是3 ，高是8 的长方体纸箱的A 点沿纸箱爬到B 点，那么它所行的最短路线的长是( ) A ．（3 +8 ）cm B ．10cm C ．14cm D ．无法确定','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01595','math','初中',0,'jkp-0268','short_answer',0.38,'如图，是一块长、宽、高分别是4cm ，2cm 和1cm 的长方体木块、一只 蚂蚁要从长方体木块的一个顶点A 处，沿着长方体的表面到长方体上和A 相对 的顶点B 处吃食物，那么它需要爬行的最短路径的长是( ) A ．5cm B ．5.4cm C ．6.1cm D ．7cm','','','','imported-junior-pdf','approved','通用','基础');
