INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01598','math','初中',0,'jkp-0268','short_answer',0.38,'如图，点A 的正方体左侧面的中心，点B 是正方体的一个顶点，正方体的 棱长为2 ，一蚂蚁从点A 沿其表面爬到点B 的最短路程是( ) A．3 B . √区+2 C． D ．4','','','','imported-junior-pdf','approved','通用','基础');
