INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01647','math','初中',0,'jkp-0268','short_answer',0.38,'如图，从电线杆离地面6m 处向地面拉一条长10m 的固定缆绳，这条缆绳 在地面的固定点距离电线杆底部有 m .','','','','imported-junior-pdf','approved','通用','基础');
