INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01649','math','初中',0,'jkp-0268','short_answer',0.38,'小明要把一根长为70cm 的长的木棒放到一个长、宽、高分别为50cm ， 40cm ，30cm 的木箱中，他能放进去吗？ （填“能”或“不能” ）.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01650','math','初中',0,'jkp-0268','short_answer',0.38,'小明想知道学校旗杆有多高，他发现旗杆上的绳子垂到地面还余1m ，当他 把绳子下端拉开5m 后，发现下端刚好接触地面，则旗杆高度为 米.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01651','math','初中',0,'jkp-0268','short_answer',0.38,'如图，在校园内有两棵树，相距12m ，一棵树高13m ，另一棵树高8m ， 一只小鸟从一棵树的顶端飞到另一棵树的顶端，小鸟至少要飞 m .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01652','math','初中',0,'jkp-0268','short_answer',0.38,'你听说过亡羊补牢的故事吗如图，为了防止羊的再次丢次，小明爸爸要在 高0.9m ，宽1.2m 的栅栏门的相对角顶点间加一个加固木板，这条木板需 m 长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01653','math','初中',0,'jkp-0268','short_answer',0.38,'如图，将一根长24cm 的筷子，底面直径为5cm ，高为12cm 的圆柱形水 杯中，设筷子露在杯子外面的长度为h cm ，则h 的最小值是 cm .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01654','math','初中',0,'jkp-0268','short_answer',0.38,'如图，一架10 米长的梯子斜靠在墙上，刚好梯顶抵达8 米高的路灯．当电 工师傅沿梯上去修路灯时，梯子下滑到了B′处，下滑后，两次梯脚间的距离为2 米，则梯顶离路灯 米.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01655','math','初中',0,'jkp-0268','short_answer',0.38,'如图所示的圆柱体中底面圆的半径是 ，高为2 ，若一只小虫从A 点出发 沿着圆柱体的侧面爬行到C 点，则小虫爬行的最短路程是 ．（结果 保留根号）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01656','math','初中',0,'jkp-0268','short_answer',0.38,'如图，有一圆锥形粮堆，其正视图是边长为6m 的正三角形ABC ，粮堆母 线AC 的中点P 处有一老鼠正在偷吃粮食，此时，小猫正在B 处，它要沿圆锥侧 面到达P 处捕捉老鼠，则小猫所经过的最短路程是 m ．（结果不取 近似值）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01657','math','初中',0,'jkp-0268','short_answer',0.38,'如图，这是一个供滑板爱好者使用的U 型池，该U 型池可以看作是一个长 方体去掉一个“半圆柱”而成，中间可供滑行部分的截面是半径为4m 的半圆， 其边缘AB=CD=20m ，点E 在CD 上，CE=2m ，一滑板爱好者从A 点滑到E 点，则他滑行的最短距离约为 m ．（边缘部分的厚度忽略不计，结 果保留整数）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01658','math','初中',0,'jkp-0268','short_answer',0.38,'如图是一个三级台阶，它的每一级长、宽、高分别是2 米、0.3 米、0.2 米， A ，B 是这个台阶上两个相对的端点，A 点有一只蚂蚁，想到B 点去吃可口的食 物，则蚂蚁沿台阶面爬行到B 点最短路程是 米.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01659','math','初中',0,'jkp-0268','short_answer',0.38,'一只蚂蚁从长、宽都是3 ，高是8 的长方体纸箱的A 点沿纸箱爬到B 点， 那么它所行的最短路线的长是 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01660','math','初中',0,'jkp-0268','short_answer',0.38,'如图，有一圆柱，其高为12cm ，底面半径为3cm ，在圆柱下底面A 点处 有一只蚂蚁，它想得到上底面B 处的食物，则蚂蚁经过的最短距离为 cm . ( π取3 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01661','math','初中',0,'jkp-0268','short_answer',0.38,'如图是一个三级台阶，它的每一级的长、宽、高分别为7 寸、5 寸和3 寸， A 和B 是这个台阶的两个相对端点，A 点上有一只蚂蚁想到B 点去吃可口的食 物，则它所走的最短路线长度是 寸．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01662','math','初中',0,'jkp-0268','short_answer',0.38,'在一个长为2 米，宽为1 米的矩形草地上，如图堆放着一根长方体的木块， 它的棱长和场地宽AD 平行且大于AD ，木块的正视图是边长为0.2 米的正方形， 一只蚂蚁从点A 处，到达C 处需要走的最短路程是 米．（精确到 0.01 米）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01663','math','初中',0,'jkp-0268','short_answer',0.38,'如图是一种“羊头”形图案，其做法是：从正方形①开始，以它的一边为 斜边，向外作等腰直角三角形，然后再以其直角边为边，分别向外作正方形②和 ②′ ，… ，然后依此类推，若正方形①的边长为64cm ，则第④个正方形的边长为 cm ．','','','','imported-junior-pdf','approved','通用','基础');
