INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01682','math','初中',0,'jkp-0268','short_answer',0.38,'在直线l 上依次摆放着七个正方形（如图所示）．已知斜放置的三个正方形 的面积分别是1 ，2 ，3 ，正放置的四个正方形的面积依次是S1 ，S2 ，S3 ，S4 ，则 S1 +S2+S3+S4= . 解答：','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01683','math','初中',0,'jkp-0268','short_answer',0.38,'如图1 所示为一上面无盖的正方体纸盒，现将其剪开展成平面图，如图2 所 示．已知展开图中每个正方形的边长为1 . （1 ）求在该展开图中可画出最长线段的长度这样的线段可画几条？ （2 ）试比较立体图中∠BAC 与平面展开图中∠B′A′C′的大小关系？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01684','math','初中',0,'jkp-0268','short_answer',0.38,'如图，△ACB 和△ECD 都是等腰直角三角形，∠ACB=∠ECD=90° , D 为AB 边上一点，求证： （1）△ACE≌△BCD； （2 ）AD2+DB2=DE2 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01685','math','初中',0,'jkp-0268','short_answer',0.38,'如图，把矩形纸片ABCD 沿EF 折叠，使点B 落在边AD 上的点B′处，点A 落在点A′处； （1 ）求证：B′E=BF ； （2 ）设AE=a ，AB=b ，BF=c ，试猜想a ，b ，c 之间的一种关系，并给予证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01686','math','初中',0,'jkp-0268','short_answer',0.38,'△ABC 中，BC=a ，AC=b ，AB=c ．若∠C=90° , 如图1 ，根据勾股定理，则 a2+b2=c2 ．若△ABC 不是直角三角形，如图2 和图3 ，请你类比勾股定理，试猜 想a2 +b2 与c2 的关系，并证明你的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01687','math','初中',0,'jkp-0268','short_answer',0.38,'（1 ）四年一度的国际数学家大会于2002 年8 月20 日在北京召开，大会会 标如图（1 ）．它是由四个相同的直角三角形与中间的小正方形拼成的一个大正方 形．若大正方形的面积为13 ，每个直角三角形两直角边的和是5 ，求中间小正 方形的面积. （2 ）现有一张长为6.5cm ，宽为2cm 的纸片，如图（2 ），请你将它分割成6 块，再拼合成一个正方形. （要求：先在图（2 ）中画出分割线，再画出拼成的正方形并标明相应数据）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01688','math','初中',0,'jkp-0268','short_answer',0.38,'在Rt△ABC 中，∠C=90° , ∠A、∠B、∠C 的对边长分别为a、b、c ，设△ABC 的面积为S ，周长为l . （1 ）填表： 三边a、b、c a+b﹣c 3、4、5 2 5、12、13 4 8、15、17 6 （2 ）如果a+b﹣c=m ，观察上表猜想： 式表示）； （3 ）说出（2 ）中结论成立的理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01689','math','初中',0,'jkp-0268','short_answer',0.38,'如图所示，折叠长方形的一边AD ，使点D落在边BC 的点F处，已知AB=8cm ， BC=10cm ，则EC 的长为 cm .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01690','math','初中',0,'jkp-0268','short_answer',0.38,'如图，将矩形ABCD 沿直线AE 折叠，顶点D 恰好落在BC 边上F 点处，已 知CE=3cm ，AB=8cm ，求图中阴影部分的面积.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01691','math','初中',0,'jkp-0268','short_answer',0.38,'在学习勾股定理时，我们学会运用图（I）验证它的正确性；图中大正方形的 面积可表示为： （a+b ）2 ，也可表示为：c2+4•（ab ）， 即（a+b）2=c2+4•（ ab）由此推出勾股定理a2+b2=c2 ，这种根据图形可以极 简单地直观推论或验证数学规律和公式的方法，简称“无字证明” . = ，（用含有m 的代数 （1 ）请你用图（II ）（2002 年国际数字家大会会标）的面积表达式验证勾股定 理（其中四个直角三角形全等）； （2 ）请你用（III ）提供的图形进行组合，用组合图形的面积表达式验证（x+y） 2=x2+2xy+y2 ； （3 ）请你自己设计图形的组合，用其面积表达式验证：（x+p ）（x+q ） =x2 +px+qx+pq=x2 +（p+q ）x+pq ．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01692','math','初中',0,'jkp-0268','short_answer',0.38,'据我国古代《周髀算经》记载，公元前1120 年商高对周公说，将一根直尺 折成一个直角，两端连接得一个直角三角形，如果勾是三、股是四，那么弦就等 于五．后人概括为“勾三，股四，弦五” ． （1 ）观察：3 ，4 ，5 ；5 ，12 ，13；7 ，24 ，25；… ，发现这些勾股数的勾都是 奇数，且从3起就没有间断过．计算（9﹣1）、（9+1）与（25﹣1）、（25+1）， 并根据你发现的规律，分别写出能表示7 ，24 ，25 的股和弦的算式； （2 ）根据（1 ）的规律，用n（n 为奇数且n≥3 ）的代数式来表示所有这些勾股 数的勾、股、弦，合情猜想他们之间二种相等关系并对其中一种猜想加以证明； （3 ）继续观察4 ，3 ，5 ；6 ，8 ，10；8 ，15 ，17 ；… ，可以发现各组的第一个 数都是偶数，且从4 起也没有间断过．运用类似上述探索的方法，直接用m（m 为偶数且m＞4）的代数式来表示他们的股和弦．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01693','math','初中',0,'jkp-0268','short_answer',0.38,'大家在学完勾股定理的证明后发现运用“同一图形的面积不同表示方式相 同”可以证明一类含有线段的等式，这种解决问题的方法我们称之为面积法．学 有所用：在等腰三角形ABC 中，AB=AC ，其一腰上的高为h ，M 是底边BC 上 的任意一点，M 到腰AB、AC 的距离分别为h1、h2 ． （1 ）请你结合图形来证明：h1+h2=h ； （2 ）当点M 在BC 延长线上时，h1、h2、h 之间又有什么样的结论．请你画出 图形，并直接写出结论不必证明； （3 ）利用以上结论解答，如图在平面直角坐标系中有两条直线l1：y= x+3 ，l2 ： y=﹣3x+3 ，若l2 上的一点M 到l1 的距离是 ．求点M 的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01694','math','初中',0,'jkp-0268','short_answer',0.38,'如图，正方形MNPQ 网格中，每个小方格的边长都相等，正方形ABCD 的顶点在正方形MNPQ 的4 条边的小方格顶点上. （1）设正方形MNPQ 网格内的每个小方格的边长为1 ，求： ①△ABQ ，△BCM ，△CDN ，△ADP 的面积；②正方形ABCD 的面积； （2 ）设MB=a ，BQ=b ，利用这个图形中的直角三角形和正方形的面积关系， 你能验证已学过的哪一个数学公式或定理吗？相信你能给出简明的推理过程.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01695','math','初中',0,'jkp-0268','short_answer',0.38,'如图（1 ）所示，一个梯子AB 长2.5 米，顶端A 靠在墙AC 上，这时梯子 下端B 与墙角C 距离为1.5 米，梯子滑动后停在DE 位置上，如图（2 ）所示， 测得BD=0.5 米，求梯子顶端A 下落了多少米？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01696','math','初中',0,'jkp-0268','short_answer',0.38,'如图，A 城气象台测得台风中心在A 城正西方向320km 的B 处，以每小 时40km 的速度向北偏东60°的BF 方向移动，距离台风中心200km 的范围内 是受台风影响的区域. （1 ）A 城是否受到这次台风的影响？为什么？ （2 ）若A 城受到这次台风影响，那么A 城遭受这次台风影响有多长时间？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01697','math','初中',0,'jkp-0268','short_answer',0.38,'已知某开发区有一块四边形的空地ABCD ，如图所示，现计划在空地上种 植草皮，经测量∠A=90° , AB=3m ，BC=12m ，CD=13m ，DA=4m ，若每平 方米草皮需要200 元，问要多少投入？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01698','math','初中',0,'jkp-0268','short_answer',0.38,'为了丰富少年儿童的业余生活，某社区要在如图所示AB 所在的直线建一图 书室，本社区有两所学校所在的位置在点C 和点D 处，CA⊥AB 于A ，DB⊥AB 于B ，已知AB=25km ，CA=15km ，DB=10km ，试问：图书室E 应该建在距 点A 多少km 处，才能使它到两所学校的距离相等？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01699','math','初中',0,'jkp-0268','short_answer',0.38,'如图所示的一块地，AD=12m ，CD=9m ，∠ADC=90° ,AB=39m ，BC=36m ， 求这块地的面积.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01700','math','初中',0,'jkp-0268','short_answer',0.38,'如图，公路AB 和公路CD 在点P 处交会，且∠APC=45° ,点Q 处有一所 小学，PQ= ，假设拖拉机行驶时，周围130m 以内会受到噪声的影响， 那么拖拉机在公路AB 上沿PA 方向行驶时，学校是否会受到噪声影响？请说明 理由；若受影响，已知拖拉机的速度为36km/h ，那么学校受影响的时间为多少 秒？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01701','math','初中',0,'jkp-0268','short_answer',0.38,'甲、乙两位探险者到沙漠进行探险，没有了水，需要寻找水源．为了不致 于走散，他们用两部对话机联系，已知对话机的有效距离为15 千米．早晨8 ： 00 甲先出发，他以6 千米/时的速度向东行走，1 小时后乙出发，他以5 千米/ 时的速度向北行进，上午10 ：00 ，甲、乙二人相距多远？还能保持联系吗？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01702','math','初中',0,'jkp-0268','short_answer',0.38,'如图，∠AOB=90° , OA=45cm ，OB=15cm ，一机器人在点B 处看见一个 小球从点A 出发沿着AO 方向匀速滚向点O ，机器人立即从点B 出发，沿直线 匀速前进拦截小球，恰好在点C 处截住了小球．如果小球滚动的速度与机器人 行走的速度相等，那么机器人行走的路程BC 是多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01703','math','初中',0,'jkp-0268','short_answer',0.38,'印度数学家什迦逻（1141 年﹣1225 年）曾提出过“荷花问题” ： “平平湖水清可鉴，面上半尺生红莲； 出泥不染亭亭立，忽被强风吹一边， 渔人观看忙向前，花离原位二尺远； 能算诸君请解题，湖水如何知深浅” 请用学过的数学知识回答这个问题.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01704','math','初中',0,'jkp-0268','short_answer',0.38,'如图，两个小滑块A、B 由一根连杆连接，A、B 分别可以在互相垂直的两 个滑道上滑动．开始时滑块A 距O 点16cm ，滑块B 距O 点12cm ．那么滑块 A 向下滑动6cm 时，求滑块B 向外滑动了多少cm ？（结果精确到0.1cm ，其 中 ， ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01705','math','初中',0,'jkp-0268','short_answer',0.38,'从下面两个题目中任选一题作答： （A 题）折竹抵地 今有竹高一丈，末折抵地，去本三尺．问折者高几何（如图） 友情提醒：请写出解答这首诗的方法和步骤. （B 题）海岛算经 三国魏人刘徽，自撰《海岛算经》，专论测高望远．其中有一题，是数学史上有 名的测量问题．今译如下：如图，要测量海岛上一座山峰A 的高度AH ，立两根 高三丈的标杆BC 和DE ，两竿相距BD=1 000 步，D、B、H 成一线，从BC 退 行123 步到F ，人目着地观察A ，A、C、F 三点共线；从DE 退行127 步到G ， 从G 看A ，A、E、G 三点也共线．试算出山峰的高度AH 及HB 的距离．（古制 1 步=6 尺，1 里=180 丈=1 800 尺=300 步．结果用里和步来表示） 友情提醒：请写出必要的算法和过程.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01706','math','初中',0,'jkp-0268','short_answer',0.38,'梅华中学九年级数学课外学习小组某下午实践活动课时，测量朝西教学楼 前的旗杆AB 的高度．如图，当阳光从正西方向照射过来时，旗杆AB 的顶端A 的影子落在教学楼前的坪地C 处，测得影长CE=2m ，DE=4m ，BD=20m ，DE 与地面的夹角α=30 度．在同一时刻，测得一根长为1m 的直立竹竿的影长恰为 4m ．根据这些数据求旗杆AB 的高度（．可能用到的数据： ≈1.414 ≈1.732 ， 结果保留两个有效数字）','','','','imported-junior-pdf','approved','通用','基础');
