INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01710','math','初中',0,'jkp-0268','short_answer',0.38,'证明：（1 ）:匕ACB=匕ECD=90。， :匕ACD+匕BCD=匕ACD+匕ACE 即匕BCD=匕ACE . :BC=AC ，DC=EC ， :△ACE竺△BCD . （2 ）:△ACB 是等腰直角三角形， :匕B=匕BAC=45 度. :△ACE竺△BCD ， :匕B=匕CAE=45。 :匕DAE=匕CAE+匕BAC=45。+45。=90。， :AD2 +AE2 =DE2 . 由（1）知AE=DB ， :AD2 +DB2 =DE2 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01711','math','初中',0,'jkp-0268','short_answer',0.38,'（1 ）证明：由题意得B,F=BF ，匕B,FE=匕BFE ， 在矩形ABCD 中，AD ⅡBC ， :匕B,EF=匕BFE ， :匕B,FE=匕B''EF ， :B,F=B,E ，:B,E=BF ； （2 ）答：a ，b ，c 三者关系不唯一，有两种可能情况： （i ）a ，b ，c 三者存在的关系是a2+b2=c2 . 证明：连接BE ， 由（1）知B,E=BF=c ， :B,E=BE ， :四边形BEB,F 是平行四边形， :BE=c . 在△ABE 中，匕A=90。，:AE2+AB2=BE2 ， :AE=a ，AB=b ，:a2+b2=c2 ； （i ）a ，b ，c 三者存在的关系是a+b＞c . , 证明：连接BE ，则BE=B′E . 由（1）知B′E=BF=c ， ∴BE=c ， 在△ABE 中，AE+AB＞BE ， ∴a+b＞c .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01712','math','初中',0,'jkp-0268','short_answer',0.38,'证明：连接BE . , 由图形可知S 梯形ABCD=SRt△DEA+SRt△ABE+SRt△BCE ， 则b（a+2b ）= ab+ c2+ （a+b ）（b﹣a ）， ∴ab+b2= ab+ c2+ b2﹣a2 ．因此，a2+b2=c2 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01713','math','初中',0,'jkp-0268','short_answer',0.38,'证明：∵四边形HEFM 的面积为：c2 ， 四边形HEFM 的面积还可以表示为：4× ab+（b﹣a ）2=a2+b2 ， ∴a2+b2=c2 ； ∵四边形ABCD 的面积为：（a+b ）2 ， 四边形ABCD 的面积还可以表示为：4× ab+c2=c2+2ab ，∴a2+b2=c2 .','','','','imported-junior-pdf','approved','通用','基础');
