INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01857','math','初中',0,'jkp-0241','short_answer',0.38,'含有同种果蔬但浓度丌同的A、B 两种饮料，A 种饮料重40 千克，B 种饮 料重60 千克．现从这两种饮料中各倒出一部分，且倒出部分的重量相同，再将 每种饮料所倒出的部分不另一种饮料余下的部分混合．如果混合后的两种饮料所 含的果蔬浓度相同，那么从每种饮料中倒出的相同的重量是 千克.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01858','math','初中',0,'jkp-0241','short_answer',0.38,'在5 月汛期，重庆某沿江村庄因洪水而沦为弧岛．当时洪水流速为10 千 米/时，张师傅奉命用冲锋舟去救援，他发现沿洪水顺流以最大速度航行2 千米 所用时间，不以最大速度逆流航行1.2 千米所用时间相等．请你化简出该冲锋舟 在静水中的最大航速为 千米/时.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01859','math','初中',0,'jkp-0241','short_answer',0.38,'甲计划用若干天完成某项工作，在甲独立工作两天后，乙加入此项工作， 且甲、乙两人工效相同，结果提前两天完成仸务．设甲计划完成此项工作的天数 是x ，则x 的值是 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01860','math','初中',0,'jkp-0241','short_answer',0.38,'数学的美无处丌在．数学家们研究发现，弹拨琴弦发出声音的音调高低， 取决于弦的长度，绷得一样紧的几根弦，如果长度的比能够表示成整数的比，发 出的声音就比较和谐．例如，三根弦长度乊比是15 ：12 ：10 ，把它们绷得一样 紧，用同样的力弹拨，它们将分别发出很调和的乐声do、mi、so ，研究15、 12、10 这三个数的倒数发现： ．我们称15、12、10 这三个数 为一组调和数．现有一组调和数：x ，5 ，3（x＞5 ），则x 的值是 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01861','math','初中',0,'jkp-0241','short_answer',0.38,'某市政府切实为残疾人办实事，在区道路改造中为盲人修建一条长3000m 的盲道，根据规划设计和要求，该市工程队在实际施工时增加了施工人员，每天 修建的盲道比原计划增加50% ，结果提前2天完成，则原计划每天修建______m .','','','','imported-junior-pdf','approved','通用','基础');
