INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01869','math','初中',0,'jkp-0241','short_answer',0.38,'已知两个分式：A= ，B= ，其中x≠±2 ．下面有三个结论： ①A=B ；②A、B 互为倒数；③A、B 互为相反数． 请问哪个正确？为什么？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01870','math','初中',0,'jkp-0241','short_answer',0.38,'我们把分子为1 的分数叫做单位分数．如 ，，… ，仸何一个单位分数 都可以拆分成两个丌同的单位分数的和，如= ，= ，= ，… （1 ）根据对上述式子的观察，你会发现 请写出□，○所表示的数； （2 ）迚一步思考，单位分数（n 是丌小于2 的正整数）= ，请写出△， ☆所表示的式，并加以验证． ,求A、B 的值.','','','','imported-junior-pdf','approved','通用','基础');
