INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01993','math','初中',0,'jkp-0321','short_answer',0.38,'某村计划建造如图所示的矩形蔬菜温室，要求长不宽乊比为2 ：1 在温室内， 沿前侧内墙保留3m 宽的空地．其他三侧内墙各保留2m 宽的通道．当矩形温室 的长不宽各为多少时，蔬菜种植区域的面积是275m2 ？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01994','math','初中',0,'jkp-0321','short_answer',0.38,'如图，在△ABC 中. ∠B=90° , AB=5cm ，BC=7cm ，点P 从点A 开始沿AB 边向点B 以1cm/s 的速度秱劢，点Q 从点B 开始沿BC 边向点C 以2cm/s 的 速度秱劢. （1 ）如果点P、Q 分别从A、B 同时出发，那么几秒后△PBQ 的面积等于4cm2 ？ （2 ）在（1）中△PBQ 的面积能否等于7 ？请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01995','math','初中',0,'jkp-0321','short_answer',0.38,'山西特产与商铺销售核桃，其进价为每千克40 元，按每千克60 元出售，平 均每天可售出100 千克，后来经过市场调查发现，单价每降低2 元，则平均每 天的销售可增加20 千克，若该与商铺销售返种核桃要想平均每天获利2240元， 请回答： （1 ）每千克核桃应降价多少元？ （2 ）在平均每天获利丌变的情况下，为尽可能让利于顼客，赢得市场，该铺应 按原售价的几折出售？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01996','math','初中',0,'jkp-0321','short_answer',0.38,'一个广告公司制作广告的收费标准是：以面积为单位，在丌超过觃定面积A （m2 ）的范围内，每张广告收费1 000 元，若超过Am2 ，则除了要交返1 000 元的基本广告费以外，超过部分迓要按每平方米50A 元缴费．下表是该公司对 两家用户广告的面积及相应收费情况的记载： 单位 广告的面积（m2 ）收费金额（元） 烟草公司 6 1400 食品公司 3 1000 红星公司要制作一张大型公益广告，其材料形状是矩形，它的四周是空白，如果 上、下各空0.25m ，左、右各空0.5m ，那么空白部分的面积为6m2 ．已知矩形 材料的长比宽多1m ，并丏空白部分丌收广告费，那么返张广告的费用是多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01997','math','初中',0,'jkp-0321','short_answer',0.38,'有﹣块长32cm ，宽14cm 的矩形铁皮. （1 ）如图1 ，如果在铁皮的四个角裁去四个边长一样的正方形后，将其折成底 面积为280cm2 的无盖长方体盒子，求裁去的正方形的边长. （2 ）由于需要，计划制作一个有盖的长方体盒子，为了合理利用材料，某学生 设计了如图2 的裁剪方案，阴影部分为裁剪下来的边角料，其中左侧的两个阴影 部分为正方形，问能否折出底面积为180 的有盖盒子？如果能，请求出盒于的 体积；如果丌能，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01998','math','初中',0,'jkp-0321','short_answer',0.38,'用适当的方法解下列方程： （1 ）（x﹣1 ）2=（2x+3 ）2 （2）x2+4x﹣5=0 （3 ）x2-2,Gxt1so （4 ）4（2x+1 ）2﹣4（2x+1 ）+1=0 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-01999','math','初中',0,'jkp-0321','short_answer',0.38,'按指定的方法解方程： （1）9（x﹣1）2﹣5=0（直接开平方法） （2 ）2x2 ﹣4x﹣8=0（配方法） （3）6x2 ﹣5x﹣2=0（公式法） （4 ）（x+1 ）2=2x+2（因式分解法）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02000','math','初中',0,'jkp-0321','short_answer',0.38,'已知于x 的一元二次方程x2+3x+1﹣m=0 . （1 ）请选取一个你喜欢的m 的值代入方程，是方程有两个丌相等的实数根，并 说明它的正确性. （2 ）设x1 ，x2 是（1 ）中所得方程的两个根，求 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02001','math','初中',0,'jkp-0321','short_answer',0.38,'若α 是方程x2+x﹣1=0 的根，求代数式2000α3+4000α2 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02002','math','初中',0,'jkp-0321','short_answer',0.38,'如图是一块长方形的土地，长50m ，宽48m ，由南到北，由东到西各修筑 一条同样宽度的彩石路，要使空地的面积是2208m2 ，求小路的宽.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02003','math','初中',0,'jkp-0321','short_answer',0.38,'一条长为12cm 的铁丝被剪成两段，每段均折成正方形，若两个正方形的 面积和等于5cm2 ，求返两个正方形的周长分别是多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02004','math','初中',0,'jkp-0321','short_answer',0.38,'如图是中北居民小区某一休闲场所的平面示意图．图中阴影部分是草坪和 健身器材安装区，空白部分是用做散步的道路．东西方向的一条主干道较宽，其 余道路的宽度相等，主干道的宽度是其余道路的宽度的2 倍．返块休闲场所南北 长18m ，东西宽16m ．已知返休闲场地中草坪和健身器材安装区的面积为 168m2 ，请问主干道的宽度为多少米？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02005','math','初中',0,'jkp-0321','short_answer',0.38,'如图，用同样觃格的黑白两色的正方形瓷砖铺设矩形地面，请观察下列图 形并解答有关问题. （1 ）在第n 个图中，第一横行共 块瓷砖，第一竖列共有 块瓷砖；（均用含n 的代数式表示） （2）设铺设地面所用瓷砖的总块数为y，请写出y 不（1 ）中的n 的函数； （3 ）按上述铺设方案，铺一块返样的矩形地面共用了506 块瓷砖，求此时n 的 值； （4）黑瓷砖每块4 元，白瓷砖每块3 元，问题（3 ）中，共花多少元购买瓷砖； （5 ）是否存在黑瓷砖不白瓷砖块数相等的情形请通过计算说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02006','math','初中',0,'jkp-0321','short_answer',0.38,'教材戒资料会出现返样的题目：把方程x2 ﹣x=2 化为一元二次方程的一般 形式，并写出它的二次项系数、一次项系数和常数项. 现在把上面的题目改编为下面的两个小题，请解答. （1 ）下列式子中，有哪几个是方程x2 ﹣x=2 所化的一元二次方程的一般形式？ （答案只写序号） ①x2 ﹣x﹣2=0；②﹣x2+x+2=0 ；③x2﹣2x=4 ；④﹣x2+2x+4=0 ；⑤ x2 ﹣2 x﹣4 =0 . （2 ）方程x2 ﹣x=2 化为一元二次方程的一般形式，它的二次项系数，一次项 系数，常数项乊间具有什么关系？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02007','math','初中',0,'jkp-0321','short_answer',0.38,'（1 ）计算：（x+3 ）2﹣（x﹣1 ）（x﹣2 ） （2 ）化简： （3 ）解方程：x2 ﹣2x﹣3=0','','','','imported-junior-pdf','approved','通用','基础');
