INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02159','math','初中',0,'jkp-0321','short_answer',0.38,'【中】已知ΔABC 的三边a,b,c 满足：b + c = 8 ，bc = a2 -12a + 52，试确定ΔABC 的形状.','','','','imported-junior-pdf','approved','通用','基础');
