INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02161','math','初中',0,'jkp-0321','short_answer',0.38,'【易】（眉山市初中学业水平暨高中阶段教育学校招生考试）已知三角形的两边长是 方程x2 - 5x + 6 = 0的两个根．则该三角形的周长L 的取值范围是( ) A．1< L < 5 B．2 < L < 6 C．5 < L < 9 D．6 < L <10','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02162','math','初中',0,'jkp-0321','short_answer',0.38,'【中】已知ΔABC 的两边AB 、AC 的长是关于x 的一元二次方 程x2 - (2k + 3)x + k2 + 3k + 2 = 0 的两个实数根，第三边BC 的长 是5 ⑴k 为何值时，△ABC 是以BC 为斜边的直角三角形； ⑵k 为何值时，△ABC 是等腰三角形，并求ΔABC 的周长','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02163','math','初中',0,'jkp-0321','short_answer',0.38,'【易】（北大附中2010-2011 学年度初二第二学期期末考试）已知方程x2 - 5x + 2 = 0 的两个解分别为x1 、x2 ，则x1 + x2 -x1 .x2 的值为( ) A ．-7 B ．-3 C ．7 D ．3','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02164','math','初中',0,'jkp-0321','short_answer',0.38,'【易】若方程x2 + x + k = 0有两负根，则k 的取值范围是( ) A．k > 0 B．k < 0 C．k < D ．0 < k ≤','','','','imported-junior-pdf','approved','通用','基础');
