INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02166','math','初中',0,'jkp-0321','short_answer',0.38,'【易】实数k 为何值时，关于x 的一元二次方程x2 - (2k - 3)x + (2k - 4) = 0 . ⑴有两个正根？ ⑵两根异号，且正根的绝对值较大？ ⑶一根大于3，一根小于3？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02167','math','初中',0,'jkp-0321','short_answer',0.38,'【易】已知关于x 的方程x2 + 2(m + 2)x+ m2 - 5 = 0 有两个实数根，并且这两个 根的平方和比这两个根的积大16，求m 的值.','','','','imported-junior-pdf','approved','通用','基础');
