INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02171','math','初中',0,'jkp-0321','short_answer',0.38,'【中】已知方程x2 + ax - b = 0的根是a 和c ，方程x2 + cx + d = 0 的根是b 和d ．其中 ，a 、b 、c 、d 为不同实数，求a 、b 、c 、d 的值.','','','','imported-junior-pdf','approved','通用','基础');
