INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02173','math','初中',0,'jkp-0321','short_answer',0.38,'【难】已知方程ax2 + 4x + b = 0 (a < 0) 的两实根为x1 、x2 ，方程ax2 + 3x + b = 0的 两实根为α 、β . ⑴若a 、b 均为负整数，且α- β= 1 ，求a 、b 的值 ；⑵若α<1 < β< 2 ，x1 < x2 ，求证：-2 < x1 <1< x2 . b a 四、利用根系关系求代数式的值','','','','imported-junior-pdf','approved','通用','基础');
