INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02177','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（2012 年潜江市中考题）如果关于x 的一元二次方程x2 + 4x + a = 0的两个不 相等实数根x1,x2 满足x1x2 - 2x1 - 2x2 - 5 = 0 ，那么a 的值为( ) A．3 B．-3 C．13 D．-13','','','','imported-junior-pdf','approved','通用','基础');
