INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02180','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（苏省南通市中考数学试题）设x1 、x2 是一元二次方程x2 + 4x - 3 = 0 的两个根， 2x1(x2 2 + 5x2 - 3) + a = 2 ，则a = . + 的值为( ) x1 x2 A ．5 B ．-5 C．1 D．-1 a b','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02181','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（孝感市高中阶段学校招生考试数学） 已知关于x 的一元二次方程x 2 - (2k +1)x + k 2 + 2k = 0 有两个实数根x1 、x2 . ⑴求实数k 的取值范围； ⑵是否存在实数k 使得x1 . x2 - x1 2 - x2 2 ≥0 成立？若存在，请求出k 的值；若不存在 ，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02182','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（怀化市中考题） 已知x1 ，x2 是一元二次方程(a - 6)x2 + 2ax + a = 0 的两个实数根. ⑴是否存在实数a ，使-x1 + x1x2 = 4 + x2 成立？若存在，求出a 的值；若不存在， 请说明理由. ⑵求使(x1 +1)(x2 +1) 为负整数的实数a 的整数值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02183','math','初中',0,'jkp-0321','short_answer',0.38,'【难】（内江市中考题）已知方程x2 + px+ q = 0 的两个根是x1,x2 ，那么x1 + x2 = -p ，x1 .x2 = q ，请根据以上结论，解决下列问题： ⑴已知关于x 的方程x2 + mx+ n = 0(n ≠0) ，求出一个一元二次方程，使它的两根分 别是已知方程两根的倒数； ⑵已知a、b 满足a2 -15a - 5 = 0 ，b2 -15b - 5 = 0 ，求 的值； ⑶已知a、b 均为实数，且a + b + c = 0,abc= 16 ，求正数c 的最小值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02184','math','初中',0,'jkp-0321','short_answer',0.38,'【难】（“TRULY®信利杯”竞赛题）已知实数a ≠b ，且满足(a +1)2 = 3 - 3(a +1) ， 3(b +1) = 3 - (b +1)2 ，则b· b + a· a 的值为( ) A ．23 B．-23 C．-2 D．-13','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02185','math','初中',0,'jkp-0321','short_answer',0.38,'【易】（北京市朝阳外国语学校2010-2011 学年初二期中）一元二次方程 x2 + px + q = 0 ，当p > 0 且q < 0 时方程( ) A ．两根异号，且负根的绝对值大 B．两根都是负数 C ．两根异号，且正根的绝对值大 D．两根都是正数','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02186','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（平谷区）已知一元二次方程x2 — 4x + k = 0 有两个不相等的实数根 ，⑴求k 的取值范围； ⑵如果k 是符合条件的最大整数，且关于x 的方程x2 — 4x + k = 0 与x2 — mx —1= 0 有 一个相同的根，求此时m 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02187','math','初中',0,'jkp-0321','short_answer',0.38,'【难】试求满足方程x2 — kx —7 = 0 与x 2 —6x —(k +1) = 0 有公共根的所有的k 值及所 有公共根和所有相异根.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02188','math','初中',0,'jkp-0321','short_answer',0.38,'【难】三个二次方程ax2 + bx + c = 0 ，bx2 + cx + a = 0 ，cx2 + ax + b = 0 有公共根. ⑴求证：a + b + c = 0； ⑵求 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02189','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（南充市高中阶段教育学校招生考试数学试卷） 关于x 的一元二次方程为(m —1)x 2 —2mx + m +1= 0 . ⑴求出方程的根； ⑵m 为何整数时，此方程的两个根都为正整数？','','','','imported-junior-pdf','approved','通用','基础');
