INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02193','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（密云一模） 已知：x1 、x2 分别为关于x 的一元二次方程mx2 + 2x + 2 —m = 0的两个实数根. ⑴设x1 、x2 均为两个不相等的非零整数根，求m 的整数值； ⑵利用图象求关于m 的方程x1 + x2 + m —1= 0 的解.','','','','imported-junior-pdf','approved','通用','基础');
