INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02195','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（昌平一模） 已知关于x 的方程(k +1)x 2 +(3k —1)x + 2k — 2 = 0 . ⑴讨论此方程根的情况； ⑵若方程有两个整数根，求正整数k 的值. ⑶若抛物线y = (k +1)x 2 +(3k —1)x + 2k — 2 与x 轴的两个交点之间的距离为3，求k 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02196','math','初中',0,'jkp-0321','short_answer',0.38,'【难】若k 为正整数，且关于k 的方程(k2 —1)x2 —6(3k —1)x + 72 = 0 有两个相异正整 数根，求k 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02197','math','初中',0,'jkp-0321','short_answer',0.38,'【难】（顺义一模） 已知关于x 的方程(k —1)x 2 + 2kx + k+ 3 = 0 . ⑴若方程有两个不相等的实数根，求k 的取值范围； ⑵当方程有两个相等的实数根时，求关于y 的方程y 2 + (a — 4k)y + a +1= 0 的整数 根（a 为正整数）. 五、有理根','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02198','math','初中',0,'jkp-0321','short_answer',0.38,'【难】设k 为整数，且k ≠0 ，方程kx 2 —(k —1)x +1= 0 有有理根，求k 的值 【一元二次方程的实际应用】 一、增长率 二、买涨价 三、储蓄问题 四、趣味问题 五、图形面积 六、数字乘积 一、增长率','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02199','math','初中',0,'jkp-0321','short_answer',0.38,'【中】(四川省绵阳市中考数学真题试题) “低碳生活，绿色出行” ，自行车正逐渐成为人们喜爱的交通工具.某运动商城的自行车 销售量自2013 年起逐月增加，据统计，该商城1 月份销.售自行车64 辆，3 月份销售 了100 辆. ⑴若该商城前4 个月的自行车销量的月平均增长率相同，问该商城4 月份卖出多少辆 自行车？ ⑵考虑到自行车需求不断增加，该商城准备投入3 万元再购进一批两种规格的自行车， 已知A 型车的进价为500 元/辆，售价为700 元/辆，B 型车进价为1000 元/辆，售价为 1300 元/辆.根据销售经验，A 型车不少于B 型车的2 倍，但不超过B 型车的2.8 倍.假 设所进车辆全部售完，为使利润最大，该商城应如何进货？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02200','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（浙江省初中毕业生学业考试（湖州市）） 随着人民生活水平的不断提高， 我市家庭轿车的拥有量逐年增加.据统计，某小区2006 年底拥有家庭轿车64 辆，2008 年底家庭轿车的拥有量达到100 辆. ⑴若该小区2006 年底到2009 年底家庭轿车拥有量的年平均增长率都相同，求该小区 到2009 年底家庭轿车将达到多少辆？ ⑵为了缓解停车矛盾，该小区决定投资15 万元再建造若干个停车位.据测算，建造费用 分别为室内车位5000 元/个，露天车位1000 元/个，考虑到实际因素，计划露天车位的 数量不少于室内车位的2 倍，但不超过室内车位的2.5 倍，求该小区最多可建两种车位 各多少个？试写出所有可能的方案. 二、买涨价','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02201','math','初中',0,'jkp-0321','short_answer',0.38,'【易】某商店如果将进货价8 元的商品按每件10 元出售，每天可销售200 件，现采用 提高售价，减少进货量的方法增加利润，已知这种商品每涨0.5 元，其销售量就可以 减少10 件，问应将售价定为多少时，才能使所赚利润最大，并求出最大利润','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02202','math','初中',0,'jkp-0321','short_answer',0.38,'【易】益群精品店以每件21 元的价格购进一批商品，该商品可以自行定价，若每件商 品售价a 元，则可卖出（350 —10a）件，但物价局限定每件商品的利润不得超过20%， 商店计划要盈利400 元，需要进货多少件？每件商品应定价多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02203','math','初中',0,'jkp-0321','short_answer',0.38,'【易】（淮安数学中考试题）小丽为校合唱队购买某种服装时，商店经理给出了如下 优惠条件，如果一次性购买不超过10 件，单价为80 元；如果一次性购买多于10 件， 那么每增加1 件，购买的所有服装的单价降低2 元，但单价不得低于50 元，按此优惠 条件，小丽一次性购买这种服装付了1200 元，请问她购买了多少件这种服装？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02204','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（绍兴市中考题）某公司投资新建了一商场，共有商铺30 间，据预测，当每间 的年租金定为10 万元时，可全部租出；每间的年租金每增加5000 元，少租出商铺1 间，该公司要为租出的商铺每间每年交各种费用1 万元，未租出去的商铺每间每年交 各种费用5000 元. ⑴当每间商铺的年租金定为13 万元时，能租出多少间？ ⑵当每间商铺的年租金定为多少万元时，该公司的年收益（收益=租金-各种费用）为 275 万元？ 三、储蓄问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02205','math','初中',0,'jkp-0321','short_answer',0.38,'【易】王红梅同学将1000 元压岁钱第一次按一年定期储蓄存入“少儿银行”，到期后将 本金和利息取出，并将其中的500 元捐给“希望工程”，剩余的又全部按一年定期存入， 这时存款的年利率已下调到第一次存款时年利率的90% ，这样到期后，可得本金和利 息共530 元，求第一次存款时的年利率.（假设不计利息税） 四、趣味问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02206','math','初中',0,'jkp-0321','short_answer',0.38,'【易】一个醉汉拿着一根竹竿进城，横着怎么也拿不进去，量竹竿长比城门宽4 米， 旁边一个醉汉嘲笑他，你没看城门高吗，竖着拿就可以进去啦，结果竖着比城门高2 米，二人没办法，只好请教聪明人，聪明人教他们二人沿着门的对角斜着拿，二人一 试，不多不少刚好进城，你知道竹竿有多长吗？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02207','math','初中',0,'jkp-0321','short_answer',0.38,'【易】 读诗词解题：（通过列方程式，算出周瑜去世时的年龄）. 大江东去浪淘尽，千古风流数人物； 而立之年督东吴，早逝英年两位数； 十位恰小个位三，个位平方与寿符； 哪位学子算得快，多少年华属周瑜？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02208','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（襄阳市初中毕业生学业考试数学试题）有一人患了流感，经过两轮传染后共 有64 人患了流感. ⑴求每轮传染中平均一个人传染了几个人？ ⑵如果不及时控制，第三轮将又有多少人被传染？ 五、图形面积','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02209','math','初中',0,'jkp-0321','short_answer',0.38,'【易】如图所示，某幼儿园有一道长为16 米的墙，计划用32 米长的围栏靠墙围成一 个面积为120 平方米的矩形草坪ABCD ．求该矩形草坪BC 边的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02210','math','初中',0,'jkp-0321','short_answer',0.38,'【易】用22 厘米长的铁丝，折成一个面积为30 平方厘米的长方形，求这个长方形的 长和宽。又问：能否折成面积是32 平方厘米的长方形呢？为什么？ 六、数字乘积','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02211','math','初中',0,'jkp-0321','short_answer',0.38,'【易】（西南宁中考）某单位要组织一次篮球联赛，赛制为单循环形式（每两队之间 都赛一场），计划安排10 场比赛，则参加比赛的球队应有( ) A．7 队 B．6 队 C．5 队 D．4 队','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02212','math','初中',0,'jkp-0321','short_answer',0.38,'【易】一容器装满20L 纯酒精，第一次倒出若干升后，用水加满，第二次又倒出同样 升数的混合液，再用水加满，容器里只有5L 的纯酒精，第一次倒出的酒精多少升？ （过程）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02213','math','初中',0,'jkp-0321','short_answer',0.38,'【易】如图所示，在△ABC 中，上C = 90o ，AC＝6cm ，BC＝8cm，点P 从点A 出 发沿边AC 向点C 以1cm / s 的速度移动，点Q 从C 点出发沿CB 边向点B 以2cm / s 的速度移动. （1）如果P、Q 同时出发，几秒钟后，可使△PCQ 的面积为8 平方厘米？ （2）点P、Q 在移动过程中，是否存在某一时刻，使得△PCQ 的面积等于△ABC 的面积的一半.若存在，求出运动的时间；若不存在，说明理由. 【可化为一元二次方程的其他方程】 一、含参的二次方程 二、含绝对值的二次方程 三、高次方程 四、分式方程 五、根式方程 六、与函数结合 一、含参的二次方程','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02214','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（武汉市武珞路中学补课资料）解方程ax2 + bx + c = 0 二、含绝对值的二次方程','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02215','math','初中',0,'jkp-0321','short_answer',0.38,'【中】（北京市朝阳外国语学校2010-2011 学年初二期中）阅读下面的例题：请参照 例题解方程x 2 —x —1 —1 = 0 例：x2 —x —2 = 0 解：⑴当x≥0 时，原方程化为x2 —x —2 = 0 解得x1 = 2 ，x2 = —1（不合题意，舍去） ⑵当x < 0 时，原方程化为x2 + x — 2 = 0 解得x1 = 1（不合题意，舍去），x2 = — 2 ∴原方程的根是x1 = 2 ，x2 = —2','','','','imported-junior-pdf','approved','通用','基础');
