INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02280','math','初中',0,'jkp-0213','short_answer',0.38,'已知f（x）为一次函数．若f（-3）＞0 且f（-1）=0 ，判断下列四个式 子，哪一个是正确的( ) A . f（0）＜0 B . f（2 ）＞0 C . f（-2 ）＜0 D . f（3）＞f（-2）','','','','imported-junior-pdf','approved','通用','基础');
