INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02285','math','初中',0,'jkp-0213','short_answer',0.38,'如图，把直线y=-2x 向上平秱后得到直线AB ，直线AB 经过点（a ，b）， 且2a+b=6 ，则直线AB 的解析式是( ) A ．y=-2x-3 B ．y=-2x-6 C ．y=-2x+3 D ．y=-2x+6','','','','imported-junior-pdf','approved','通用','基础');
