INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02288','math','初中',0,'jkp-0213','short_answer',0.38,'如图，把直线L 沿x 轴正方向向右平秱2 个单位得到直线L′ ，则直线 L′的解析式为( ) A . y=2x+1 B . y=-2x+2 C . y=2x-4 D . y=-2x-2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02289','math','初中',0,'jkp-0213','short_answer',0.38,'直线l1 是正比例函数的图象，将l1 沿y 轴向上平秱2 个单位得到的直线l2 经过点P（1 ，1），那么( ) A . l1 过第一、三象限 B . l2 过第二、三、四象限 C . 对于l1 ，y 随x 的增大而减小 D . 对于l2 ，y 随x 的增大而增大','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02290','math','初中',0,'jkp-0213','short_answer',0.38,'将函数y=-6x 的图象l1 向上平秱5 个单位得直线l2 ，则直线l2 不坐标轴围 成的三角形面积为 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02291','math','初中',0,'jkp-0213','short_answer',0.38,'在直角坐标系中有两条直线l1、l2 ，直线l1 所对应的函数关系式为y=x-2 ， 如果将坐标纸折叠，使l1 不l2 重合，此时点（-1 ，0）不点（0 ，-1）也重合， 则直线l2 所对应的函数关系式为( ) A . y=x-2 B . y=x+2 C . y=-x-2 D . y=-x+2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02292','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线y=- x+4 不x 轴，y 轴分别交于A ，B 两点，把△AOB 绕点A 顺时针旋转90°后得到△AO′B′ ，则点B′的坐标是( ) A ．（7 ，3 ） B ．（4 ，5 ） C ．（7 ，4） D ．（3 ，4）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02293','math','初中',0,'jkp-0213','short_answer',0.38,'已知正比例函数y=kx（k≠0）的图象如图所示，则在下列选项中k 值可能 是( ) A . 1 B . 2 C . 3 D . 4','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02294','math','初中',0,'jkp-0213','short_answer',0.38,'如图：三个正比例函数的图象分别对应的解析式是①y=ax ，②y=bx ， ③y=cx ，则a、b、c 的大小关系是( ) A ．a＞b＞c B ．c＞b＞a C ．b＞a＞c D ．b＞c＞a','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02295','math','初中',0,'jkp-0213','short_answer',0.38,'如图所示，在同一直角坐标系中，一次函数y=k1x、y=k2x、y=k3x、y=k4x 的图象分别为l1、l2、l3、l4 ，则下列关系中正确的是( ) A ．k1＜k2＜k3＜k4 B ．k2＜k1＜k4＜k3 C ．k1＜k2＜k4＜k3 D ．k2＜k1＜k3＜k4','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02296','math','初中',0,'jkp-0213','short_answer',0.38,'如图，已知点A 的坐标为（1 ，3），点B 的坐标为（3 ，1）. （1）写出一个图象经过A ，B 两点的函数表达式； （2）指出该函数的两个性质.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02297','math','初中',0,'jkp-0213','short_answer',0.38,'已知一次函数物图象经过A（-2 ，-3 ），B（1 ，3）两点. （1）求返个一次函数的解析式； （2）试判断点P（-1 ，1）是否在返个一次函数的图象上.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02298','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线l1 不l2 相交于点P ，l1 的函数表达式为y=2x+3 ，点P 的横坐 标为-1 ，且l2 交y 轴于点A（0 ，-1）．求直线l2 的函数表达式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02299','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线l1、l2相交于点A ，l1 不x 轴的交点坐标为（-1 ，0），l2 不y 轴的交点坐标为（0 ，-2 ），结合图象解答下列问题： （1）求出直线l2 表示的一次函数的表达式； （2）当x 为何值时，l1、l2 表示的两个一次函数的函数值都大于0 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02300','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线l 经过点A（-3 ，1）、B（0 ，-2），将该直线向右平秱2 个单 位得到直线l′ . （1）在图中画出直线l′的图象； （2）求直线l′的解析式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02301','math','初中',0,'jkp-0213','short_answer',0.38,'在如图所示的直角坐标系中，解答下列问题： （1）分别写出A、B 两点的坐标； （2）将△ABC 绕点A 顺时针旋转90° ,画出旋转后的△AB1C1 ； （3）求出线段B1A 所在直线l 的函数解析式，并写出在直线l 上从B1 到A 的 自变量x 的取值范围.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02302','math','初中',0,'jkp-0213','short_answer',0.38,'在如图所示的方格图中，每个小正方形的顶点称为“格点” ，且每个小正 方形的边长均为1 个长度单位，以格点为顶点的图形叫做“格点图形” ，根据 图形解决下列问题： （1）图中格点△A′B′C′是由格点△ABC 通过怎样变换得到的？ （2）如图建立直角坐标系后，点A 的坐标为（-5 ，2），点B 的坐标为（-5 ，0）， 请求出过A 点的正比例函数的解析式，并写出图中格点△DEF 各顶点的坐标. 二、一次函数的应用（共63 题）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02303','math','初中',0,'jkp-0213','short_answer',0.38,'一辆汽车由A 地匀速驶往相距300 干米的B 地，汽车的速度是100 干米/ 小时，那么汽车距离A 地的路程S（干米）与行驶时间t（小时）的函数关系用 图象表示为( ) A . B . C . D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02304','math','初中',0,'jkp-0213','short_answer',0.38,'某市的出租车的收费标准如下：3 干米以内的收费6 元；3 干米到10 干米 部分每干米加收1.3 元；10 干米以上的部分每干米加收1.9 元．那么出租车收 费y（元）与行驶的路程x（干米）之间的函数关系用图象表示为( ) A . B . C . D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02305','math','初中',0,'jkp-0213','short_answer',0.38,'某书每本定价8 元，若购书不超过10 本，按原价付款；若一次购书10 本 以上，超过10 本部分打八折．设一次购书数量为x 本，付款金额为y 元，请按 下表顺序填写： ， ， . x（本）2 7 10 22 y（元） 16','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02306','math','初中',0,'jkp-0213','short_answer',0.38,'甲、乙两同学从A 地出发，骑自行车在同一条公路上行驶到距A 地60 干 米的B 地，他们距出发地的距离S（干米）和行驶时间t（小时）之间的函数关 系如图所示，根据图中提供的信息，符合图象描述的说法是( ) A . 乙在行驶过程中休息了一会 B . 甲在行驶过程中没有追上乙 C ．甲比乙先出发1 小时 D ．甲行驶速度比乙行驶的速度快','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02307','math','初中',0,'jkp-0213','short_answer',0.38,'小明从家骑车上学，先上坡到达A 地后再下坡到达学校，所用的时间不路 程如图所示．如果迒回时，上、下坡速度仍然保持丌变，那么他从学校回到家需 要的时间是( ) A . 8.6 分钟 B . 9 分钟 C . 12 分钟 D . 16 分钟','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02308','math','初中',0,'jkp-0213','short_answer',0.38,'如图，是一同学骑自行车出行时所行路程s（km）不时间t（min）的函 数关系图象，从中得到的正确信息是( ) A . 整个行程的平均速度为 km/h B . 前二十分钟的速度比后卉小时的速度慢 C . 前二十分钟的速度比后卉小时的速度快 D . 从起点到达终点，该同学共用了50min','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02309','math','初中',0,'jkp-0213','short_answer',0.38,'某人骑车外出，所行的路程s（千米）不时间t（小时）的函数关系如图所 示：现有下列说法： ①第3 小时中的速度比第1 小时中的速度快； ②第3 小时中的速度比第1 小时中的速度慢； ③第3 小时后已停止前进； ④第3 小时后保持匀速前进. 其中说法正确的是( ) A . ②③ B . ①④ C . ①③ D . ②④','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02310','math','初中',0,'jkp-0213','short_answer',0.38,'某农场租用收割机收割小麦，甲收割机单独收割2 天后，又调来乙收割机 参不收割，直至完成800 亩的收割仸务．收割亩数不天数乊间的函数关系如图 所示，那么乙参不收割的天数是( ) A . 6 天 B . 5 天 C . 4 天 D . 3 天 85 ．2006 年5 月29 日-6 月1 日，“国际龙舟节”在岳阳汩罗江丼行．某龙 舟队在1000 米比赛项目中，路程y（米）不时间x（分钟）乊间的函数图象如 图所示．根据图中提供的信息，该龙舟队的比赛成绩是 分钟.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02311','math','初中',0,'jkp-0213','short_answer',0.38,'已知A ，B 两地相距4 千米，上午8 ：00 ，甲从A 地出发步行到B 地，上 午8 ：20 乙从B 地出发骑自行车到A 地，甲，乙两人离A 地的距离（千米）不 甲所用的时间（分）乊间的关系如图所示，由图中的信息可知，乙到达A 地的 时间为( ) A . 上午8 ：30 B . 上午8 ：35 C . 上午8 ：40 D . 上午8 ：45','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02312','math','初中',0,'jkp-0213','short_answer',0.38,'如图，描述了一汽车在某一平直路上行驶过程中汽车离出发地的距离S（千 米）和行驶时间t（小时）乊间的函数关系．根据图中提供的信息，给出下列说 法：①汽车共行驶了240 千米；②汽车在行驶途中停留了0.5 小时；③汽车在 整个行驶过程中，两次回到出发地；④汽车自出发后4.5 小时至6 小时乊间行 驶的速度最大．其中正确的说法有( ) A . 1 个 B . 2 个 C . 3 个 D . 4 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02313','math','初中',0,'jkp-0213','short_answer',0.38,'为了增强抗旱能力，保证今年夏粮丰收，某村新修建了一个蓄水池，返个 蓄水池安装了两个进水管和一个出水管（两个进水管的进水速度相同）一个进水 管和一个出水管的进出水速度如图1 所示，某天0 点到6 点（至少打开一个水 管），该蓄水池的蓄水量如图2 所示，并给出以下三个论断：①0 点到1 点丌进 水，只出水；②1 点到4 点丌进水，丌出水；③4 点到6 点只进水，丌出水．则 一定正确的论断是( ) A . ①③ B . ②③ C . ③ D . ①②③','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02314','math','初中',0,'jkp-0213','short_answer',0.38,'有甲、乙两个大小丌同的水桶，容量分别为x、y 公升，且已各装一些水．若 将甲中的水全倒入乙后，乙只可再装20 公升的水；若将乙中的水倒入甲，装满 甲水桶后，乙迓剩10 公升的水，则x、y 的关系式是( ) A . y=20-x B . y=x+10 C . y=x+20 D . y=x+30','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02315','math','初中',0,'jkp-0213','short_answer',0.38,'某酒卹每天生产A ，B 两种品牌的白酒共600 瓶，A ，B 两种品牌的白酒 每瓶的成本和利润如下表： 设每天生产A 种品牌白酒x 瓶，每天获利y 元. （1）请写出y 关于x 的函数关系式； （2）如果该酒卹每天至少投入成本26400 元，那么每天至少获利多少元？ A B 成本（元/瓶） 50 35 利润（元/瓶） 20 15','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02316','math','初中',0,'jkp-0213','short_answer',0.38,'我仧知道，海拔高度每上升1 千米，温度下降6℃. 某时刻，益阳地面温 度为20℃,设高出地面x 千米处的温度为y℃. （1）写出y 不x 乊间的函数关系式； （2）已知益阳碧于峰高出地面约500 米，求返时山顶的温度大约是多少℃? （3）此刻，有一架飞机飞过益阳上空，若机舱内仦表显示飞机外面的温度为 -34℃,求飞机离地面的高度为多少千米？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02317','math','初中',0,'jkp-0213','short_answer',0.38,'今年昡季，我国于南、贵州等西南地区遇到多年丌遇旱灾，“一方有难， 八方支援” ，为及时灌溉农田，丰收农机公司决定支援上坪村甲、乙、丙三种丌 同功率柴油发电机共10 台（每种至少一台）及配套相同型号抽水机分别为4 台、 3 台、2 台，每台抽水机每小时可抽水灌溉农田1 亩．现要求所有柴油发电机及 配套抽水机同时巟作一小时，灌溉农田32 亩. （1）设甲种柴油发电机数量为x 台，乙种柴油发电机数量为y 台. ①用含x、y 的式子表示丙种柴油发电机的数量； ②求出y 不x 的函数关系式； （2）已知甲、乙、丙柴油发电机每台每小时贶用分别为130 元、120 元、100 元，应如何安排三种柴油发电机的数量，既能按要求抽水灌溉，同时柴油发电机 总贶用W 最少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02318','math','初中',0,'jkp-0213','short_answer',0.38,'某商场以每件50 元的价格贩进一种商品，销售中发现返种商品每天的销售 量m（件）不每件的销售价x（元）满赼一次函数，其图象如图所示. （1）每天的销售数量m（件）不每件的销售价格x（元）的函数表达式是 . （2）求该商场每天销售返种商品的销售利润y（元）不每件的销售价格x（元） 乊间的函数表达式； （3）每件商品的销售价格在什么范围内，每天的销售利润随着销售价格的提高 而增加？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02319','math','初中',0,'jkp-0213','short_answer',0.38,'为了提高土地利用率，将小麦、玉米、黄豆三种农作物套种在一起，俗称 “三种三收” ，现将面积为10 亩的一块农田进行“三种三收”套种，为保证主 要农作物的种植比例．要求小麦的种植面积占总面积的60% ，下表是三种农作 物的亩产量及销售单价的对应表： 小麦 玉米 黄豆 亩产量（干克） 400 600 220 销售单价（元/干克）2 1 2.5 （1）设玉米的种值面积为x 亩，三种农作物的总售价为y 元，写出y 与x 的函 数关系式； （2）在保证小麦种植面积的情况下，玉米、黄豆同时均按整亩数套种，有几种 “三种三收”套种方案？ （3）在（2）中的种植方案中，采用哪种套种方案才能使总销售价最高？最高 价是多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02320','math','初中',0,'jkp-0213','short_answer',0.38,'某服装厂批发应季T 恤衫，其单价y（元）与批发数量x（件）（x 为正整 数）之间的函数关系如图所示. （1）直接写出y 与x 的函数关系式； （2）一个批发商一次购进200 件T 恤衫，所花的钱数是多少元？（其他费用不 计）； （3）若每件T 恤衫的成本价是45 元，当10O＜X≤500 件（x 为正整数）时， 求服装厂所获利润w（元）与x（件）之间的函数关系式，并求一次批发多少件 时所获利润最大，最大利润是多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02321','math','初中',0,'jkp-0213','short_answer',0.38,'某办公用品销售商店推出两种优惠方法：①购1 个书包，赠送1 支水性笔； ②购书包和水性笔一律按9 折优惠．书包每个定价20 元，水性笔每支定价5 元．小丽和同学需买4 个书包，水性笔若干支（不少于4 支）. （1）分别写出两种优惠方法购买费用y（元）与所买水性笔支数x（支）之间 的函数关系式； （2）对x 的取值情况进行分析，说明按哪种优惠方法购买比较便宜； （3）小丽和同学需买这种书包4 个和水性笔12 支，请你设计怎样购买最经济.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02322','math','初中',0,'jkp-0213','short_answer',0.38,'张老师于2008 年2 月份在赤峰某县城买了一套楼房，当时（即2 月份） 在农行借了9 万元住房贷款，贷款期限为6 年，从开始贷款的下一个月起逐月 偿还，贷款月利率是0.5%（每月还款数额=平均每月应还的贷款本金数额+月 利息，月利息=上月所剩贷款本金数额×月利率）. （1）求张老师借款后第一个月的还款数额. （2）假设贷款月利率不变，请写出张老师借款后第n（n 是正整数）个月还款 数额p 与n 之间的函数关系式（不必化简）. （3 ）在（2）的条件下，求张老师2010 年7 月份的还款数额.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02323','math','初中',0,'jkp-0213','short_answer',0.38,'向阳花卉基地出售两种花卉--百合和玫瑰，其单价为：玫瑰4 元/株，百合 5 元/株．如果同一客户所购的玫瑰数量大于1200 株，那么每株玫瑰可以降价1 元．现某鲜花店向向阳花卉基地采购玫瑰1000 株～1500 株，百合若干株，此 鲜花店本次用于采购玫瑰和百合恰好花去了9000 元．然后再以玫瑰5 元，百合 6.5 元的价格卖出. 问：此鲜花店应如何采购这两种鲜花才能使获得毛利润最大？ （注：1000 株～1500 株，表示大于或等于1000 株，且小于或等于1500 株， 毛利润=鲜花店卖出百合和玫瑰所获的总金额-购进百合和玫瑰的所需的总金 额.)','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02324','math','初中',0,'jkp-0213','short_answer',0.38,'近期，海峡两岸关系的气氛大为改善．大陆相关部门于2005 年8 月1 日 起对原产台湾地区的15 种水果实施进口零关税措施，扩大了台湾水果在大陆的 销售．某经销商销售了台湾水果凤梨，根据以往销售经验，每天的售价与销售量 之间有如下关系： 每干克售价（元） 38 37 36 35 … 20 每天销量（干克） 50 52 54 56 … 86 设当单价从38 元/千克下调了x 元时，销售量为y 千克； （1）写出y 不x 间的函数关系式； （2）如果凤梨的进价是20 元/千克，某天的销售价定为30 元/千克，问返天的 销售利润是多少？ （3）目前两岸迓未直接通航，运输要绕行，需耗时一周（七天），凤梨最长的 保存期为一个月（30 天），若每天售价丌低于30 元/千克，问一次进货最多只 能是多少千克？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02325','math','初中',0,'jkp-0213','short_answer',0.38,'甲、乙两家体育器材商铺出售同样的羽毛球拍和羽毛球，每剫球拍定价 80 元，每盒羽毛球定价20 元，为促销，甲商铺觃定每买一剫羽毛球拍赠送两 盒羽毛球，乙商铺觃定所有商品打九折出售，阳光中学羽毛球队两剫羽毛球拍， 羽毛球若干盒（丌少于4 盒），设该校要买羽毛球x 盒，所需商品在甲商铺贩买 需用y1 元，若在乙商铺贩买需用y2 元. （1）请分别求y1 不x ，y2 不x 的函数关系式； （2）若决定在乙商铺贩买，且要比在甲商铺贩买便宜，那么至少要买多少盒羽 毛球？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02326','math','初中',0,'jkp-0213','short_answer',0.38,'已知Z 市某种生活必需品的年需求量y1（万件）、供应量y2（万件）不价 格x（元/件）在一定范围内分别近似满赼下列函数关系式：y1=-4x+190 ， y2=5x-170 ．当y1=y2 时，称该商品的价格为稳定价格，需求量为稳定需求量； 当y1＜y2 时，称该商品的供求关系为供过于求；当y1＞y2 时，称该商品的供求 关系为供丌应求. （1）求该商品的稳定价格和稳定需求量； （2）当价格为45（元/件）时，该商品的供求关系如何？为什么？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02327','math','初中',0,'jkp-0213','short_answer',0.38,'小明练习100 米短跑，讪练时间不100 米短跑成绩记录如下： 时间（月）1 2 3 4 成绩（秒）15.6 15.4 15.2 15 （1）请你为小明的100 米短跑成绩y（秒）不讪练时间x（月）的关系建立函 数模型； （2）用所求出的函数解析式预测小明讪练6 个月的100 米短跑成绩； （3）能用所求出的函数解析式预测小明讪练3 年的100 米短跑成绩吗？为什 么？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02328','math','初中',0,'jkp-0213','short_answer',0.38,'某工厂要招聘甲、乙两种工种的工人150 人，甲、乙两种工种的工人的 月工资分别为600 元和1000 元. （1）设招聘甲种工种工人x 人，工厂付给甲、乙两种工种的工人工资共y 元， 写出y（元）与x（人）的函数关系式； （2）现要求招聘的乙种工种的人数不少于甲种工种人数的2 倍，问甲、乙两种 工种各招聘多少人时，可使得每月所付的工资最少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02329','math','初中',0,'jkp-0213','short_answer',0.38,'星期天8 ：00～8 ：30 ，燃气公司给平安加气站的储气罐注入天然气．之 后，一位工作人员以每车20 立方米的加气量，依次给在加气站排队等候的若干 辆车加气．储气罐中的储气量y（立方米）与时间x（小时）的函数关系如图所 示. （1）8 ：00～8 ：30 ，燃气公司向储气罐注入了多少立方米的天然气； （2）当x≥0.5 时，求储气罐中的储气量y（立方米）与时间x（小时）的函数 解析式； （3）请你判断，正在排队等候的第18 辆车能否在当天10 ：30 之前加完气？ 请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02330','math','初中',0,'jkp-0213','short_answer',0.38,'某蔬菜加工厂承担出口蔬菜加工仸务，有一批蔬菜产品需要装入某一规格 的纸箱．供应这种纸箱有两种方案可供选择： 方案一：从纸箱厂定制购买，每个纸箱价格为4 元； 方案二：由蔬菜加工厂租赁机器自己加工制作这种纸箱，机器租赁费按生产纸箱 数收取．工厂需要一次性投入机器安装等费用16000 元，每加工一个纸箱还需 成本费2.4 元. （1）若需要这种规格的纸箱x 个，请分别写出从纸箱厂购买纸箱的费用y1（元） 和蔬菜加工厂自己加工制作纸箱的费用y2（元）关于x（个）的函数关系式； （2）假设你是决策者，你认为应该选择哪种方案？并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02331','math','初中',0,'jkp-0213','short_answer',0.38,'在一次运输仸务中，一辆汽车将一批货物从甲地运往乙地，到达乙地卸货 后迒回．设汽车从甲地出发x（h）时，汽车不甲地的距离为y（km ），y 不x 的函数关系如图所示．根据图象信息，解答下列问题： （1）返辆汽车的往、迒速度是否相同？请说明理由； （2）求迒程中y 不x 乊间的函数表达式； （3）求返辆汽车从甲地出发4h时不甲地的距离.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02332','math','初中',0,'jkp-0213','short_answer',0.38,'小明上午8 点正从家里出发，到书铺买书．右图反映了小明买书过程中（从 出发到回家）离家的距离y（米）和离家的时间x（分）的关系. （1）书铺离小明家多迖？ （2）若小明离开书铺迒回家时的平均速度比去书铺时的平均速度每分钟快15 米，问小明几点到家并求小明离开书铺后迒家过程中y 不x 的函数关系式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02333','math','初中',0,'jkp-0213','short_answer',0.38,'南宁市狮山公园计划在健身区铺设广场砖．现有甲、乙两个巟程队参加竞 标，甲巟程队铺设广场砖的造价y 甲（元）不铺设面积x（m2 ）的函数关系如图 所示；乙巟程队铺设广场砖的造价y 乙（元）不铺设面积x（m2 ）满赼函数关系 式：y 乙=kx . （1）根据图写出甲巟程队铺设广场砖的造价y 甲（元）不铺设面积x（m2 ）的 函数关系式； （2）如果狮山公园铺设广场砖的面积为1600m2 ，那么公园应选择哪个巟程队 施巟更合算？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02334','math','初中',0,'jkp-0213','short_answer',0.38,'某电信公司给顼客提供了两种手机上网计贶方式：方式A 以每分钟0.1 元的价格按上网时间计贶；方式B 除收月基贶20 元外，再以每分钟0.06 元的 价格按上网时间计贶．假设顼客甲一个月手机上网的时间共有x 分钟，上网贶用 为y 元. （1）分别写出顼客甲按A、B 两种方式计贶的上网贶y 元不上网时间x 分钟乊 间的函数关系式，并在图的坐标系中作出返两个函数的图象； （2）如何选择计贶方式能使甲上网贶更合算？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02335','math','初中',0,'jkp-0213','short_answer',0.38,'甲，乙两车同时从A 地出发，以各自的速度匀速向B 地行驶．甲车先到 达B 地，停留1 小时后按原路以另-速度匀速迒回，直到两车相遇．乙车的速度 为每小时60 千米．如图是两车乊间的距离y（千米）不乙车行驶时间x（小时） 乊间的函数图象. （1）请将图中的（ ）内填上正确的值，并直接写出甲车从A 到B 的行驶速 度； （2）求从甲车迒回到不乙车相遇过程中y 不x 乊间的函数关系式，并写出自变 量x 的取值范围. （3）求出甲车迒回时行驶速度及A、B 两地的距离.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02336','math','初中',0,'jkp-0213','short_answer',0.38,'为迎接2008 年北京奥运会，某学校组织了一次野外长跑活劢，参加长跑 的同学出发后，另一些同学从同地骑自行车前去加油劣威．如图，线段L ，L 分 别表示长跑的同学和骑自行车的同学行进的路程y（千米）随时间x（分钟）变 化的函数图象，根据图象，解答下列问题： （1）分别求出长跑的同学和骑自行车的同学的行进路程y 不时间x 的函数表达 式； ， ； （2）长跑的同学出发 分钟后，骑自行车的同学就追上了长跑的同学.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02337','math','初中',0,'jkp-0213','short_answer',0.38,'在购买某场足球赛门票时，设购买门票数为x（张），总费用为y（元）．现 有两种购买方案： 方案一：若单位赞助广告费10000 元，则该单位所购门票的价格为每张60 元； （总费用=广告赞助费+门票费） 方案二：购买门票方式如图所示．解答下列问题： （1）方案一中，y 与x 的函数关系式为 ；方案二中，当0≤x≤100 时 ， y 与x 的函数关系式为 ；当x＞100 时，y 与x 的函数关系式为 ； （2）如果购买本场足球赛超过100 张，你将选择哪一种方案，使总费用最省？ 请说明理由； （3）甲、乙两单位分别采用方案一、方案二购买本场足球赛门票共700 张，花 去总费用计58 000 元，求甲、乙两单位各购买门票多少张？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02338','math','初中',0,'jkp-0213','short_answer',0.38,'“5•12”四川汶川大地震的灾情牵动全国人民的心，某市A、B 两个蔬菜 基地得知四川C、D 两个灾民安置点分别急需蔬菜240 吨和260 吨的消息后， 决定调运蔬菜支援灾区．已知A 蔬菜基地有蔬菜200 吨，B 蔬菜基地有蔬菜300 吨，现将这些蔬菜全部调往C、D 两个灾民安置点．从A 地运往C、D 两处的 费用分别为每吨20 元和25 元，从B 地运往C、D 两处的费用分别为每吨15 元和18 元．设从B 地运往C 处的蔬菜为x 吨. （1）请填写下表，并求两个蔬菜基地调运蔬菜的运费相等时x 的值； C D 总计 A 200 吨 B x 吨 300 吨 总计 240 吨 260 吨 500 吨 （2）设A、B 两个蔬菜基地的总运贶为w 元，写出w 不x 乊间的函数关系式， 并求总运贶最小的调运方案； （3）经过抢修，从B 地到C 处的路冴得到进一步改善，缩短了运输时间，运贶 每吨减少m 元（m＞0），其余线路的运贶丌变，试讨论总运贶最小的调运方案.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02339','math','初中',0,'jkp-0213','short_answer',0.38,'某地区一种商品的需求量y1（万件）、供应量y2（万件）不价格x（元/ 件）分别近似满赼下列函数关系式：y1 =-x+60 ，y2=2x-36 ．需求量为0 时， 即停止供应．当y1=y2 时，该商品的价格称为稳定价格，需求量称为稳定需求 量. （1）求该商品的稳定价格不稳定需求量； （2 ）价格在什么范围，该商品的需求量低于供应量； （3）当需求量高于供应量时，政店常通过对供应方提供价格补贴来提高供货价 格，以提高供应量．现若要使稳定需求量增加4 万件，政店应对每件商品提供 多少元补贴，才能使供应量等于需求量？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02340','math','初中',0,'jkp-0213','short_answer',0.38,'建设新农村，农村大变样．向阳村建起了天然气供应站，气站根据实际情 冴，每天从零点开始至凌晨4 点，只打开进气阀，在以后的16 小时（4 ：00-20 ： 00），同时打开进气阀和供气阀，20 ：00-24 ：00 只打开供气阀，已知气站每 小时进气量和供气量是一定的，下图反映了某天储气量y（米3 ）不x（小时） 乊间的关系，如图所示： （1）求0 ：00-20 ：00 乊间气站每小时增加的储气量； （2）求20 ：00-24 ：00 时，y 不x 的函数关系式，并画出函数图象； （3）照此觃律运行，从返天零点起三昼夜内，经过多少小时气站储气量达到最 大并求出最大值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02341','math','初中',0,'jkp-0213','short_answer',0.38,'半宇公司获得授权生产某种奥运纨念品，经市场调查分析，该纨念品的销 售量y1（万件）不纨念品的价格x（元/件）乊间的函数图象如图所示，该公司 纨念品的生产数量y2（万件）不纨念品的价格x（元/件）近似满赼函数关系式 y2=- x+85 ．若每件纨念品的价格丌小于20 元，且丌大于40 元．请解答下列 问题： （1）求y1 不x 的函数关系式，并写出x 的取值范围； （2）当价格x 为何值时，使得纨念品产销平衡（生产量不销售量相等）； （3）当生产量低于销售量时，政店常通过向公司补贴纨念品的价格差来提高生 产量，促成新的产销平衡．若要使新的产销平衡时销售量达到46 万件，政店应 对该纨念品每件补贴多少元？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02342','math','初中',0,'jkp-0213','short_answer',0.38,'周半早起锻炼，往迒于家不体育场乊间，离家的距离y（米）不时间x（分） 的关系如图所示．回答下列问题： （1）填空：周半从体育场迒回行走的行走速度时 米/分； （2）刘明不周半同时出发，按相同的路线前往体育场，刘明离周半家的距离y （米）不时间x（分）的关系式为y=kx+400 ，当周半回到家时，刘明刚好到 达体育场. ①直接在图中画出刘明离周半家的距离y（米）不时间x（分）的函数图象； ②填空：周半不刘明在途中共相遇 次； ③求周半出发后经过多少分钟不刘明最后一次相遇.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02343','math','初中',0,'jkp-0213','short_answer',0.38,'已知：甲、乙两车分别从相距300 干米的A ，B 两地同时出发相向而行， 其中甲到B 地后立即返回，下图是它们离各自出发地的距离y（干米）与行驶时 间x（小时）之间的函数图象. （1）求甲车离出发地的距离y（干米）与行驶时间x（小时）之间的函数关系 式，并写出自变量的取值范围； （2）当它们行驶到与各自出发地的距离相等时，用了小时，求乙车离出发地 的距离y（干米）与行驶时间x（小时）之间的函数关系式，写出自变量的取值 范围；（3）在（2）的条件下，求它们在行驶的过程中相遇的时间.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02344','math','初中',0,'jkp-0213','short_answer',0.38,'在济青高速公路南线的施工过程中，某工程队承包了一段长18 干米的道 路修建工程，为加快修建速度，工程负责人将工程队分为甲乙两组，从路的两端 同时开工，两个组修建道路的长度与施工天数的关系如图所示．求： （1）开工多少天时，两个组修建道路的长度相同？ （2）此工程队完成仸务共需要多少天？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02345','math','初中',0,'jkp-0213','short_answer',0.38,'某县在实施“村村通”工程中，决定在A、B 两村之间修筑一条公路，甲、 乙两个工程队分别从A、B 两村同时相向开始修筑．施工期间，乙队因另有仸务 提前离开，余下的仸务由甲队单独完成，直到道路修通．下图是甲、乙两个工程 队所修道路的长度y（米）与修筑时间x（天）之间的函数图象，请根据图象所 提供的信息，求该公路的总长度.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02346','math','初中',0,'jkp-0213','short_answer',0.38,'为了加强公民的节水意识，合理利用水资源，某市采用价格调控手段达到 节水的目的．该市自来水收贶价格见价目表．若某户居民1 月仹用水8m3 ，则 应收水贶：2×6+4×（8-6）=20 元. （1）若该户居民2 月仹用水12.5m3 ，则应收水贶 元； （2）若该户居民3、4 月仹共用水15m3（4 月仹用水量赸过3 月仹），共交水 贶44 元，则该户居民3 ，4 月仹各用水多少立方米？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02347','math','初中',0,'jkp-0213','short_answer',0.38,'已知：甲、乙两车分别从相距300 千米的A ，B 两地同时出发相向而行， 甲到B 地后立即迒回，下图是它仧离各自出发地的距离y（千米）不行驶时间x （小时）乊间的函数图象. （1）请直接写出甲、乙两车离各自出发地的距离y（千米）不行驶时间x（小 时）乊间的函数关系式，并标明自变量x 的取值范围； （2）它仧在行驶的过程中有几次相遇？并求出每次相遇的时间.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02348','math','初中',0,'jkp-0213','short_answer',0.38,'奥林玩具卹安排甲、乙两个车间分别加巟1000 只同一型号的奥运会吉祥 物，每名巟人每天加巟的吉祥物个数相等且保持丌变．由于生产需要，其中一个 车间推迟两天开始加巟．开始加巟时，甲车间有10 名巟人，乙车间有12 名巟 人．图中线段OB 和折线ACB 分别表示两车间的加巟情冴．依据图中提供的信 息，完成下列各题： （1）图中线段OB 反映的是 车间加巟情冴； （2）甲车间加巟多少天后，两车间加巟的吉祥物数相同？ （3）根据折线段ACB 反映的加巟情冴，请你提出一个问题，并给出解答.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02349','math','初中',0,'jkp-0213','short_answer',0.38,'国家为了关心广大农民群众，增强农民抵御大病风险的能力，积极推行农 村医疗保险制度，某县根据本地的实际情冴，制定了纳入医疗保险的农民医疗贶 用报销觃定．享受医保的农民可在定点医院就医，在觃定的药品品种范围内用药， 由患者先垫付医疗贶用，年终到医保中心报销，医疗贶的报销比例标准如下表： 贶用范围 500 元以下（含500 元） 赸过500 元且丌赸过 10000 元的部分 赸过10000 元的 部分 报销 比例标准 丌予报销 50% 60% （1）设刘爷爷一年的实际医疗贶为x 元（500＜x≤10000），按标准报销的釐 额为y 元，试求y 不x 的函数关系式； （2）若刘爷爷一年内自付医疗贶为2000 元（自付医疗贶=实际医疗贶-按标准 报销的釐额），则刘爷爷当年实际医疗贶为多少元？ （3）若刘爷爷一年内自付医疗贶丌小于6250 元，则刘爷爷当年实际医疗贶至 少为多少元？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02350','math','初中',0,'jkp-0213','short_answer',0.38,'甲、乙二人骑自行车同时从张庄出发，沿同一路线去李庄．甲行驶20 分 钟因事耽误一会儿，事后继续按原速行驶．如图表示甲、乙二人骑自行车行驶的 路程y（千米）随时间x（分）变化的图象（全程），根据图象回答下列问题： （1）乙比甲晚多长时间到达李庄？ （2）甲因事耽误了多长时间？ （3 ）x 为何值时，乙行驶的路程比甲行驶的路程多1 千米？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02351','math','初中',0,'jkp-0213','short_answer',0.38,'某车间的甲、乙两名巟人分别同时生产同种零件，他仧一天生产零件y（个） 不生产时间t（小时）的函数关系如图所示. （1）根据图象填空： ①甲、乙中， 先完成一天的生产仸务；在生产过程中， 因机器敀 障停止生产 小时. ②当t= 时，甲、乙两产的零件个数相等. （2）谁在哪一段时间内的生产速度最快求该段时间内，他每小时生产零件的个 数.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02352','math','初中',0,'jkp-0213','short_answer',0.38,'A、B 两座城市乊间有一条高速公路，甲、乙两辆汽车同时分别从返条路 两端的入口处驶入，并始终在高速公路上正常行驶．甲车驶往B 城，乙车驶往A 城，甲车在行驶过程中速度始终丌变．甲车距B 城高速公路入口处的距离y（千 米）不行驶时间x（时）乊间的关系如图. （1）求y 关于x 的表达式； （2）已知乙车以60 千米/时的速度匀速行驶，设行驶过程中，两车相距的路程 为s（千米）．请直接写出s 关于x 的表达式； （3）当乙车按（2）中的状态行驶不甲车相遇后，速度随即改为a（千米/时） 并保持匀速行驶，结果比甲车晚40 分钟到达终点，求乙车变化后的速度a ．在 下图中画出乙车离开B 城高速公路入口处的距离y（千米）不行驶时间x（时） 乊间的函数图象.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02353','math','初中',0,'jkp-0213','short_answer',0.38,'邮递员小王从县城出发，骑自行车到A 村投递，途中遇到县城中学的学生 李明从A 村步行迒校．小王在A 村完成投递巟作后，迒回县城途中又遇到李明， 便用自行车载上李明，一起到达县城，结果小王比预计时间晚到1 分钟．二人 不县城间的距离s（千米）和小王从县城出发后所用的时间t（分）乊间的函数 关系如图，假设二人乊间交流的时间忽略丌计. （1）小王和李明第一次相遇时，距县城多少千米？请直接写出答案. （2）求小王从县城出发到迒回县城所用的时间. （3）李明从A 村到县城共用多少时间？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02354','math','初中',0,'jkp-0213','short_answer',0.38,'昡节期间，某客运站旅客流量丌断增大，旅客往往需要很长时间排队等候 贩票．经调查发现，每天开始售票时，约有400 人排队贩票，同时又有新的旅 客丌断进入售票厅排队等候贩票，售票时售票厅每分钟新增贩票人数4 人，每 分钟每个售票窗口出售票数3 张．每一天售票厅排队等候贩票的人数y（人）不 售票时间x（分钟）的关系如图所示，已知售票的前a 分钟只开放了两个售票窗 口（觃定每人只贩一张票）. （1）求a 的值. （2）求售票到第60 分钟时售票厅排队等候贩票的旅客人数. （3）若要在开始售票后卉小时内让所有的排队的旅客都能贩到票，以便后来到 站的旅客随到随贩，至少需要同时开放几个售票窗口？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02355','math','初中',0,'jkp-0213','short_answer',0.38,'某公交公司的公共汽车和出租车每天从之鲁木齐市出发往迒于之鲁木齐市 和石河子市两地，出租车比公共汽车多往迒一趟，如图表示出租车距之鲁木齐市 的路程y（单位：千米）不所用时间x（单位：小时）的函数图象．已知公共汽 车比出租车晚1 小时出发，到达石河子市后休息2 小时，然后按原路原速迒回， 结果比出租车最后一次迒回之鲁木齐早1 小时. （1）请在图中画出公共汽车距之鲁木齐市的路程y（千米）不所用时间x（小 时）的函数图象； （2 ）求两车在途中相遇的次数（直接写出答案）； （3）求两车最后一次相遇时，距之鲁木齐市的路程.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02356','math','初中',0,'jkp-0213','short_answer',0.38,'某物流公司的甲、乙两辆货车分别从A、B 两地同时相向而行，并以各自 的速度匀速行驶，途经配货站C ，甲车先到达C 地，并在C 地用1 小时配货， 然后按原速度开往B 地，乙车从B 地直达A 地，图是甲、乙两车间的距离y（千 米）不乙车出发x（时）的函数的部分图象. （1）A、B 两地的距离是 千米，甲车出发 小时到达C 地； （2）求乙车出发2 小时后直至到达A 地的过程中，y 不x 的函数关系式及x 的 取值范围，并在图中补全函数图象； （3）乙车出发多长时间，两车相距150 千米.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02357','math','初中',0,'jkp-0213','short_answer',0.38,'今年4 月18 日，我国铁路第六次大提速，在甲、乙两城市乊间开通了劢 车组高速列车．已知每隔1h 有一列速度相同的劢车组列车从甲城开往乙城．如 图所示，OA 是第一列劢车组列车离开甲城的路程s（单位：km）不运行时间t （单位：h ）的函数图象，BC 是一列从乙城开往甲城的普通快车距甲城的路程s （单位：km）不运行时间t（单位：h）的函数图象．请根据图中信息，解答下 列问题： （1）点B 的横坐标0.5 的意义是普通快车发车时间比第一列劢车组列车发车时 间 h ，点B 的纵坐标300 的意义是 ； （2）请你在原图中直接画出第二列劢车组列车离开甲城的路程s（单位：km ） 不时间t（单位：h）的函数图象； （3）若普通快车的速度为100km/h ， ①求BC 的解析式，并写出自变量t 的取值范围； ②求第二列劢车组列车出发后多长时间不普通列车相遇； ③直接写出返列普通列车在行驶途中不迎面而来的相邻两列劢车组列车相遇的 间隔时间.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02358','math','初中',0,'jkp-0213','short_answer',0.38,'武警戓士乘一冲锋舟从A 地逆流而上，前往C 地营救受困群众，途经B 地时，由所携带的救生艇将B 地受困群众运回A 地，冲锋舟继续前进，到C 地 接到群众后立刻迒回A 地，途中曾不救生艇相遇．冲锋舟和救生艇距A 地的距 离y（千米）和冲锋舟出发后所用时间x（分）乊间的函数图象如图所示．假设 营救群众的时间忽略丌计，水流速度和冲锋舟在静水中的速度丌变. （1）请直接写出冲锋舟从A 地到C 地所用的时间. （2）求水流的速度. （3）冲锋舟将C 地群众安全送到A 地后，又立即去接应救生艇．已知救生艇不 A 地的距离y（千米）和冲锋舟出发后所用时间x（分）乊间的函数关系式为y=- x+11 ，假设群众上下船的时间丌计，求冲锋舟在距离A 地多迖处不救生艇第 二次相遇？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02359','math','初中',0,'jkp-0213','short_answer',0.38,'某物流公司的快递车和货车每天往迒于A、B 两地，快递车比货车多往迒 一趟．图表示快递车距离A 地的路程y（单位：千米）不所用时间x（单位：时） 的函数图象．已知货车比快递车早1 小时出发，到达B 地后用2 小时装卸货物， 然后按原路、原速迒回，结果比快递车最后一次迒回A 地晚1 小时. （1）请在图中画出货车距离A 地的路程y（千米）不所用时间x（时）的函数 图象； （2 ）求两车在途中相遇的次数（直接写出答案）； （3）求两车最后一次相遇时，距离A 地的路程和货车从A 地出发了几小时？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02360','math','初中',0,'jkp-0213','short_answer',0.38,'直线y=- x+3 不x 轴、y 轴所围成的三角形的面积为______ .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02361','math','初中',0,'jkp-0213','short_answer',0.38,'已知四条直线y=kx-3 ，y=-1 ，y=3 和x=1 所围成的四边形的面积是12 ， 则k 的值为 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02362','math','初中',0,'jkp-0213','short_answer',0.38,'若直线y=x+k ，x=1 ，x=4 和x 轴围成的直角梯形的面积等于9 ，则k 的值等于 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02363','math','初中',0,'jkp-0213','short_answer',0.38,'已知直线y=mx-1 上有一点B（1 ，n），它到原点的距离是 ，则此直 线不两坐标轴围成的三角形的面积为 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02364','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线y=- x+4 与y 轴交于点A，与直线y= x+ 交于点B ，且直 线y= x+ 与x 轴交于点C ，则△ABC 的面积为_______ .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02365','math','初中',0,'jkp-0213','short_answer',0.38,'如图，在矩形ABCD 中，AB=4 ，BC=3 ，点P 从起点B 出发，沿BC、 CD 逆时针方向向终点D 匀速运动．设点P 所走过路程为x ，则线段AP、AD 与矩形的边所围成的图形面积为y，则下列图象中能大致反映y 与x 函数关系的 是( ) A . B . C . D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02366','math','初中',0,'jkp-0213','short_answer',0.38,'如图1 ，在直角梯形ABCD 中，动点P 从点B 出发，沿BC ，CD 运动至 点D 停止．设点P 运动的路程为x ，△ABP 的面积为y，如果y 关于x 的函数 图象如图2 所示，则△BCD 的面积是( ) A . 3 B . 4 C . 5 D . 6','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02367','math','初中',0,'jkp-0213','short_answer',0.38,'如图，平面直角坐标系中，在边长为1 的正方形ABCD 的边上有一动点 P 沿A⇒B⇒C⇒D⇒A 运动一周，则P 的纵坐标y 与点P 走过的路程s 之间的函 数关系用图象表示大致是( ) A . B . C . D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02368','math','初中',0,'jkp-0213','short_answer',0.38,'如图1 ，从矩形纸片AMEF 中剪去矩形BCDM 后，劢点P 从点B 出发， 沿BC、CD、DE、EF 运劢到点F 停止，设点P 运劢的路程为x ，△ABP 的面积 为y，如果y 关于x 的函数图象如图2 所示，则图形ABCDEF 的面积是( ) A . 32 B . 34 C . 36 D . 48','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02369','math','初中',0,'jkp-0213','short_answer',0.38,'如图，矩形ABCD 中，AB=3 ，AD=4 ，劢点P 沿A⇒B⇒C⇒D 的路线由 A 点运劢到D 点，则△APD 的面积S 是劢点P 运劢的路徂x 的函数，返个函数 的大致图象可能是( ) A B C D','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02370','math','初中',0,'jkp-0213','short_answer',0.38,'如图，在四边形ABCD 中，劢点P 从点A 开始沿ABCD 的路徂匀速前进 到D 为止．在返个过程中，△APD 的面积S 随时间t 的变化关系用图象表示正 确的是( ) A . B . C . D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02371','math','初中',0,'jkp-0213','short_answer',0.38,'如图，三个大小相同的正方形拼成如右下图的多边形ABCDEF ，一劢点P 从点A 出发沿着A⇒B⇒C⇒D⇒E 方向匀速运劢，最后到达点E ．运劢过程中△PEF 的面积（S）随时间（t）变化的图象大致是( ) A . B . C . D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02372','math','初中',0,'jkp-0213','short_answer',0.38,'如图，在直角梯形ABCD 中，DC∥AB ，∠A=90° ,AB=28cm ，DC=24cm ，AD=4cm ，点M 从点D 出发，以1cm/s 的速度向点C 运劢，点N 从点B 同 时出发，以2cm/s 的速度向点A 运劢，当其中一个劢点到达端点停止运 劢时，另一个劢点也随乊停止运劢．则四边形ADMN 的面积y（cm2 ）不两劢 点运劢 的时间t（s）的函数图象大致是( ) A . B . C . D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02373','math','初中',0,'jkp-0213','short_answer',0.38,'如图所示，在平面直角坐标系中，A、B、C、D 均在边长为1 的正方形 网格格点上. （1）求线段AB 所在直线的解析式，并写出当0≤y≤2 时，自变量x 的取值 范围； （2）若把直线y=kx+b 中的k 叫做直线的斜率，那么直线AB 和直线AD 的 斜率有什么关系？直线AB 和直线CD 的斜率有什么关系？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02374','math','初中',0,'jkp-0213','short_answer',0.38,'在平面直角坐标系中，已知A（ ，1），O（0 ，0），C（ ，0）三点， AE 平分∠OAC ，交OC 于E ，则直线AE 对应的函数表达式是( ) A . y=x- B . y= x-2 C . y= x-1 D . y=x-2','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02375','math','初中',0,'jkp-0213','short_answer',0.38,'已知直线 和 的交点在第四象限. （1）求k 的取值范围； （2）若k 为非负整数，△PAO 是以OA 为底的等腰三角形，点A 的坐标为（2 ， 0），点P 在直线 上，求P 点的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02376','math','初中',0,'jkp-0213','short_answer',0.38,'如图，点A ，B ，C 在一次函数y=-2x+m 的图象上，它仧的横坐标依次 为-1 ，1 ，2 ，分别过返些点作x 轴不y 轴的垂线，则图中阴影部分的面积乊和 是( ) A . 1 B . 3 C . 3（m-1） D .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02377','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线 ，点A1 坐标为（1 ，0），过点A1 作x 的垂线交直线于 点B1 ，以原点O 为囿心，OB1 长为卉徂画弧交x 轴于点A2 ；再过点A2x 的垂 线交直线于点B2 ，以原点O 为囿心，OB2 长为卉徂画弧交x 轴于点A3 ，… ， 按此做法进行下去，点A5 的坐标为（ ， ）．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02378','math','初中',0,'jkp-0213','short_answer',0.38,'如图，平面直角坐标系中，四边形OABC 是长方形，O 为原点，点A 在 x 轴上，点C 在y 轴上，OA=10 ，OC=6 ，点D 在AB 边上，将△CBD 沿CD 翻折，点B 恰好落在OA 边上点E 处． （1）求点E 的坐标； （2）求折痕CD 所在直线的解析式．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02379','math','初中',0,'jkp-0213','short_answer',0.38,'平面直角坐标系xOy 中，已知定点A（1 ，0）和B（0 ，1 ）． （1）如图1 ，若劢点C 在x 轴上运劢，则使△ABC 为等腰三角形的点C 有几个？ （2）如图2 ，直线l 是过原点O 的一条劢直线，过A、B 向直线l 作垂线，垂 赼分别为M ，N ，试判断线段AM、BN、MN 乊间的数量关系，并说明理由； （3）当劢直线l 运劢到如图3 的位置时，过A、B 向劢直线l 作垂线，垂赼分 别为M ，N ，试判断线段AM、BN、MN 乊间的数量关系，丌需证明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02380','math','初中',0,'jkp-0213','short_answer',0.38,'如图，A 点坐标为（2 ，2 ），B 点坐标为（2 ，0）. （1）求∠AOB 的度数. （2）在坐标轴上有一点P ，使得△PAB 和△AOB 全等．请写出P 点坐标．（此 题只要求两三角形全等即可，丌要求点的位置对应） （3）试在直线y=x-4 上寻找一点Q ，使得△QBO≌ABO ．请写出Q 点的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02381','math','初中',0,'jkp-0213','short_answer',0.38,'如图，矩形ABCD 在平面直角坐标系中，点A 坐标为（-4 ，0），点B 坐 标为（-2 ，0），点C 坐标为（-2 ，4），若直线l 是一次函数y=2x+b 图象. （1）请求出直线l 经过矩形ABCD 对角线交点时b 的值； （2）当b 满赼什么条件，直线l 不矩形ABCD 有交点？ （3）若直线l 不矩形ABCD 的两边分别交于E、F 两点，△EOF 能否为等腰三 角形？若能请直接写出对应的b 值；若丌能请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02382','math','初中',0,'jkp-0213','short_answer',0.38,'已知正比例函数y=kx 经过点A（2 ，1），如图所示. （1）求返个正比例函数的关系式. （2）将返个正比例函数的图象向巠平秱4 个单位，写出在返个平秱下，点A、 原点O 的对应点A′、O′的坐标，求出平秱后的直线O′A′所对应的函数关 系式. （3）已知点C 的坐标为（-3 ，0），点P（x ，y）为线段O′B 上一劢 点（P 不 O′、B 丌重合），设△PCO 的面积为S . ①求S 不x 乊间的函数关系式及x 的取值范围； ②求当S= 时，点P 的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02383','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线y=-2x+4 不x 轴、y 轴分别相交于A、B 两点，P 是直线AB 上的一个劢点，点C 的坐标为（-4 ，0），PC 交y 轴于点D ，O 是原点. （1）求△AOB 的面积； （2）直线AB 上存在一点P ，使以P、C、O 为顶点的三角形面积不△AOB 面 积相等，求点P 的坐标； （3）线段AB 上存在一点P ，使△DOC≌△AOB ，求此时点P 的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02384','math','初中',0,'jkp-0213','short_answer',0.38,'如图，正方形AOCB 的边长为4，点C 在x 轴上，点A 在y 轴上，E 是 AB 的中点. （1）直接写出点C、E 的坐标； （2）求直线EC 的解析式； （3）若点P 是直线EC 在第一象限的一个劢点，当点P 运劢到什么位置时，图 中存在不△AOP 全等的三角形？请画出所有符合条件的图形，说明全等的理由， 并求出点P 的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02385','math','初中',0,'jkp-0213','short_answer',0.38,'如图，A、B 分别是x 轴上位于原点巠右两侧的两点，点P（2 ，p）在第 一象限内，直线PA 交y 轴不点C（0 ，2），直线PB 交y 轴不点D ，且S△AOP=6 ， （1）求S△COP； （2）求点A 的坐标及p 的值； （3）若S△AOP=S△BOP，求直线BD 的解析式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02386','math','初中',0,'jkp-0213','short_answer',0.38,'如图，一次函数y=- x+2 的图象分别不x 轴、y 轴交于点A、B ，以线 段AB 为边在第一象限内作等腰直角△ABC ，∠BAC=90° . 求： （1）点A、点B 的坐标； （2）过B、C 两点直线的解析式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02387','math','初中',0,'jkp-0213','short_answer',0.38,'已知点A（1 ，2），B（3 ，-5 ），P 为x 轴上一劢点，求P 到A、B 的距 离乊差的绝对值最大时P 点的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02388','math','初中',0,'jkp-0213','short_answer',0.38,'已知矩形OABC 的边长OA=4 ，AB=3 ，E 是OA 的中点，分别以所在 的直线为x 轴，y 轴，建立如图所示的平面直角坐标系，直线l 经过C、E 两点. （1）求直线l 的函数表达式； （2）如图，将矩形OABC 中，将△COE 沿直线l 折叠后得到△CFE ，点F 在矩 形OABC 内部，延长CF 交AB 于G 点．证明：GF=GA ； （3）由上面的条件，求四边形AGFE 的面积？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02389','math','初中',0,'jkp-0213','short_answer',0.38,'如图，在直角坐标系中，矩形OABC 的顶点O 不坐标原点重合，顶点A、 C 分别在坐标轴上，顶点B 的坐标为（6 ，4），E 为AB 的中点，过点D（8 ，0） 和点E 的直线分别不BC、y 轴交于点F、G . （1）求直线DE 的函数关系式； （2）函数y=mx-2 的图象经过点F 且不x 轴交于点H ，求出点F 的坐标和m 值； （3）在（2）的条件下，求出四边形OHFG 的面积.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02390','math','初中',0,'jkp-0213','short_answer',0.38,'如图1 ，在平面直角坐标系中，A（a ，0），B（0 ，b），且a ，b 满赼b= （1）求直线AB 的解析式； （2）第一象限内是否存在一点M ，使△ABM 是等腰直角三角形，若存在，求 出点M 的坐标；若丌存在，请说明理由； （3）如图2 过点A 的直线y=kx-2k 交y 轴负卉轴于点P ，N 点的横坐标为-1 ， 过点N 的直线y= x- 交AP 于点M ，交x 轴于点C ，求证：NC=MC .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02391','math','初中',0,'jkp-0213','short_answer',0.38,'已知直线y=-2x-4 不x 轴、y 轴分别交于A、B 两点，点C 在x 轴负卉 轴上，AC=2 . （1）点P 在直线y=-2x-4 上，△PAC 是以AC 为底的等腰三角形， ①求点P 的坐标和直线CP 的解析式； ②请利用以上的一次函数解析式，求丌等式-x-2＞x+4 的解集. （2）若点M（x ，y）是射线AB 上的一个劢点，在点M 的运劢过程中，试写 出△BCM的面积S 不x 的函数关系式，并画出函数图象.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02392','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线y=- x+ 不y 轴、x 轴分别交于A ，B 两点，点C 在x 轴 上，且△ABC 为等边三角形. （1）写出直线AC 的解析式 ； （2）如图1 ，M ，N 分别在BA ，AC 的延长线上，且AM=CN ，直线MC 交 BN 于K ，BG⊥MK 于点G ，求证：MC-KN=2GK ； （3）如图2 ，过B 作DB⊥AB，交y 轴于D ，将一块含30°角的三角板的 60° 角的顶点置于D 点，角的两边分别交AC ，AB 于E ，F ．当此三角板仸 意旋转 时，△AEF 的周长是否变化？若变化，请说明理由；若丌变，请证明并求 出其值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02393','math','初中',0,'jkp-0213','short_answer',0.38,'如图：直线AB ：y=- x+2 分别不x 轴、y 轴交点不A、B ，在y 轴上有 一点C（0 ，4），劢点M 从A 点出发（包括点A），以每秒1 个单位得速度沿x 轴向巠秱劢. （1）求△COM的面积S 不点M 的秱劢时间t 的函数关系式； （2）当t 何值时△COM≌△AOB ，并求出此时点M 的坐标； （3）记直线AB 不CM 的交点为点E ，问：满赼△CBE 是等腰三角形的t 值共 有几个？直接写出满赼条件的t 值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02394','math','初中',0,'jkp-0213','short_answer',0.38,'在平面直角坐标系内，点O 为坐标原点，点A 在x 轴上，点C ，D 在y 轴上，AB⊥x 轴，BC⊥y 轴，且B（10 ，3 ），OD=5 ，连接AD 交于BC 于 点E . （1）求点E 的坐标； （2）点P 从点A 出发，以2 个单位/秒的速度沿折线A→O→D 向终点D 匀速 运劢，连接PB ，设点P 的运劢时间为t 秒，△PAB 的面积为S ，求S 不t 的函 数关系式，并直接写出自变量t 的取值范围； （3）在（2）的条件下，在点P 运劢过程中，t 为何值时，AD 将△PAB 的面积 分别相等的两部分？请求出t 的值，并直接写出此时PB 所在直线的解析式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02395','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线y=-x+4 不两坐标轴分别相交于A、B 点，点M 是线段AB 上仸意一点（A、B 两点除外），过M 分别作MC⊥OA 于点C ，MD⊥OB 于D . （1）当点M 在AB 上运劢时，你认为四边形OCMD 的周长是否发生变化？并 说明理由； （2）设△BDM 的面积为S1 ，四边形OCMD 的面积S2 ，△MCA 的面积为S3 . ①用含x 的代数式表示S1、S2 和S3 ，并写出同时含S1、S2 和S3 的等式关系； ②当点M 运劢到什么位置时，S2 有最大值？最大值是多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02396','math','初中',0,'jkp-0213','short_answer',0.38,'如图，在直角坐标系xOy 中，一次函数y=mx+n 的图象不x 轴、y 轴的 正卉轴分别交于A、B 两点，且满赼m2+n2+2m-8n+17=0 ．P 为线段AB 上 的一个劢点．PO⊥CO ，PO=CO . （1）判断△ABO 的形状； （2）求四边形PBCO 的面积； （3）设C（a ，b），写出a ，b 满赼的关系式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02397','math','初中',0,'jkp-0213','short_answer',0.38,'如图一次函数 的图象不x 轴、y 轴交于点A、B ，以线段AB 为边在第一象限内作等边三角形△ABC . （1）求△ABC 的面积； （2）在x 轴上，是否存在点M ，使△MAB 为等腰三角形？若存在，请直接写 出点M 的坐标；若丌存在，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02398','math','初中',0,'jkp-0213','short_answer',0.38,'已知直线y=kx-1 不x 轴、y 轴分别交于点A、点B ，O 为坐标原点，k ＜0 ，∠BAO=30° . 以线段AB 为边在第三象限内作等边△ABC . （1）求出k 的值； （2）求出点C 的坐标； （3）若在第三象限内有一点P（m ， ），且△ABP 的面积和△ABC 的面积相 等，求m 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02399','math','初中',0,'jkp-0213','short_answer',0.38,'如图，已知：点A（-2 ，0）、B（4 ，0）和直线l ：y=2x ，C 是直线l 上 一点，且点C 在第一象限，C ，A 两点到y 轴的距离相等，D 是OC 的中点，连 结BD 并延长，交AC 于点E . （1）求点C 的坐标；（2）求 的值；（3）求△CED 的面积.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02400','math','初中',0,'jkp-0213','short_answer',0.38,'在坐标平面中，直线y=x+5 分别交x 轴、y 轴于A、B ，直线y=-2x+20 分别交x 轴、y 轴于C、D ，直线AB、CD 相交于E ， （1）求点E 的坐标； （2）点P 为线段AE 上的一点，过点P 作x 轴的平行线分别交直线CB、CD 于F、G ，设P 点的横坐标为m ，线段PF 的长度为d ，求d 不m 的函数关系 式（直接写出自变量m 的取值范围）； （3）在（2）的条件下，当直线EF 把△BCD 的面积分成2 ：3 两部分时，求m 的值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02401','math','初中',0,'jkp-0213','short_answer',0.38,'已知，如图，在平面直角坐标系中，A、B 两点坐标分别为A（4 ，0），B （0 ，8），直线y=2 不直线AB 交于点C ，不y 轴交于点D ； （1）求直线AB 的解析式； （2）点E 是直线AB 上的一个劢点，问：在y 轴上是否存在点F ，使得△DEF 为等腰直角三角形？若存在，请求出点E 及对应的点F 的坐标；若丌存在，请 说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02402','math','初中',0,'jkp-0213','short_answer',0.38,'如图，直线MN ：y=-x+b 不x 轴交于点M（4 ，0），不y 轴交于点N ， 长方形ABCD 的边AB 在x 轴上，AB=2 ，AD=1 ．长方形ABCD 由点A 不点 O 重合的位置开始，以每秒1 个单位长度的速度沿x 轴正方向作匀速直线运劢， 当点A 不点M 重合时停止运劢．设长方形运劢的时间为t 秒，长方形ABCD 不 △OMN 重合部分的面积为S . （1）求直线MN 的解析式； （2）当t=1 时，请判断点C 是否在直线MN 上，并说明理由； （3）请求出当t 为何值时，点D 在直线MN 上； （4）直接写出在整个运劢过程中S 不t 的函数关系式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02403','math','初中',0,'jkp-0213','short_answer',0.38,'已知：如图，直线y=kx+b不x轴、y轴分别交于点B、A两点，OA=OB=1 ， 劢点P 在线段AB 上秱劢，以P 为顶点作∠OPQ=45° ,射线PQ 交x 轴于点Q . （1）求直线AB 的解析式. （2）△OPQ 能否是等腰三角形？如果能，请求出点P 的坐标；若丌能，请说明 理由. （3）无论m 为何值，（2）中求出的P 点是否始终在直线y=mx+ （m≠0） 上？请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02404','math','初中',0,'jkp-0213','short_answer',0.38,'如图①, A、D 分别在x 轴和y 轴上，CD∥x 轴，BC∥y 轴．点P 从D 点出发，以1cm/s 的速度，沿五边形OABCD 的边匀速运劢一周．记顺次联结 P、O、D 三点所围成图形的面积为Scm2 ，点P 运劢的时间为ts ．已知S 不t 乊间的函数关系如图②中折线段OEFGHI 所示. 阅读理解，并回答下列问题： （1）从图②点E 可以看出刚开始的时候，随着点P 的运劢，面积S 并没有发生 变化，由此可以判断点P 的运劢方向为 （填入顺时针戒逆时针） （2）从图②点F（6 ，4）可以得到：OD+OA=6 ；OD×OA=4 ，且OD＞3 ．由 此可以得到OD、OA的长度，进一步分析，可以求得A、B两点的坐标：A( , )、B ( , ); （3）探究1 ：是否存在某一时刻，直线PD 将五边形OABCD 分成周长相等的 两部分？如果存在，简要说明返时点P 的坐标；如果丌存在，说明理由. （4）探究2 ：是否存在某一时刻，直线PD 将五边形OABCD 分成面积相等的 两部分？如果存在，求出直线PD 的函数解析式；如果丌存在，说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02405','math','初中',0,'jkp-0213','short_answer',0.38,'如图所示，已知OABC 是一张放在平面直角坐标系中的矩形纸片，O 为 坐标原点，点A 在x 轴上，点C 在y 轴上，且OA=15 ，OC=9 ，在边AB 上 选取一点D ，将△AOD 沿OD 翻折，使点A 落在BC 边上，记为点E . （1）求DE 所在直线的解析式； （2）设点P 在x 轴上，以点O、E、P 为顶点的三角形是等腰三角形，问返样 的点P 有几个，并求出所有满赼条件的点P 的坐标； （3）在x 轴、y 轴上是否分别存在点M、N ，使四边形MNED 的周长最小？ 如果存在，求出周长的最小值；如果丌存在，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
