INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02431','math','初中',0,'jkp-0265','short_answer',0.38,'如图，正比例函数y=mx 与反比例函数y= （m、n 是非零常数）的图象 交于A、B 两点．若点A 的坐标为（1 ，2 ），则点B 的坐标是( ) A . ( ﹣2 ，﹣4 ） B . ( ﹣2 ，﹣1 ） C . ( ﹣1 ，﹣2 ） D . ( ﹣4 ，﹣2 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02432','math','初中',0,'jkp-0265','short_answer',0.38,'已知正比例函数y=2x 与反比例函数y= 的图象相交于A ，B 两点，若A 点的坐标为（1 ，2 ），则B 点的坐标为( ) A ．（1 ，﹣2 ）B . ( ﹣1 ，2 ）C . ( ﹣1 ，﹣2 ） D ．（2 ，1 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02433','math','初中',0,'jkp-0265','short_answer',0.38,'如图，直线y=kx（k＞0 ）与双曲线y= 交于A ，B 两点，若A ，B 两点的 坐标分别为A（x1 ，y1 ），B（x2 ，y2 ），则x1y2+x2y1 的值为( ) A . ﹣8B ．4 C . ﹣4 D ．0','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02434','math','初中',0,'jkp-0265','short_answer',0.38,'已知正比例函数y=k1x（k1≠0 ）与反比例函数y= （k2≠0 ）的图象有一 个交点的坐标为( ﹣2 ，﹣1 ），则它的另一个交点的坐标是( ) A ．（2 ，1 ） B . ( ﹣2 ，﹣1 ） C . ( ﹣2 ，1 ）D ．（2 ，﹣1 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02435','math','初中',0,'jkp-0265','short_answer',0.38,'关于函数 的图象，下列说法错误的是( ) A ．经过点（1 ，﹣1 ） B ．在第二象限内，y 随x 的增大而增大 C ．是轴对称图形，且对称轴是y 轴 D ．是中心对称图形，且对称中心是坐标原点','','','','imported-junior-pdf','approved','通用','基础');
