INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02460','math','初中',0,'jkp-0265','short_answer',0.38,'如图，反比例函数 的图象经过矩形OABC 对角线的交点M ， 分别与AB、BC 相交于点D、E ．若四边形ODBE 的面积为6 ，则k 的值为( ) A．1 B．2 C ．3 D ．4','','','','imported-junior-pdf','approved','通用','基础');
