INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02594','math','初中',0,'jkp-0265','short_answer',0.38,'已知，A、B、C、D、E 是反比例函数y= （x＞0 ）图象上五个整数点（横， 纵坐标均为整数），分别以这些点向横轴或纵轴作垂线段，由垂线段所在的正方 形边长为半径作四分之一圆周的两条弧，组成如图所示的五个橄榄形（阴影部分）， 则这五个橄榄形的面积总和是 （用含π的代数式表示）. 解答：','','','','imported-junior-pdf','approved','通用','基础');
