INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02597','math','初中',0,'jkp-0265','short_answer',0.38,'给出下列命题： 命题1 ：点（1 ，1 ）是直线y=x 与双曲线y= 的一个交点； 命题2 ：点（2 ，4 ）是直线y=2x 与双曲线y= 的一个交点； 命题3 ：点（3 ，9 ）是直线y=3x 与双曲线y= 的一个交点； （1 ）请观察上面命题，猜想出命题n（n 是正整数）； （2 ）证明你猜想的命题n 是正确.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02598','math','初中',0,'jkp-0265','short_answer',0.38,'如图，一次函数y=kx﹣1 的图象与反比例函数 的图象交于A、B 两点， 其中A 点坐标为（2 ，1 ）. （1 ）试确定k、m 的值； （2 ）求B 点的坐标. , 求一次函数','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02599','math','初中',0,'jkp-0265','short_answer',0.38,'如图，已知反比例函数 与一次函数y=x+b 的图象在第一象限相交于点A （1 ，﹣k+4 ）. （1 ）试确定这两个函数的表达式； （2 ）求出这两个函数图象的另一个交点B 的坐标，并根据图象写出使反比例函 数的值大于一次函数的值的x 的取值范围.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02600','math','初中',0,'jkp-0265','short_answer',0.38,'已知图中的曲线函数 （m 为常数）图象的一支. （1 ）求常数m 的取值范围； （2 ）若该函数的图象与正比例函数y=2x 图象在第一象限的交点为A（2 ，n ）， 求点A 的坐标及反比例函数的解析式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02601','math','初中',0,'jkp-0265','short_answer',0.38,'如图，反比例函数y= （x＞0 ）与正比例函数y=k2x 的图象分别交矩形 OABC 的BC 边于M（4 ，1 ），B（4 ，5 ）两点. （1 ）求反比例函数和正比例函数的解析式； （2 ）若一个点的横坐标、纵坐标都是整数，则称这个点为格点．请你写出图中 阴影区域BMN（不含边界）内的所有格点关于y 轴对称的点的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02602','math','初中',0,'jkp-0265','short_answer',0.38,'如图，已知一次函数y1=x+m（m 为常数）的图象与反比例函数 （k 为常数，k≠0 ）的图象相交点A（1 ，3 ）. （1 ）求这两个函数的解析式及其图象的另一交点B 的坐标； （2 ）观察图象，写出使函数值y1≥y2的自变量x 的取值范围.','','','','imported-junior-pdf','approved','通用','基础');
