INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02616','math','初中',0,'jkp-0265','short_answer',0.38,'如图，一次函数y=kx+b 的图象经过第一、二、三象限，且与反比例函数 图象相交于A ，B 两点，与y 轴交于点C ，与x 轴交于点D ，OB= ．且点B 横坐标是点B 纵坐标的2 倍. （1 ）求反比例函数的解析式； （2 ）设点A 横坐标为m ，△ABO 面积为S ，求S 与m 的函数关系式，并求出 自变量的取值范围.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02617','math','初中',0,'jkp-0265','short_answer',0.38,'已知一次函数与反比例函数的图象交于点P ( ﹣3 ，m ），Q（2 ，﹣3 ）. （1 ）求这两个函数的函数关系式； （2 ）在给定的直角坐标系（如图）中，画出这两个函数的大致图象； （3 ）当x 为何值时，一次函数的值大于反比例函数的值？当x 为何值时，一次 函数的值小于反比例函数的值？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02618','math','初中',0,'jkp-0265','short_answer',0.38,'我们学习了利用函数图象求方程的近似解，例如：把方程2x﹣1=3﹣x 的 解看成函数y=2x﹣1 的图象与函数y=3﹣x 的图象交点的横坐标．如图，已画 出反比例函数y= 在第一象限内的图象，请你按照上述方法，利用此图象求方 程x2﹣x﹣1=0 的正数解．（要求画出相应函数的图象；求出的解精确到0.1 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02619','math','初中',0,'jkp-0265','short_answer',0.38,'如图所示，一次函数y=x+m 和反比例函数y= 一象限内的交点为P（a ，3 ）. （1 ）求a 的值及这两个函数的解析式； （2 ）根据图象，直接写出在第一象限内，使反比例函数的值大于一次函数的值 的x 的取值范围.','','','','imported-junior-pdf','approved','通用','基础');
