INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02621','math','初中',0,'jkp-0265','short_answer',0.38,'已知：如图，反比例函数y= 的图象与一次函数y=mx+b 的图象交于A（1 ， 3 ），B（n ，﹣1 ）两点. （1 ）求反比例函数与一次函数的解析式； （2 ）根据图象回答：当x 取何值时，反比例函数的值大于一次函数的值.','','','','imported-junior-pdf','approved','通用','基础');
