INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02623','math','初中',0,'jkp-0265','short_answer',0.38,'一次函数y=ax+b 的图象分别与x 轴、y 轴交于点M ，N ，与反比例函数 y=专的图象相交于点A ，B ．过点A 分别作AC⊥x轴，AE⊥y 轴，垂足分别为C ， E ；过点B 分别作BF⊥x轴，BD⊥y 轴，垂足分别为F ，D ，AC 与BD 交于点K ， 连接CD . （1 ）若点A ，B 在反比例函数y= 的图象的同一分支上，如图1 ，试证明： ①S 四边形AEDK=S 四边形CFBK ；②AN=BM . （2 ）若点A ，B 分别在反比例函数y= 的图象的不同分支上，如图2 ，则AN 与BM 还相等吗？试证明你的结论.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02624','math','初中',0,'jkp-0265','short_answer',0.38,'如图，在平面直角坐标系xOy 中，矩形OEFG 的顶点E 的坐标为（4 ，0 ）， 顶点G 的坐标为（0 ，2 ），将矩形OEFG 绕点O 逆时针旋转，使点F 落在y 轴 的点N 处，得到矩形OMNP ，OM 与GF 交于点A . （1 ）判断△OGA 和△OMN 是否相似，并说明理由； （2 ）求图象经过点A 的反比例函数的解析式； （3 ）设（2 ）中的反比例函数图象交EF 于点B ，求直线AB 的解析式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02625','math','初中',0,'jkp-0265','short_answer',0.38,'如图所示，在平面直角坐标系中，一次函数y=kx+1 的图象与反比例函数 y= 的图象在第一象限相交于点A ，过点A 分别作x 轴、y 轴的垂线，垂足为点 B、C ．如果四边形OBAC 是正方形，求一次函数的关系式.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02626','math','初中',0,'jkp-0265','short_answer',0.38,'如图1 ，已知正比例函数和反比例函数的图象都经过点M ( ﹣2 ，﹣1 ），且 P ( ﹣1 ，﹣2 ）为双曲线上的一点，Q 为坐标平面上一动点，PA 垂直于x 轴， QB 垂直于y 轴，垂足分别是A、B . （1 ）写出正比例函数和反比例函数的关系式； （2 ）当点Q 在直线MO 上运动时，直线MO上是否存在这样的点Q ，使得△OBQ 与△OAP 面积相等？如果存在，请求出点的坐标，如果不存在，请说明理由； （3 ）如图2 ，当点Q 在第一象限中的双曲线上运动时，作以OP、OQ 为邻边 的平行四边形OPCQ ，求平行四边形OPCQ 周长的最小值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02627','math','初中',0,'jkp-0265','short_answer',0.38,'如图，点A（m ，m+1 ），B（m+3 ，m﹣1 ）都在反比例函数y= 的图象 上. （1 ）求m ，k 的值； （2 ）如果M 为x 轴上一点，N 为y 轴上一点，以点A ，B ，M ，N 为顶点的四 边形是平行四边形，试求直线MN 的函数表达式； （3 ）在平面直角坐标系中，点P 的坐标为（5 ，0 ），点Q 的坐标为（0 ，3 ）， 把线段PQ 向右平移4 个单位，然后再向上平移2 个单位，得到线段P1Q1 ，则 点P1 的坐标为 ，点Q1 的坐标为 .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02628','math','初中',0,'jkp-0265','short_answer',0.38,'已知双曲线y= 与直线y= 相交于A、B 两点．第一象限上的点M（m ， n ）（在A 点左侧）是双曲线y= 上的动点．过点B 作BD∥y 轴交x 轴于点D ．过 N（0 ，﹣n ）作NC∥x 轴交双曲线y= 于点E ，交BD 于点C ． （1 ）若点D 坐标是（﹣8 ，0 ），求A、B 两点坐标及k 的值； （2 ）若B 是CD 的中点，四边形OBCE 的面积为4 ，求直线CM 的解析式； （3 ）设直线AM、BM 分别与y 轴相交于P、Q 两点，且MA=pMP ，MB=qMQ ， 求p﹣q 的值．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02629','math','初中',0,'jkp-0265','short_answer',0.38,'如图，P1（x1 ，y1 ），P2（x2 ，y2 ），…Pn（xn ，yn ）在函数y= 图象上，△P1OA1 ，△P2A1A2 ，△P3A2A3 ，…△PnAn﹣1An 都是等腰直角三角形，斜 边OA1、A1A2、A2A3 ，…An﹣1An 都在x 轴上 （1 ）求P1 的坐标； （2 ）求y1+y2+y3+…y10 的值．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02630','math','初中',0,'jkp-0265','short_answer',0.38,'如图，正方形OABC 的面积为4 ，点O 为坐标原点，点B 在函数y= （k ＜0 ，x＜0 ）的图象上，点P（m ，n ）是函数y= （k＜0 ，x＜0 ）的图象上异 于B 的任意一点，过点P 分别作x 轴、y 轴的垂线，垂足分别为E ，F ． （1 ）设矩形OEPF 的面积为S1 ，试判断S1 是否与点P 的位置有关；（不必说明 理由） （2 ）从矩形OEPF 的面积中减去其与正方形OABC 重合的面积，剩余面积记为 S2 ，写出S2 与m 的函数关系，并标明m 的取值范围． （x＞0 ）的','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02631','math','初中',0,'jkp-0265','short_answer',0.38,'（1 ）探究新知：如图1 ，已知△ABC 与△ABD 的面积相等，试判断AB 与 CD 的位置关系，并说明理由. （2 ）结论应用： ①如图2 ，点M ，N 在反比例函数y= （k＞0 ）的图象上，过点M 作ME⊥y 轴，过点N 作NF⊥x轴，垂足分别为E ，F ，试证明：MN ∥EF ； ②若①中的其他条件不变，只改变点M ，N 的位置如图3 所示，请判断MN 与 EF 是否平行.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02632','math','初中',0,'jkp-0265','short_answer',0.38,'病人按规定的剂量服用某种药物，测得服药后2 小时，每毫升血液中的含 药量达到最大值为4 毫克，已知服药后，2 小时前每毫升血液中的含药量y（毫 克）与时间x（小时）成正比例，2 小时后y 与x 成反比例（如图所示）．根据 以上信息解答下列问题. （1 ）求当0≤x≤2 时，y 与x 的函数关系式； （2 ）求当x＞2 时，y 与x 的函数关系式； （3 ）若每毫升血液中的含药量不低于2 毫克时治疗有效，则服药一次，治疗疾 病的有效时间是多长？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02633','math','初中',0,'jkp-0265','short_answer',0.38,'保护生态环境，建设绿色社会已经从理念变为人们的行动．某化工厂2009 年1 月的利润为200 万元．设2009 年1 月为第1 个月，第x 个月的利润为y 万元．由于排污超标，该从2009 年1 月底起适当限产，并投入资金进行治污改 造，导致月利润明显下降，从1 月到5 月，y 与x 成反比例．到5 月底，治污改 造工程顺利完工，从这时起，该厂每月的利润比前一个月增加20 万元（如图）. （1 ）分别求该化工厂治污期间及改造工程顺利完工后y 与x 之间对应的函数关 系式. （2 ）治污改造工程顺利完工后经过几个月，该厂利润才能达到200 万元？ （3 ）当月利润少于100 万元时为该厂资金紧张期，问该厂资金紧张期共有几个 月？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02634','math','初中',0,'jkp-0265','short_answer',0.38,'某服装厂承揽一项生产夏凉小衫1600 件的任务，计划用t 天完成. （1 ）写出每天生产夏凉小衫w（件）与生产时间t（天）（t＞4 ）之间的函数关 系式； （2 ）由于气温提前升高，商家与服装厂商议调整计划，决定提前4 天交货，那 么服装厂每天要多做多少件夏凉小衫才能完成任务？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02635','math','初中',0,'jkp-0265','short_answer',0.38,'近年来，我国煤矿安全事故频频发生，其中危害最大的是瓦斯，其主要成 分是CO ．在一次矿难事件的调查中发现：从零时起，井内空气中CO 的浓度达 到4mg/L ，此后浓度呈直线型增加，在第7 小时达到最高值46mg/L ，发生爆 炸；爆炸后，空气中的CO 浓度成反比例下降．如图所示，根据题中相关信息回 答下列问题： （1 ）求爆炸前后空气中CO 浓度y 与时间x 的函数关系式，并写出相应的自变 量取值范围； （2 ）当空气中的CO 浓度达到34mg/L 时，井下3km 的矿工接到自动报警信 号，这时他们至少要以多少km/h 的速度撤离才能在爆炸前逃生？ （3 ）矿工只有在空气中的CO 浓度降到4mg/L 及以下时，才能回到矿井开展 生产自救，求矿工至少在爆炸后多少小时才能下井？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02636','math','初中',0,'jkp-0265','short_answer',0.38,'为预防“手足口病” ，某校对教室进行“药熏消毒” ．已知药物燃烧阶段， 室内每立方米空气中的含药量y（mg ）与燃烧时间x（分钟）成正比例；燃烧 后，y 与x 成反比例（如图所示）．现测得药物10 分钟燃烧完，此时教室内每立 方米空气含药量为8 mg ．根据以上信息，解答下列问题： （1 ）求药物燃烧时y 与x 的函数关系式； （2 ）求药物燃烧后y 与x 的函数关系式； （3 ）当每立方米空气中含药量低于1.6 mg 时，对人体无毒害作用．那么从消 毒开始，经多长时间学生才可以返回教室？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02637','math','初中',0,'jkp-0265','short_answer',0.38,'水产公司有一种海产品共2 104 千克，为寻求合适的销售价格，进行了8 天试销，试销情况如下： 第1 天第2 天第3 天第4 天第5天第6 天第7 天第8 天 售价 x（元/千克） 400 250 240 200 150 125 120 销售量 y（千克） 30 40 48 60 80 96 100 观察表中数据，发现可以用反比例函数刻画这种海产品的每天销售量y（千克） 与销售价格x（元/千克）之间的关系．现假定在这批海产品的销售中，每天的 销售量y（千克）与销售价格x（元/千克）之间都满足这一关系. （1 ）写出这个反比例函数的解析式，并补全表格； （2 ）在试销8 天后，公司决定将这种海产品的销售价格定为150 元/千克，并 且每天都按这个价格销售，那么余下的这些海产品预计再用多少天可以全部售 出？ （3 ）在按（2 ）中定价继续销售15 天后，公司发现剩余的这些海产品必须在不 超过2 天内全部售出，此时需要重新确定一个销售价格，使后面两天都按新的价 格销售，那么新确定的价格最高不超过每千克多少元才能完成销售任务？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02638','math','初中',0,'jkp-0265','short_answer',0.38,'为了预防流感，某学校在休息天用药熏消毒法对教室进行消毒．已知药物 释放过程中，室内每立方米空气中的含药量y（毫克）与时间x（分钟）成正比 例；药物释放完毕后，y 与x 成反比例，如图所示．根据图中提供的信息，解答 下列问题： （1 ）写出从药物释放开始，y 与x 之间的两个函数关系式及相应的自变量取值 范围； （2 ）据测定，当空气中每立方米的含药量降低到0.45 毫克以下时，学生方可进 入教室，那么从药物释放开始，至少需要经过多少小时后，学生才能进入教室？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02639','math','初中',0,'jkp-0265','short_answer',0.38,'如图，奥运圣火抵达某市奥林匹克广场后，沿图中直角坐标系中的一段反 比例函数图象传递．动点T（m ，n ）表示火炬位置，火炬从离北京路10 米处的 M 点开始传递，到离北京路1000 米的N 点时传递活动结束．迎圣火临时指挥 部设在坐标原点O（北京路与奥运路的十字路口），OATB 为少先队员鲜花方阵， 方阵始终保持矩形形状且面积恒为10000 平方米（路线宽度均不计）. （1 ）求图中反比例函数的关系式（不需写出自变量的取值范围）； （2 ）当鲜花方阵的周长为500 米时，确定此时火炬的位置（用坐标表示）； （3 ）设t=m﹣n ，用含t 的代数式表示火炬到指挥部的距离；当火炬离指挥部 最近时，确定此时火炬的位置（用坐标表示）.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02640','math','初中',0,'jkp-0265','short_answer',0.38,'人的视觉机能受运动速度的影响很大，行驶中司机在驾驶室内观察前方物 体时是动态的，车速增加，视野变窄．当车速为50km/h 时，视野为80 度．如 果视野f（度）是车速v（km/h ）的反比例函数，求f ，v 之间的关系式，并计 算当车速为100km/h 时视野的度数．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02641','math','初中',0,'jkp-0265','short_answer',0.38,'小华家离学校500m ，小华步行上学需xmin ，那么小华步行速度y（m/min ） 可以表示为y= ；水平地面上重500N 的物体，与地面的接触面积为xm2 ， 那么该物体对地面压强y（N/m2 ）可以表示为y= ；… ，函数关系式y= 还 可以表示许多不同情境中变量之间的关系，请你再列举出一例．','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02642','math','初中',0,'jkp-0265','short_answer',0.38,'某项工程需要沙石料2×106 立方米，阳光公司承担了该工程运送沙石料的 任务． （1 ）在这项任务中平均每天的工作量v（立方米/天）与完成任务所需要的时间 t（天）之间具有怎样的函数关系写出这个函数关系式． （2 ）阳光公司计划投入A 型卡车200 辆，每天一共可以运送沙石料2×104 立 方米，则完成全部运送任务需要多少天？如果工作了25 天后，由于工程进度的 需要，公司准备再投入A 型卡车120 辆．在保持每辆车每天工作量不变的前提 下，问：是否能提前28 天完成任务？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02643','math','初中',0,'jkp-0265','short_answer',0.38,'如图，学校生物兴趣小组的同学们用围栏围了一个面积为24 平方米的矩形 饲养场地ABCD ．设BC 为x 米，AB 为y 米. （1 ）求y 与x 的函数关系式； （2 ）延长BC 至E ，使CE 比BC 少1 米，围成一个新的矩形ABEF ，结果场地 的面积增加了16 平方米，求BC 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02644','math','初中',0,'jkp-0265','short_answer',0.38,'某校科技小组进行野外考察，途中遇到一片十几米宽的烂泥湿地．为了安 全、迅速通过这片湿地，他们沿着前进路线铺了若干块木块，构筑成一条临时近 道．木板对地面的压强P（Pa ）是木板面积S（m2 ）的反比例函数，其图象如 下图所示. （1 ）请直接写出这一函数表达式和自变量取值范围； （2 ）当木板面积为0.2m2时，压强是多少？ （3 ）如果要求压强不超过6000Pa ，木板的面积至少要多大？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02645','math','初中',0,'jkp-0265','short_answer',0.38,'某人采用药熏法进行室内消毒，已知药物燃烧时室内每立方米空气中的含 药量y（毫克）与时间x（分钟）成正比例，药物燃烧后，y 与x 成反比例（如 图所示），现测得药物10 分钟燃完，此时室内空气中每立方米的含药量为8 毫 克，请根据题中所提供的信息，解答下列问题： （1 ）药物燃烧时，y 与x 的函数关系式为 ，自变量x 的取值范围 是 ；药物燃烧后，y 与x 的函数关系式为 . （2 ）研究表明，当空气中每立方米的含药量低于2 毫克时，人方可进入室内， 那么从消毒开始，至少需要经过 分钟后，人才可以回到室内. （3 ）当空气中每立方米的含药量不低于5 毫克且持续时间不低于10 分钟时， 才能有效杀灭空气中的病菌，那么此次消毒是否有效，为什么？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02646','math','初中',0,'jkp-0265','short_answer',0.38,'一定质量的气体，当温度不变时，气体的压强p（Pa ）是气体体积V（m3 ） 的反比例函数．已 知当气体体积为1 m3 时，气体的压强为9.6×104Pa . （1 ）求p 与V 之间的函数关系式； （2 ）要使气体的压强不大于1.4×105Pa ，气体的体积应不小于多少立方米？（精 确到0.1 m3 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02647','math','初中',0,'jkp-0265','short_answer',0.38,'某厂从2005 年起开始投入技术改进资金，经技术改进后，其产品的生产成 本不断降低，具体数据如下表： 年 度 2006 2007 2008 2009 投入技改资金x（万元）2.5 3 4 4.5 产品成本y（万元/件）7.2 6 4.5 4 （1 ）请你认真分析表中数据，从你所学习过的一次函数、二次函数和反比例函 数中确定哪种函数能表示其变化规律，说明确定是这种函数而不是其它函数的理 由，并求出它的解析式； （2 ）按照这种变化规律，若2010 年已投入技改资金5 万元. ①预计生产成本每件比2009 年降低多少万元？ ②如果打算在2009 年把每件产品成本降低到3.2 万元，则还需投入技改资金多 少万元？（结果精确到0.01 万元）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02648','math','初中',0,'jkp-0265','short_answer',0.38,'为预防“流感“ ，某单位对办公室进行“药熏消毒” ．已知药物燃烧时， 室内每立方米空气中的含药量y（毫克）与燃烧时间x（分钟）成正比例；燃烧 后，y 与x 成反比例（如图所示）．现测得药物8 分钟燃毕，此时办公室内每立 方米空气中含药量为6 毫克，据以上信息： （1 ）分别求药物燃烧时和燃烧后，y 与x 的函数关系式； （2 ）研究表明，当空气中含药量低于1.6 毫克/立方米时，工作人员才能回到办 公室，那么从消毒开始，经多长时间，工作人员才可以回到办公室？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02649','math','初中',0,'jkp-0265','short_answer',0.38,'某市城建部门经过长期市场调查发现，该市年新建商品房面积P（万平方米） 与市场新房均价x（千元/平方米）存在函数关系P=25x；年新房销售面积Q（万 平方米）与市场新房均价x（千元/平方米）的函数关系为 Q= ﹣10 ； （1 ）如果年新建商品房的面积与年新房销售面积相等，求市场新房均价和年新 房销售总额； （2 ）在（1 ）的基础上，如果市场新房均价上涨1 千元，那么该市年新房销售 总额是增加还是减少？变化了多少？结合年新房销售总额和积压面积的变化情 况，请你提出一条合理化的建议．（字数不超过50 ）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02650','math','初中',0,'jkp-0265','short_answer',0.38,'制作一种产品，需先将材料加热达到60℃后，再进行操作．设该材料温度 为y ( ℃) , 从加热开始计算的时间为x（分钟）．据了解，该材料加热时，温度 y 与时间x 成一次函数关系；停止加热进行操作时，温度y 与时间x 成反比例关 系（如图）．已知该材料在操作加工前的温度为15℃, 加热5 分钟后温度达到 60℃. （1 ）分别求出将材料加热和停止加热进行操作时，y 与x 的函数关系式； （2 ）根据工艺要求，当材料的温度低于15℃时，须停止操作，那么从开始加热 到停止操作，共经历了多少时间？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02651','math','初中',0,'jkp-0265','short_answer',0.38,'你吃过拉面吗？实际上在做拉面的过程中就渗透着数学知识：一定体积的 面团做成拉面，面条的总长度y（m ）是面条的粗细（横截面积）x（mm2）的 反比例函数，其图象如图所示. （1 ）写出y 与x 的函数关系式； （2 ）求当面条粗1.6mm2 时，面条的总长度是多少米？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02652','math','初中',0,'jkp-0265','short_answer',0.38,'某小型开关厂今年准备投入一定的经费用于现有生产设备的改造以提高经 济效益．通过测算：今年开关的年产量y（万只）与投入的改造经费x（万元） 之间满足3﹣y 与x+1 成反比例，且当改造经费投入1 万元时，今年的年产量是 2 万只. （1 ）求年产量y（万只）与改造经费x（万元）之间的函数解析式．（不要求写 出x 的取值范围） （2 ）已知每生产1 万只开关所需要的材料费是8 万元．除材料费外，今年在生 产中，全年还需支付出2 万元的固定费用. ①求平均每只开关所需的生产费用为多少元？（用含y 的代数式表示） （生产费用=固定费用+材料费） ②如果将每只开关的销售价定位“平均每只开关的生产费用的1.5 倍”与“平 均每只开关所占改造费用的一半”之和，那么今年生产的开关正好销完．问今年 需投入多少改造经费，才能使今年的销售利润为9.5 万元？ （销售利润=销售收入一生产费用﹣改造费用）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02653','math','初中',0,'jkp-0265','short_answer',0.38,'某气球内充满了一定质量的气球，当温度不变时，气球内气球的气压p（千 帕）是气球的体积V（米2 ）的反比例函数，其图象如图所示．（千帕是一种压强 单位） （1 ）写出这个函数的解析式； （2 ）当气球的体积为0.8 立方米时，气球内的气压是多少千帕？ （3 ）当气球内的气压大于144 千帕时，气球将爆炸，为了安全起见，气球的体 积应不小于多少立方米？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02654','math','初中',0,'jkp-0265','short_answer',0.38,'通过市场调查，一段时间内某地区特种农产品的需求量y（千克）与市场价 格x（元/千克）存在下列函数关系式：y= +6000（0＜x＜100 ）；又已知 该地区农民的这种农产品的生产数量z（千克）与市场价格x（元/千克）成正比 例关系：z=400x（0＜x＜100 ），现不计其它因素影响，如果需求数量y 等于生 产数量z 时，即供需平衡，此时市场处于平衡状态. （1 ）根据以上市场调查，请你分析当市场处于平衡状态时，该地区这种农产品 的市场价格与这段时间内农民的总销售收入各是多少？ （2 ）受国家“三农”政策支持，该地区农民运用高科技改造传统生产方式，减 少产量，以大力提高产品质量．此时生产数量z 与市场价格x 的函数关系发生改 变，而需求函数关系未发生变化，当市场再次处于平衡状态时，市场价格已上涨 了a（0＜a＜25 ）元，问在此后的相同时间段内该地区农民的总销售收入是增 加了还是减少了，变化多少？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02655','math','初中',0,'jkp-0265','short_answer',0.38,'如图所示，点P 经过点B（0 ，﹣2 ），C（4 ，0 ）所在的直线上，且纵坐标 为﹣1 ，点Q 在函数 图象上，若PQ 平行于y 轴，求出点Q 的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02656','math','初中',0,'jkp-0265','short_answer',0.38,'如图，已知直角坐标系内有一条直线和一条曲线，这条直线和x 轴、y 轴分 别交于点A 和点B ，且OA=OB=1 ，这条曲线是函数y= 的图象在第一限内的 一个分支，点P 是这条曲线的任意一点，它的坐标是（a ，b ），由点P 向x 轴、 y 轴所作的垂线PM、PN（点M、N 为垂足）分别与直线AB 相交于点E 和F . （1 ）求△OEF 的面积（a ，b 的代数式表示）； （2 ）△AOF 与△BOE 是否一定相似？如果一定相似，请证明；如果不一定相似， 请说明理由； （3 ）当点P 在曲线上移动时，△OEF 随之变动，指出在△OEF 的三个内角中， 是否有大小始终保持不变的角？若有，请求出其大小；若没有，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02657','math','初中',0,'jkp-0265','short_answer',0.38,'如图，直线y=kx+4 与函数y= （x＞0 ，m＞0 ）的图象交于A、B 两点， 且与x、y 轴分别交于C、D 两点. （1 ）若△COD 的面积是△AOB 的面积的√E倍，求k 与m 之间的函数关系式； （2 ）在（1 ）的条件下，是否存在k 和m ，使得以AB 为直径的圆经过点P（2 ， 0 ）？若存在，求出k 和m 的值；若不存在，请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02658','math','初中',0,'jkp-0265','short_answer',0.38,'如图，Rt△ABO 的顶点A 是双曲线y= 与直线y=﹣x﹣（k+1 ）在第二象 限的交点．AB⊥x 轴于B ，且S△ABO= . （1 ）求这两个函数的解析式； （2 ）求直线与双曲线的两个交点A、C 的坐标和△AOC 的面积.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02659','math','初中',0,'jkp-0265','short_answer',0.38,'已知反比例函数 （k≠0 ，k 为常数）和正比例函数y=ax（a≠0 ，a 为常 数）．求反比例函数的图象和正比例函数的图象的交点坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02660','math','初中',0,'jkp-0265','short_answer',0.38,'直线a 分别交x 轴、y 轴于A、C ，点P 是该直线与反比例函数在第一 象限内的一个交点，PB⊥x 轴于B ，且S△ABP=9 . （1 ）求点P 的坐标； （2 ）设点R 与点P 在同一个反比例函数的图象上，且点R 在直线PB 的右侧， 作RT⊥x轴于T ，当BR∥AP 时，求点R 的坐标.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02661','math','初中',0,'jkp-0265','short_answer',0.38,'已知一次函数 的图象分别交x 轴、y 轴于A、B 两点，且与反比例 函数 的图象在第一象限交于点C（4 ，n ），CD⊥x 轴于D . （1 ）求m、n 的值，并在给定的直角坐标系中作出一次函数的图象； （2 ）如果点P、Q 分别从A、C 两点同时出发，以相同的速度沿线段AD、CA 向D、A 运动，设AP=k . ①k 为何值时，以A、P、Q 为顶点的三角形与△AOB 相似？ ②k 为何值时，△APQ 的面积取得最大值并求出这个最大值.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02662','math','初中',0,'jkp-0265','short_answer',0.38,'已知反比例函数y= 的图象和一次函数y=kx﹣7 的图象都经过点P（m ， 2）. （1 ）求这个一次函数的解析式； （2 ）如果等腰梯形ABCD 的顶点A、B 在这个一次函数的图象上，顶点C、D 在这个反比例函数的图象上，两底AD、BC 与y 轴平行，且A 和B 的横坐标分 别为a 和a+2 ，求a 的值. 解析： 选择：','','','','imported-junior-pdf','approved','通用','基础');
