INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02665','math','初中',0,'jkp-0422','short_answer',0.38,'【易】（德州市初中学业考试数学试题）  2 cos30 的值是____________．','','','','imported-junior-pdf','approved','通用','基础');
