INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02749','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（2011-2012 学年朝阳区九年级第一学期期末统一考试）抛物线y = (x 一2)2 +1是 由抛物线y = x2 平移得到的，下列对于抛物线y = x2 的平移过程叙述正确的是( ) A ．先向右平移2 个单位，再向上平移1 个单位 B ．先向右平移2 个单位，再向下平移1 个单位 C．先向左平移2 个单位，再向上平移1 个单位 D．先向左平移2 个单位，再向下平移1 个单位 对称','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02750','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（北京市东城区初三年级综合练习）已知抛物线C1：y = x2 一2x 的图象如图所示 ，把C1 的图象沿y 轴翻折，得到抛物线C2 的图象，抛物线C1 与抛物线C2 的图象合 称图象C3 . y C1 O x A ⑴求抛物线C1 的顶点A 坐标，并画出抛物线C2 的图象； ⑵若直线y = kx + b 与抛物线y = ax2 + bx + c(a ≠0) 有且只有一个交点时，称直线与抛 物线相切．若直线y = x + b 与抛物线C1 相切，求b 的值； ⑶结合图象回答，当直线y = x + b 与图象C3 有两个交点时，b 的取值范围. 旋转','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02751','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（北京市第156 中学初三期中）已知：抛物线 C1 ∶y = ax2 + bx + c 经过点A(一1，0) 、B(3，0) 、C(0，一3) 。⑴求抛物线C1 的解析式； ⑵将抛物线C1 向左平移几个单位长度，可使所得的抛物线C2 经 过坐标原点，并写出C2 的解析式； ⑶把抛物线C1 绕点A(一1，0) 旋转180O ，写出所得抛物线C3 顶点D 的坐标。 -5 -4-3 -2 -1O 1 2 3 4 5 -1 -2 -3 -4 4 - 3 - 2 1 二次函数与方程不等式结合','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02752','math','初中',0,'jkp-0375','short_answer',0.38,'【难】（西城二模）阅读下列材料：若关于x 的一元二次方程ax2 + bx + c = 0 (a ≠0) 的 两个实数根分别为x1 ，x2 ，则x1 + x2 = 一 ，x1 . x2 = . 解决下列问题： 已知：a，b，c 均为非零实数，且a > b > c ，关于x 的一元二次方程ax 2 + bx + c = 0 有两个实数根，其中一根为2. ⑴填空：4a + 2b+ c 0，a 0，c 0；（填“ > ”，“ < ”或“ = ”） ⑵利用阅读材料中的结论直接写出方程ax2 + bx + c = 0 的另一个实数根（用含a，c 的代数式表示）； ⑶若实数m 使代数式am2 + bm+ c 的值小于0，问：当x = m + 5 时，代数式ax2 + bx+ c 的值是否为正数？写出你的结论并说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02753','math','初中',0,'jkp-0375','short_answer',0.38,'【难】已二次函数y1 = x2 一2x 一3 及一次函数y2 = x + m . ⑴求该二次函数图象的顶点坐标以及它与x 轴的交点坐标； ⑵将该二次函数图象在x 轴下方的部分沿x 轴翻折到x 轴上方，图象的其余部分不变 ，得到一个新图象，请你在图中画出这个新图象，并求出新图象与直线y2 = x + m 有 三个不同公共点时m 的值： ⑶当0 ≤x ≤2 时，函数y = y1 + y2 + (m 一2)x + 3 的图象与x 轴有两个不同公共点， 求m 的取值范围. \ y O x','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02754','math','初中',0,'jkp-0375','short_answer',0.38,'【易】张大爷要围成一个矩形花圃．花圃的一边利用足够长的墙另三边用总长为32 米 的篱笆恰好围成．围成的花圃是如图所示的矩形ABCD ．设AB 边的长为x 米．矩形 ABCD 的面积为S 平方米. ⑴求S 与x 之间的函数关系式（不要求写出自变量x 的取值范围）. ⑵当x 为何值时，S 有最大值？并求出最大值. （参考公式：二次函数y = ax2 + bx+ c（a ≠0 ），当 时，y最大 值= D 花圃 C A B','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02755','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（雅安市初中毕业暨高中阶段教育学校招生考试数学试卷）如图，已知抛物线 y = ax2 + bx+c 经过A（-3，0），B（1，0），C（0，3）三点，其顶点为D，对称轴是直线l ，l 与x 轴交于点H . （1）求该抛物线的解析式； （2）若点P 是该抛物线对称轴l 上的一个动点，求△PBC 周长的最小值； （3）如图（2），若E 是线段AD 上的一个动点（E 与A、D 不重合），过E 点作平行 于y 轴的直线交抛物线于点F ，交x 轴于点G ，设点E 的横坐标为m ，△ADF 的面 积为S . ①求S 与m 的函数关系式； ②S 是否存在最大值？若存在，求出最大值及此时点E 的坐标；若不存在，请说明理由. / D \ C A H l O B 图（1） D P ys\ C A H O B F E D \ C A G H O B 图（2） F E / D \ C A G H l O B y x x x x l y y 利用函数图象解方程和不等式','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02756','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（北京二中初三上质量检测）已知抛物线y = (k - 2)xk2 -4k+5 + 2x + 3 有最高点， 此抛物线与直线y2 = 3x + m 其中一个交点的横坐标是2. ⑴抛物线y1 和直线y2 的解析式. ⑵抛物线y1 最高点的坐标是________ . ⑶当x _________ 时，y1 随x 的增大而增大. ⑷当x _________ 时，y1 < 0 ⑸当x _________ 时，y1 < y2 ⑹当0 < x < 3 时，y1 的取值范围是___________ 最大利润问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02757','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（河南省实验中学内部中考数学第一轮复习资料）某商场购进一种单价为40 元的 篮球，如果以单价50 元售出，那么每月可售出500 个．根据销售经验，售价每提高1元， 销售量相应减少10 个. ⑴假设销售单价提高x 元，那么销售每个篮球所获得的利润是 元；这种篮 球每月的销售量是 个．（用含x 的代数式表示） ⑵当篮球的售价应定为 元时，每月销售这种篮球的最大利润，此时最大利润是 元. 实根分布问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02758','math','初中',0,'jkp-0375','short_answer',0.38,'【中】已知二次函数 ，且x1 、x2 是方程 的两个根，则实数a 、b 、x1 、x2 的大小关系为( ) A．a < x1 < b < x2 B．a < x1 < x2 < b C．x1 < a < x2 < b D．x1 < a < b < x2 二次函数与等腰三角形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02759','math','初中',0,'jkp-0375','short_answer',0.38,'（特殊条件下的等腰三角形）（2011年淮安）如图．已知二次函数y= 一x2 + bx + 3 的图 象与x 轴的一个交点为A(4，0)，与y 轴交于点B . ⑴求此二次函数关系式和点B 的坐标； ⑵在x 轴的正半轴上是否存在点P ．使得△PAB 是以AB 为底边的等腰三角形？若 存在，求出点P 的坐标；若不存在，请说明理由. B y','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02760','math','初中',0,'jkp-0375','short_answer',0.38,'（等腰三角形点的存在性问题）（临沂市中考题）如图，点A 在x 轴上，OA = 4 ，将 线段OA 绕点O 顺时针旋转120°至OB 的位置； （1）求点B 的坐标； （2）求经过点A、O、B 的抛物线的解析式； （3）在此抛物线的对称轴上，是否存在点P ，使得以点P、O、B 为顶点的三角形使 等腰三角形？若存在，求点P 的坐标；若不存在，请说明理由. y O M P N A （第3题） 二次函数与直角三角形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02761','math','初中',0,'jkp-0375','short_answer',0.38,'【难】（在特殊条件下存在点问题直角三角形）（九年级第一次质量预测）如图，经过x 轴上A(一1，0) 、B(3，0) 两点的抛物线y = ax2 +bx + c (a ≠0) 交y 轴的正半轴于点C ，设抛物线的顶点为D . (1)用含a 的代数式表示出点C 、D 的坐标 (2)若么BCD = 90o ，请确定抛物线的解析式； (3)在(2)的条件下，能否在抛物线上找到另外的点Q ，使△BDQ 为直角三角形?如 果能，请求出Q 点坐标；如果不能，请说明理由. y D C O x A l A O B x x 二次函数与等腰直角三角形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02762','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（二次函数与等腰直角三角形）（东城二模）在平面直角坐标系中，现将一块等腰 直角三角板ABC 放在第二象限，斜靠在两坐标轴上，且点A（0，2），点C（—1，0），如 图所示，抛物线y = ax2 + ax —2 经过点B . ⑴求点B 的坐标； ⑵求抛物线的解析式； ⑶在抛物线上是否还存在点P （点B 除外），使△ACP 仍然是以AC 为直角边的等 腰直角三角形？若存在，求所有点P 的坐标；若不存在，请说明理由. y x 二次函数与相似三角形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02763','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（相似）（上海市初中毕业生统一学业数学考试试卷）如图，在平面直角坐标系xoy 中，顶点为M 的抛物线y = ax2 + bx(a > 0) 经过点A 和x 轴正半轴上的点B ，AO = OB = 2 ，上AOB = 120。. （1）求这条抛物线的表达式； （2 ）联结OM ，求上AOM 的大小； （3）如果点C 在x 轴上，且△ABC 与△AOM 相似，求点C 的坐标. C(-1,0) O A(0,2) B','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02764','math','初中',0,'jkp-0375','short_answer',0.38,'【难】（相似+面积）（莱芜市中考题）如图，抛物线y = ax2 + bx + c 的顶点坐标为（2 ，-1），并且与y 轴交于点C (0，3)，与x 轴交于两点A 、B . （1）求抛物线的解析式； （2）设抛物线的对称轴与直线B 、C 交于点D ，连接AC 、AD，求ΔACD 的面积； （3）点E 是直线BC 上一动点，过点E 作y 轴的平行线EF ，与抛物线交于点F 。问是否存在点E ，使得以D 、E 、F 为顶点的三角形与ΔBCO 相似？若存在，求 出E 点的坐标；若不存在，请说明理由 y E D F A B 二次函数与平行四边形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02765','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（平行四边形）（南昌中考）如图所示，抛物线m ：y = ax2 + b（a < 0 ，b > 0 ）与x轴交于点A、B（点A在点B的左侧），与y轴交于点C．将抛物线m绕点B旋转180 。， 得到新的抛物线n，它的顶点为C1 ，与x轴的另一个交点为A1 . ⑴当a = —1 ，b = 1 时，求抛物线n的解析式； ⑵四边形AC1A1C 是什么特殊四边形，请写出结果并说明理由 ；⑶若四边形AC1A1C 为矩形，请求出a ，b 应满足的关系式. yl C A O B A1 C1 x x O C 二次函数与正方形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02766','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（平行四边形+正方形）（湖南衡阳）已知抛物线 x2 — mx + 2m — ⑴试说明：无论m为何实数，该抛物线与x轴总有两个不同的交点； ⑵如图，当该抛物线的对称轴为直线x = 3 时，抛物线的顶点为点C，直线y = x —1 与抛物线交于A、B两点，并与它的对称轴交于点D . ①抛物线上是否存在一点P 使得四边形ACPD 是正方形？若存在，求出点P 的坐标 ；若不存在，说明理由； ②平移直线CD，交直线AB 于点M，交抛物线于点N，通过怎样的平移能使得C、D、M 、N为顶点的四边形是平行四边形. x 二次函数与矩形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02767','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（矩形+平移）（江西）将抛物线沿C1 : — 3x2 + 3 沿x 轴翻折，得抛物线C2 ，如 图所示. ⑴请直接写出抛物线C2 的表达式； ⑵现将抛物线C1 向左平移m 个单位长度，平移后得到的新抛物线的顶点为M ，与 x 轴的交点从左到右依次为A ，B ；将抛物线C2 向右也平移m 个单位长度，平移后 得到的新抛物线的顶点为N ，与x 轴交点从左到右依次为D ，E . ①当B ，D 是线段AE 的三等分点时，求m 的值； ②在平移过程中，是否存在以点A ，N ，E ，M 为顶点的四边形是矩形的情形？ 若存在，请求出此时m 的值；若不存在，请说明理由 y C2 O C1 y O 备用图 D y O A C B x x 二次函数与菱形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02768','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（菱形+平移）（北京市宣武区第二学期第一次质量检测）已知：将函数y = 图象向上平移2 个单位，得到一个新的函数的图像. ⑴求这个新的函数的解析式； x 的 ⑵若平移前后的这两个函数图象分别与y 轴交于O 、A 两点，与直线x = — 交于C 、B 两点．试判断以A 、B 、C 、O 四点为顶点的四边形形状，并说明理由； ⑶若⑵中的四边形（不包括边界）始终覆盖着二次函数y = x2 — 2bx + b2 + 一部分，求满足条件的实数b 的取值范围. y O 二次函数与梯形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02769','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（梯形+轴对称）如图，在平面直角坐标系中，已知点A(—2，— 4) ，OB = 2 ，抛 物线y = ax2 + bx + c 经过点A，O，B 三点. ⑴求抛物线的函数表达式； ⑵若点M 是抛物线线对称轴上一点，试求AM + OM 的最小值； ⑶在此抛物线上，是否存在点P ，使得点P 与点O，A，B 为顶点的四边形是梯形 ？若存在，求点P 的坐标；若不存在，请说明理由. yA B O x A 二次函数与三角形面积，求点的坐标','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02770','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（延庆一模） 如图，已知平面直角坐标系xOy ，抛物线y= —x2 + bx + c 过点A(4，0) 、B(1，3) . ⑴求该抛物线的解析式，并写出该抛物线的对称轴和顶点坐标； ⑵记该抛物线的对称轴为直线l ，设抛物线上的点P(m，n) 在第四象限，点P 关于直 线l 的对称点为E ，点E 关于y 轴的对称点为F ，若四边形OAPF 的面积为20，求m 、n 的值. y 1 O 1 x 的图象的 x 存在相等面积','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02771','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（上海闵行区九年级下质量调研） 如图，已知：抛物线y = x2 + bx - 3 与x 轴相交于A 、B 两点，与y 轴相交于点C， 并且OA = OC . ⑴求这条抛物线的解析式； ⑵过点C 作CE∥x 轴，交抛物线于点E ，设抛物线的顶点为点D ，试判断△CDE 的形状，并说明理由； ⑶设点M 在抛物线的对称轴l 上，且△MCD 的面积等于△CDE 的面积，请写出点 M 的坐标（无需写出解题步骤）. D 存在面积的比值为几','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02772','math','初中',0,'jkp-0375','short_answer',0.38,'【中】如图，在平面直角坐标系中，直线 与抛物线y = ax2 + bx - 3交于点 A ，B 两点，点A 在x 轴上，点B 的纵坐标为3，点P 是直线AB 下方的抛物线上 的一动点（不与点A ，B 重合），过点P 作x 轴的垂线交直线AB 于点C ，作PD 丄 AB 于点D 。 ⑴求a ，b 及sin上ACP 的值。 （2）设点P 的横坐标为m 。 ①用m 的代数式表示线段PD的长，并求出线段PD长的最大值； ②连接PB，线段PC 把ΔPDB分成两个三角形，是否存在合适的m 值，使这两个三 角形的面积之比为9:10？若存在，直接写出m 的值；若不存在，说明理由。 y A O P A O B y l C x E x G D C B F A B C /、y 存在面积的最值问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02773','math','初中',0,'jkp-0375','short_answer',0.38,'【难】广东省清远市初中毕业生学业考试中考数学试题 如图，抛物线y = (x +1) 2 + k 与x 轴交于A 、B 两点，与y 轴交于点C(0，- 3) . ⑴求抛物线的对称轴及k 的值； ⑵抛物线的对称轴上存在一点P ，使得PA + PC 的值最小，求此时点P 的坐标 ；⑶点M 是抛物线上一动点，且在第三象限. ①当M 点运动到何处时，△AMB 的面积最大？求出△AMB 的最大面积及此时点 M 的坐标； ②当M 点运动到何处时，四边形AMCB 的面积最大？求出四边形AMCB 的最大面 积及此时点M 的坐标. y x 点到点、点到线的距离问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02774','math','初中',0,'jkp-0375','short_answer',0.38,'【难】(点到直线距离+点到点的距离)（广西玉林市中考数学试卷）已知抛物线 y = ax2 - 2ax - 3a (a < 0) 与x 轴交于A 、B 两点（点A 在点B 的左侧），与y 轴交于点C ，点D 为抛物线的顶点. ⑴求A 、B 的坐标； ⑵过点D 作DH ⊥y 轴于点H ，若DH = HC ，求a 的值和直线CD 的解析式； ⑶在第⑵小题的条件下，直线CD 与x 轴交于点E ，过线段OB 的中点N 作NF ⊥x 轴 ，并交直线CD 于点F ，则直线NF 上是否存在点M ，使得点M到直线CD 的距离 等于点M到原点O 的距离？若存在，求出点M 的坐标；若不存在，请说明理由. H C E D F A O N B x 线段和差最值及周长最值问题','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02775','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（线段和最短）（广东省中考数学试卷）已知二次函数y = x2 - 2mx+ m2 -1 . ⑴当二次函数的图象经过坐标原点O(0，0) 时，求二次函数的解析式； ⑵如图，当m = 2 时，该抛物线与y 轴交于点C ，顶点为D ，求C 、D 两点的坐标 ；⑶在⑵的条件下，x 轴上是否存在一点P ，使得PC + PD 最短？若P 点存在，求 出P 点的坐标；若P 点不存在，请说明理由. A y C O x ● D 点动','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02776','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（衡阳市初中毕业学业水平考试数学试卷）如图，已知抛物线经过A(1，0) ， B(0，3) 两点，对称轴是x = -1 . ⑴求抛物线对应的函数关系式； ⑵动点Q 从点O 出发，以每秒1 个单位长度的速度在线段OA 上运动，同时动点M 从O 点出发以每秒3 个单位长度的速度在线段OB 上运动，过点Q 作x 轴的垂线交线 段 AB 于点N ，交抛物线于点P ，设运动的时间为t 秒. ①当t 为何值时，四边形OMPQ 为矩形； ②△AON能否为等腰三角形？若能，求出t 的值；若不能，请说明理由. y B(0,3) P N M A O Q (1,0） x 线动','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02777','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（广西玉林）如图，在平面直角坐标系xOy 中，矩形AOCD 的顶点A 的坐标是（0,4）， 现有两动点P、Q，点P 从点O 出发沿线段OC（不包括端点O，C）以每秒2 个单位长度 的速度，匀速向点C 运动，点Q 从点C 出发沿线段CD（不包括端点C，D）以每秒1 个 单位长度的速度匀速向点D 运动.点P，Q 同时出发，同时停止，设运动时间为t 秒，当 t = 2 秒时PQ = 2 5 . ⑴求点D 的坐标，并直接写出t 的取值范围； ⑵连接AQ 并延长交x 轴于点E,把AE 沿AD 翻折交CD 延长线于点F,连接EF，则 △AEF 的面积S 是否随t 的变化而变化？若变化，求出S 与t 的函数关系式；若不 变化，求出S 的值. ⑶在⑵的条件下，t 为何值时，四边形APQF 是梯形？ 形动','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02778','math','初中',0,'jkp-0375','short_answer',0.38,'【中】（河南省中考）【面积+形动】 如图，在平面直角坐标系中，直线y = 与抛物线 x2 + bx + c 交于A、B两点， 点A 在x 轴上，点B 的横坐标为－8. ⑴求该抛物线的解析式； ⑵点P 是直线AB 上方的抛物线上一动点（不与点A、B 重合），过点P 作x 轴的垂线， 垂足为C，交直线AB 于点D，作PE 丄AB 于点E. ①设△PDE 的周长为l ，点P 的横坐标为x ，求l 关于x 的函数关系式，并求出l 的最 大值； ②连接PA，以PA 为边作图示一侧的正方形APFG.随着点P 的运动，正方形的大小、位 置也随之改变.当顶点F 或G 恰好落在y 轴上时，直接写·出对应的点P 的坐标. y yA A O B 备用图 C E x O A D O F G A C x x E P B y D P F Q 角的三角函数值','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02779','math','初中',0,'jkp-0375','short_answer',0.38,'【易】（奉贤区调研测试）如图，在平面直角坐标系中，点O 为坐标原点，已知点A 的 坐标为(2，2)，点B 、C 在y 轴上，BC = 8 ，AB = AC ，直线AB 与x 轴相交于点D ，⑴求C 、D 的坐标； ⑵求经过A 、C 、D 三点的二次函数解析式 ；⑶求上CAD 的正弦 y A D 求角的度数','','','','imported-junior-pdf','approved','通用','基础');
