INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02792','math','初中',0,'jkp-0167','short_answer',0.38,'【易】（北京二中期中）课本画AOB 的角平分线的方法步骤是： ①以O 为圆心，适当长为半径作弧，交OA于M 点，交OB 于N 点； ②分别以M 、N 为圆心，大于 MN 2 1 的长为半径作弧，两弧在AOB 的内部相交于点C ； ③连接射线OC ．射线OC 就是AOB 的角平分线． 请你说明这样作角平分线的根据是（ ） A O B N M C A．SSS B．SAS C．ASA D．AAS','','','','imported-junior-pdf','approved','通用','基础');
