INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02798','math','初中',0,'jkp-0167','short_answer',0.38,'【易】（北京西城区期末）如图，用三角尺可按下面方法画角平分线：在已知的AOB 的两边上分别取点M 、N ，使  OM ON ，再分别过点M 、N 作OA、OB 的垂线，交 点为P ，画射线OP ．可证得 △ ≌ △POM PON ，OP 平分AOB ．以上依画法证明 △ ≌ △POM PON 根据的是（ ） A．SSS B．SAS C．AAS D．HL A O B N M P','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02799','math','初中',0,'jkp-0167','short_answer',0.38,'【易】（北京东城六校期中）下列命题中正确的是（ ） ①全等三角形对应边相等；②三个角对应相等的两个三角形全等； ③三边对应相等的两个三角形全等；④有两边对应相等的两个三角形全等． A．1 个 B．2 个 C．3 个 D．4 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02800','math','初中',0,'jkp-0167','short_answer',0.38,'【易】（实验学校初一下期末）下列说法正确的有（ ）个 ①两个角和其中一角的对边对应相等的两个三角形全等； ②两条边和其中一边的对角对应相等的两个三角形全等； ③三个角对应相等的两个三角形全等； ④成轴对称的两个图形全等； ⑤三角形的最大角不小于60 度． A．1 B．2 C．3 D．4 四、 全等三角形综合','','','','imported-junior-pdf','approved','通用','基础');
