INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02802','math','初中',0,'jkp-0167','short_answer',0.38,'【中】（昌平区第一学期初二年级期末考试）如图，点E 是等边三角形ABC 内一点，且  EA EB ，△ABC 外一点D 满足  BD AC ，BE 平分DBC ，求BDE 的度数． A B C D E','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02803','math','初中',0,'jkp-0167','short_answer',0.38,'【中】（青海省初中考试）请阅读，完成证明和填空． 九年级数学兴趣小组在学校的“数学长廊”中兴奋地展示了他们小组探究发现的结果，内 容如下： 3 图 2 图 1 图 A B C M N O A B C D M N O A B C D E M O ⑴ 如图1，正三角形ABC 中，在AB 、AC 边上分别取点M 、N ，使  BM AN ，连 接BN 、CM ，发现  BN CM ，且   NOC','','','','imported-junior-pdf','approved','通用','基础');
