INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02805','math','初中',0,'jkp-0167','short_answer',0.38,'⑵ 如图2，正方形ABCD 中，在AB 、BC 边上分别取点M 、N ，使  AM BN ，连接 AN 、DM ，那么  AN ________，且  DON ________． ⑶ 如图3，正五边形ABCDE 中，在AB 、BC 边上分别取点M 、N ，使  AM BN ， 连接AN 、EM ，那么AN =________，且  EON ________． ⑷ 在正n 边形中，对相邻的三边实施同样的操作过程，也会有类似的结论．请大胆猜 测，用一句话概括你的发现： 7/46','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02806','math','初中',0,'jkp-0167','short_answer',0.38,'【中】（永州市2013 年初中毕业学业考试试卷数学试题卷）如图，M 是△ABC 的边BC 的中点，AN 平分BAC ， ⊥ BN AN 于点N ，延长BN 交AC 于点D ，连接MN ，已 知  AB 10 ，  BC 15 ，  MN 3 A B D M N C 1 2 ⑴ 求证：  BN DN ⑵ 求△ABC 的周长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02807','math','初中',0,'jkp-0167','short_answer',0.38,'【中】（海口市中考题）在△ABC 中，    ACB AC BC 90 , ，直线MN 经过C 点， 且  AD MN 于D ，  BE MN 于E ． ⑴ 当直线MN 绕点C 旋转到图①的位置时，求证：   DE AD BE ； ⑵ 当直线MN 绕点C 旋转到图②的位置时，求证：   DE AD BE ； ⑶ 当直线MN 绕点C 旋转到图③的位置时，试问： 、 、 DE AD BE 有怎样的等量关系？ 请写出这个等量关系，并加以证明． 8/46','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02808','math','初中',0,'jkp-0167','short_answer',0.38,'【难】（东营）⑴如图⑴，已知：在△ABC 中，   BAC 90 ，  AB AC ，直线m 经过 点A ， 线 直  BD m ， 线 直  CE m ，垂足分别为点 、 D E ．证明:   DE BD CE ． ⑵ 如图⑵，将⑴中的条件改为：在△ABC 中，  AB AC ， 、 、 D A E 三点都在直线m 上， 并且有    BDA AEC BAC ，其中为任意锐角或钝角．请问结论   DE BD CE 是否成立?如成立，请你给出证明;若不成立，请说明理由． ⑶ 拓展与应用：如图⑶，、 D E 是 、 、 D A E 三点所在直线m 上的两动点（ 、 、 D A E 三 点互不重合），点F 为BAC 平分线上的一点，且△ABF 和△ACF 均为等边三角形， 连接 、 BD CE ，若   BDA AEC BAC ，试判断△DEF 的形状．','','','','imported-junior-pdf','approved','通用','基础');
