INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02862','math','初中',0,'jkp-0278','short_answer',0.38,'给出下面四个命题：①对角线相等的四边形是矩形；②对角线互相垂直的四边形是菱形； ③有一个角是直角且对角线互相平分的四边形是矩形；④菱形的对角线的平方和等于边 长平方的4 倍．其中所有正确的命题有 （填入正确命题的序号）','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02863','math','初中',0,'jkp-0278','short_answer',0.38,'如图，已知四边形ABCD 是平行四边形，下列结论中不正确的是( ) A ．当AB = BC 时，它是菱形 B．当AC = BD 时，它是正方形 C ．当上ABC = 90 时，它是矩形 D．当AC 丄BD 时，它是菱形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02864','math','初中',0,'jkp-0278','short_answer',0.38,'如图，菱形ABCD 中，∠B = 60。，AB = 4 ，则以AC 为边长的正方形ACEF 的周长 为( ) A．14 B．15 C．16 D．17','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02865','math','初中',0,'jkp-0278','short_answer',0.38,'如图，在矩形ABCD 中，AD = 2AB，点M 、N 分别在边AD 、BC 上，连接BM 、DN ． 若AM 四边形MBND 是菱形，则MD 等于( ) 。 3 A ．8 B. 2 3 C. 3 5 D. 4 5','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02866','math','初中',0,'jkp-0278','short_answer',0.38,'如图，。ABCD 的顶点B 在矩形AEFC 的边EF 上，点B 与点E ，F 不重合，若△ACD 的面积为3，则图中阴影部分两个三角形的面积和为 . D A C E B F','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02867','math','初中',0,'jkp-0278','short_answer',0.38,'下列说法中，正确的个数是( ) ⑴只用一种图形能够密铺的有三角形、四边形、正六边形 ⑵菱形的对角线互相垂直平分 ⑶矩形有而平行四边形没有的性质是对角线相等 ⑷平移和旋转都不改变图形的大小和形状，只是位置发生了变化 ⑸一组对边平行，另一组对边相等的四边形是平行四边形 A．2 个 B．3 个 C．4 个 D．5 个','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02868','math','初中',0,'jkp-0278','short_answer',0.38,'如图，已知平行四边形ABCD 中，∠DBC = 45。，DE 丄BC 于E ，BF 丄CD 于F ，DE 、BF 相交于H ，BF 、AD 的延长线相交于G ，下面结论： ①AB = BH ；②∠A = ∠BHE ；③BH = HG ；④DB = 2BE ； 其中正确的结论有 (填序号). A D H F B E C','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02869','math','初中',0,'jkp-0278','short_answer',0.38,'如图①,在正方形ABCD 中，P 是对角线AC 上的一点，点E 在BC 的延长线上，且 PE = PB . ⑴求证：△BCP ≌△DCP ；⑵求证：上DPE = 上ABC ； ⑶把正方形ABCD 改为菱形，其它条件不变（如图②), 若上ABC = 58。，则上DPE = 度. P D C 图① E A P C 图② G A E B B D','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02870','math','初中',0,'jkp-0278','short_answer',0.38,'在矩形ABCD 中，将点A 翻折到对角线BD 上的点M 处，折痕BE 交AD 于点E ．将 点C 翻折到对角线BD 上的点N 处，折痕DF 交BC 于点F . （1）求证：四边形BFDE 为平行四边形； （2）若四边形BFDE 为菱形，且AB = 2 ，求BC 的长. A B E M N F C . 二、判定及综合','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02871','math','初中',0,'jkp-0278','short_answer',0.38,'下列说法中，错误的是( ) A ．邻边相等菱形是正方形 B ．两条对角线互相垂直且平分的四边形是菱形 C．四个角都相等的四边形是矩形 D ．一组对边平行且相等的四边形是平行四边形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02872','math','初中',0,'jkp-0278','short_answer',0.38,'如图，过矩形ABCD 的四个顶点作对角线AC 、BD 的平行线，分别相交于E 、F 、G 、H 四点，则四边形EFGH 为( ) H A D G E B C F A ．平行四边形 B．矩形 C．菱形 D．正方形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02873','math','初中',0,'jkp-0278','short_answer',0.38,'如图，在平行四边形ABCD 中，E 为BC 边上的一点，连结AE 、BD 且AE = AB . （1）求证：上ABE = 上EAD； （2）若上AEB = 2上ADB ，求证：四边形ABCD 是菱形. A D C D E B','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02874','math','初中',0,'jkp-0278','short_answer',0.38,'如图，在矩形ABCD 中，E、F 分别是边AB 、CD 的中点，连接AF ，CE . A E B D F C ⑴求证：△BEC ≌△DFA； ⑵求证：四边形AECF 是平行四边形.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02875','math','初中',0,'jkp-0278','short_answer',0.38,'在平行四边形ABCD 中，点E、F 分别在AB、CD 上，且AE = CF . （1）求证：△ADE 三△CBF； （2）若DF = BF ，求证：四边形DEBF 为菱形.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02876','math','初中',0,'jkp-0278','short_answer',0.38,'直角梯形ABCD 中，AB∥DC AD 的中点，联结EF 、EC 、 AB 丄BC , BF 、CF 上A = 60O AB = 2CD , , , E 、F 分别为AB 、 （1）证明四边形AECD 为平行四边形 （2）若CD = 2 ，求BC 的长. （3）求证：△CFE ≌△CBE D F E','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02877','math','初中',0,'jkp-0278','short_answer',0.38,'【中】(大庆地区2013 年中考数学模拟试题)已知△ABC 是等边三角形，点D 、F 分别 在边BC 、AC 上，且DF ∥AB ，过点A 作平行于BC 的直线与DF 的延长线交于点E ，连结CE 、BF . （1）求证：△ABF≌△ACE； （2）若D 是BC 的中点，判断△DCE 的形状，并说明理由. A E F B D C A C B','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02878','math','初中',0,'jkp-0278','short_answer',0.38,'已知矩形纸片ABCD 中，AB = 1 ，BC = 2 ，将该纸片叠成一个平面图形，折痕EF 不经过A 点（E 、F 是该矩形边界上的点），折叠后点A 落在A’ 处，给出以下判断 ：- ⑴当四边形A’CDF 为正方形时， ； ⑵当EF = 2 时，四边形A’CDF 为正方形； ⑶当EF = 5 时，四边形BA’CD 为等腰梯形 ；⑷当四边形BA’CD 为等腰梯形时，EF =','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02879','math','初中',0,'jkp-0278','short_answer',0.38,'其中正确的是 （把所有正确结论序号都填在横线上）.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02880','math','初中',0,'jkp-0278','short_answer',0.38,'如图所示，在Rt△ABC 中，上ABC = 90。。将Rt△ABC 绕点C 顺时针方向旋转60。 得到△DEC ，点E 在AC 上，再将Rt△ABC 沿着AB 所在直线翻转180。得到 △ABF 连接AD 。 ⑴求证：四边形AFCD 是菱形； ⑵连接BE 并延长交AD 于G ，连接CG ，请问：四边形ABCG 是什么特殊平行四 边形？为什么？ G E F B C','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02881','math','初中',0,'jkp-0278','short_answer',0.38,'如图，在直角梯形ABCD 中，AD∥BC ，AD 丄DC ，点A 关于对角线BD 的对称点F 刚 好落在腰DC 上，连接AF 交BD 于点E ，AF 的延长线与BC 的延长线交于点G ， M ，N 分别是 BG ，DF 的中点. ⑴求证：四边形EMCN 是矩形； ⑵若AD = 2 ， S梯形ABCD = 求矩形EMCN 的长和宽. A D D A B M C G N E','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02882','math','初中',0,'jkp-0278','short_answer',0.38,'已知：在矩形ABCD 中，AB = 10 ，BC = 12 ，四边形EFGH 的三个顶点E ，F ，H 分别在矩形ABCD 边AB ，BC ，DA 上，AE = 2 . ⑴如图①,当四边形EFGH 为正方形时，求△GFC 的面积； ⑵如图②,当四边形EFGH 为菱形，且BF = a 时，求△GFC 的面积（用含α 的代 数式表示）； ⑶在⑵的条件下，△GFC 的面积能否等于2？请说明理由.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02883','math','初中',0,'jkp-0278','short_answer',0.38,'已知：如图，在△ABC 中，AB = AC ，AD 丄BC ，垂足为点D ，AN 是上CAM 的平 分线，CE 丄AN，垂足为点E . ⑴求证：四边形ADCE 为矩形； ⑵当△ABC 满足什么条件时，四边形ADCE 是一个正方形？并给出证明. M A B D C N E','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02884','math','初中',0,'jkp-0278','short_answer',0.38,'已知：如图，在平行四边形ABCD 中，E，F 分别为边AB，CD 的中点，BD 是对角线 ，AG∥DB 交CB 的延长线于G ．若四边形BEDF 是菱形，则四边形AGBD 是什么 特殊四边形？并证明你的结论. D C A E F B G','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02885','math','初中',0,'jkp-0278','short_answer',0.38,'如图⑴, Rt△ABC 中，上ACB = 90。，中线BE、CD 相交于点O，点F、G 分别是OB 、OC 的中点. ⑴求证：四边形DFGE 是平行四边形； ⑵如果把Rt△ABC 变为任意△ABC ，如图⑵, 通过你的观察，第⑴问的结论是否仍 然成立？（不用证明）； ⑶在图⑵中，试想：如果拖动点A，通过你的观察和探究，在什么条件下？四边形 DFGE 是矩形，并给出证明； ⑷在第⑶问中，试想：如果拖动点A，是否存在四边形DFGE 是正方形或菱形？如果 存在，画出相应的图形（不用证明）. A D E O F G i B C 图1 A E D O F G B 图2 C 三、中位线','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02886','math','初中',0,'jkp-0278','short_answer',0.38,'【易】（无锡市中考）如图，在Rt△ABC 中，上ACB = 90O，D 、E 、F 分别是AB CA 的中点，若CD = 5cm，则EF = cm . A C E ● D B 、BC、 F','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02887','math','初中',0,'jkp-0278','short_answer',0.38,'【中】（福建龙岩中考）如图，在△ABC 中，点D 、E 、F 分别是AB 、BC 、CA 的 中点，若△ABC 的周长为12cm，则△DEF 的周长是 cm . C D E 四、中点四边形','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02888','math','初中',0,'jkp-0278','short_answer',0.38,'下列说法正确的是( ) ①顺次连接梯形各边中点，所得的四边形是平行四边形 ②顺次连接平行四边形各边中点，所得的四边形是矩形 ③顺次连接对角线相等的四边形各边中点，所得的四边形是菱形 ④顺次连接对角线互相垂直的四边形各边中点，所得的四边形是矩形 A. ①②③ B. ②③④ C. ①③④ D. ①②③④','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02889','math','初中',0,'jkp-0278','short_answer',0.38,'如图，在四边形ABCD 中，E 为AB 上一点，△ADE 和△BCE 都是等边三角形，AB 、BC、CD、DA 的中点分别为P、Q、M、N，试判断四边形PQMN 为怎样的四边形 ，并证明你的结论. D M C Q A 五、剪拼','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02890','math','初中',0,'jkp-0278','short_answer',0.38,'将一张四边形纸片沿两组对边的中点连线剪开，得到四张小纸片，如图3 所示．用这四 张小纸片一定可拼成一个( ) A．梯形 B．矩形 C．菱形 D．平行四边形 P E N B A B F','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02891','math','初中',0,'jkp-0278','short_answer',0.38,'如图1，若将△AOB 绕点O 逆时针旋转180。得到△COD ，则△AOB ≌ OD ．此时 ，我们称△AOB 与△COD 为“8 字全等型”．借助“8 字全等型”我们可以解决一些图形 的分割与拼接问题．例如：图2 中，△ABC 是锐角三角形且AC > AB，点E 为AC 中 点，F 为BC 上一点且BF≠FC（F 不与B ．C 重合），沿EF 将其剪开，得到的两 块图形恰能拼成一个梯形. D C O A B A ② E ① ② B F C 图1 图2 请分别按下列要求用直线将图2 中的△ABC 重新进行分割，画出分割线及拼接后的 图形. ⑴在图3 中将△ABC 沿分割线剪开，使得到的两块图形恰能拼成一个平行四边形； ⑵在图4 中将△ABC 沿分割线剪开，使得到的三块图形恰能拼成一个矩形，且其中 的两块为直角三角形； ⑶在图5 中将△ABC 沿分割线剪开，使得到的三块图形恰能拼成一个矩形，且其中 的一块为锐角三角形. A A A B C B C B C 图3 图4 图5','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02892','math','初中',0,'jkp-0278','short_answer',0.38,'阅读下列材料: 将图1 的平行四边形用一定方法可分割成面积相等的八个四边形，如图2，再将图2 中 的八个四边形适当组合拼成两个面积相等且不全等的平行四边形．（要求：无缝隙且不 重叠） 请你参考以上做法解决以下问题： ⑴将图4 的平行四边形分割成面积相等的八个三角形； ⑵将图5 的平行四边形用不同于⑴的分割方案，分割成面积相等的八个三角形，再将这 八个三角形适当组合拼成两个面积相等且不全等的平行四边形，类比图2，图3，用数 字1 至8 标明. 1 2 3 4 \ 1\ 2\ 3\ 4 5 6 5 6 7 8 7 8 图1 图2 图3 图4 图5 【','','','','imported-junior-pdf','approved','通用','基础');
