INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02898','math','初中',0,'jkp-0409','short_answer',0.38,'从美学角度来说，人的上身长不下身长乊比为黄金比时，可以给人一种协调 的美感．某女老师上身长约61.80cm ，下身长约93.00cm ，她要穹约 cm 的高跟鞋才能达到黄金比的美感效果（精确到0.01cm ）.','','','','imported-junior-pdf','approved','通用','基础');
