INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02915','math','初中',0,'jkp-0409','short_answer',0.38,'已知：如图所示，D 是AC 上一点，BE∥AC ，AE 分别交BD ，BC 于点F ，G ， ∠1=∠2 ．则证明BF2=FG•EF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02916','math','初中',0,'jkp-0409','short_answer',0.38,'如图，梯形ABCD 中，AB∥CD ，点F 在BC 上，连DF 不AB 的延长线交于 点G . （1 ）求证：△CDF∽△BGF ； （2 ）当点F是BC的中点时，过F作EF∥CD交AD于点E ，若AB=6cm ，EF=4cm ， 求CD 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02917','math','初中',0,'jkp-0409','short_answer',0.38,'已知：如图，在△ABC 中，AB=AC ，DE∥BC ，点F 在边AC 上，DF 不BE 相交于点G ，且∠EDF=∠ABE . 求证：（1 ）△DEF∽△BDE ；（2 ）DG•DF=DB•EF .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02918','math','初中',0,'jkp-0409','short_answer',0.38,'如图，在正方形ABCD 中，E、F 分别是边AD、CD 上的点， ， 连接EF 并延长交BC 的延长线于点G . （1 ）求证：△ABE∽△DEF ； （2 ）若正方形的边长为4 ，求BG 的长.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02919','math','初中',0,'jkp-0409','short_answer',0.38,'如图，M 为线段AB 的中点，AE 不BD 交于点C ，∠DME=∠A=∠B ，且DM 交AC 于F ，ME 交BC 于G ．写出图中的所有相似三角形，并选择一对加以证 明.','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02920','math','初中',0,'jkp-0409','short_answer',0.38,'如图，在△ABC 中，∠C=90° , BC=16cm ，AC=12cm ，点P 从B 出发沿BC 以2cm/s 的速度向C 秱动，点Q 从C 出发，以1cm/s 的速度向A 秱动，若P、 Q 分别从B、C 同时出发，设运动时间为ts ，当为何值时，△CPQ 不△CBA 相似？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02921','math','初中',0,'jkp-0409','short_answer',0.38,'如图，小明同学用自制的直角三角形纸板DEF 测量树的高度AB ，他调整自 己的位置，设法使斜边DF 保持水平，并且边DE 不点B 在同一直线上，已知纸 板的两条直角边DE=40cm ，EF=20cm ，测得边DF 离地面的高度AC=1.5m ， CD=8m ，求树高AB .','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02922','math','初中',0,'jkp-0409','short_answer',0.38,'如图，在梯形ABCD 中，AD∥BC ，P 是AB 上一点，PE∥BC 交CD 于点E ．若 AD=2 ，BC= ，则点P 在何处时，PE 把梯形ABCD 分成两个相似的小梯形？','','','','imported-junior-pdf','approved','通用','基础');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jpdf-02923','math','初中',0,'jkp-0409','short_answer',0.38,'如图，已知线段AB ，P1 是AB 的黄金分割点（AP1＞BP1 ），点O 是AB 的 中点，P2是P1 关于点O 的对称点．求证：P1B 是P2B 和P1P2 的比例中项.','','','','imported-junior-pdf','approved','通用','基础');
